  app.get("/api/auth/me", authenticateToken, async (req: any, res) => {
    try {
      const authUser = req.user;
      if (!authUser || !authUser.id) {
        return res.status(401).json({ success: false, error: "Authentication session expired" });
      }

      const adminClient = getSupabaseAdmin();
      const rawId = String(authUser.id);
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawId);

      let dbUser: any = null;
      if (isUuid) {
        const { data: byAuthUid } = await adminClient
          .from('users')
          .select('*, schools(*)')
          .eq('auth_user_id', rawId)
          .maybeSingle();
        if (byAuthUid) dbUser = byAuthUid;
      } else {
        const { data: byId } = await adminClient
          .from('users')
          .select('*, schools(*)')
          .eq('id', authUser.id)
          .maybeSingle();
        if (byId) dbUser = byId;
      }

      if (!dbUser && authUser.auth_user_id) {
        const { data: byAuthUid2 } = await adminClient
          .from('users')
          .select('*, schools(*)')
          .eq('auth_user_id', authUser.auth_user_id)
          .maybeSingle();
        if (byAuthUid2) dbUser = byAuthUid2;
      }

      if (!dbUser && authUser.email) {
        const { data: byEmail } = await adminClient
          .from('users')
          .select('*, schools(*)')
          .ilike('email', authUser.email)
          .maybeSingle();
        if (byEmail) dbUser = byEmail;
      }

      if (!dbUser) {
        return res.json({
          success: true,
          user: {
            id: authUser.id,
            auth_user_id: authUser.auth_user_id || authUser.sub || null,
            username: authUser.username,
            fullName: authUser.fullName || authUser.username,
            email: authUser.email,
            role: authUser.role,
            schoolId: authUser.school_id || authUser.schoolId,
            school_id: authUser.school_id || authUser.schoolId,
            rlsAuthenticated: true,
            status: 'active'
          }
        });
      }

      const userStatus = (dbUser.status || 'active').toLowerCase();
      if (userStatus === 'suspended' || userStatus === 'inactive' || userStatus === 'disabled') {
        return res.status(403).json({
          success: false,
          error: "Your account is currently inactive or suspended. Please contact administrator."
        });
      }

      if (!dbUser.auth_user_id) {
        const linked = await ensureUserSupabaseAuthIdentity({
          userId: dbUser.id,
          email: dbUser.email,
          username: dbUser.username,
          fullName: dbUser.full_name || dbUser.username,
          role: dbUser.role || 'teacher',
          schoolId: dbUser.school_id,
          issueSession: false
        });
        if (linked.authUserId) {
          dbUser.auth_user_id = linked.authUserId;
        }
      }

      const userObj = {
        id: dbUser.id,
        auth_user_id: dbUser.auth_user_id || authUser.auth_user_id || null,
        username: dbUser.username,
        fullName: dbUser.full_name || dbUser.fullName || dbUser.username,
        email: dbUser.email,
        phone: dbUser.phone,
        role: dbUser.role || 'teacher',
        status: dbUser.status || 'active',
        schoolId: dbUser.school_id,
        school_id: dbUser.school_id,
        rlsAuthenticated: true,
        createdAt: dbUser.created_at ? Number(dbUser.created_at) : Date.now(),
        lastLogin: dbUser.last_login ? Number(dbUser.last_login) : null
      };

      recordUserSessionHeartbeat({
        userId: userObj.id,
        authUserId: userObj.auth_user_id,
        username: userObj.username,
        fullName: userObj.fullName,
        email: userObj.email,
        role: userObj.role,
        schoolId: userObj.school_id,
        schoolName: dbUser.schools?.name || (userObj.role === 'creator' || userObj.role === 'super_admin' ? 'Platform Global Scope' : undefined),
        authStatus: 'Session Active',
        loginTimestamp: userObj.lastLogin || Date.now(),
        isOnline: true
      });

      return res.json({
        success: true,
        user: userObj,
        school: dbUser.schools || null
      });
    } catch (err: any) {
      console.error("Error in GET /api/auth/me:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Setup 2FA for user
  app.post("/api/auth/2fa/setup", authenticateToken, async (req: any, res) => {
    try {
      const authUser = req.user;
      const schoolId = authUser?.school_id || authUser?.organization_id;

      // Only admins and super admins can enable 2FA
      const userRole = (authUser.role || '').toLowerCase();
      if (userRole !== 'admin' && userRole !== 'super_admin' && userRole !== 'creator') {
        return res.status(403).json({ success: false, error: "2FA is only available for administrators" });
      }

      const result = await setupTwoFactorAuth({
        userId: authUser.id,
        schoolId
      });

      if (!result.success) {
        return res.status(400).json({ success: false, error: result.error });
      }

      // Generate QR code as data URL
      let qrCodeDataURL = '';
      try {
        qrCodeDataURL = await generateQRCodeDataURL(result.qrCodeUri!);
      } catch (qrError) {
        console.error('QR code generation failed:', qrError);
      }

      // Audit log for 2FA setup initiation
      createAuditLog({
        userId: authUser.id,
        schoolId,
        action: AuditAction.SYSTEM_CONFIG_CHANGED,
        entityType: EntityType.USER,
        entityId: String(authUser.id),
        details: { action: '2fa_setup_initiated' },
        ipAddress: extractIpAddress(req)
      }).catch(err => console.error('Audit log failed:', err));

      return res.json({
        success: true,
        secret: result.secret,
        qrCodeDataURL,
        backupCodes: result.backupCodes
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

