  // Change Password Endpoint for Authenticated Users (Requires current password verification)
  app.post("/api/auth/change-password", authenticateToken, async (req: any, res) => {
    try {
      const authUser = req.user;
      const { currentPassword, newPassword } = req.body || {};

      if (!currentPassword || !newPassword) {
        return res.status(400).json({ success: false, error: "Both current password and new password are required" });
      }

      if (newPassword.length < 4) {
        return res.status(400).json({ success: false, error: "New password must be at least 4 characters long" });
      }

      const adminClient = getSupabaseAdmin();
      const rawId = String(authUser.id || '');
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawId);

      let dbUser: any = null;
      if (isUuid) {
        const { data: byUid } = await adminClient
          .from('users')
          .select('id, auth_user_id, username, email, school_id')
          .eq('auth_user_id', rawId)
          .maybeSingle();
        if (byUid) dbUser = byUid;
      } else if (rawId) {
        const { data: byId } = await adminClient
          .from('users')
          .select('id, auth_user_id, username, email, school_id')
          .eq('id', authUser.id)
          .maybeSingle();
        if (byId) dbUser = byId;
      }

      if (!dbUser && authUser.auth_user_id) {
        const { data: byAuthUid } = await adminClient
          .from('users')
          .select('id, auth_user_id, username, email, school_id')
          .eq('auth_user_id', authUser.auth_user_id)
          .maybeSingle();
        if (byAuthUid) dbUser = byAuthUid;
      }

      if (!dbUser && authUser.email) {
        const { data: byEmail } = await adminClient
          .from('users')
          .select('id, auth_user_id, username, email, school_id')
          .ilike('email', authUser.email)
          .maybeSingle();
        if (byEmail) dbUser = byEmail;
      }

      if (!dbUser) {
        return res.status(404).json({ success: false, error: "User record not found in database" });
      }

      let canonicalEmail = String(dbUser.email || '').trim().toLowerCase();
      let existingUserMeta: Record<string, any> = {};
      if (dbUser.auth_user_id && adminClient.auth?.admin?.getUserById) {
        try {
          const { data: au } = await adminClient.auth.admin.getUserById(dbUser.auth_user_id);
          if (au?.user?.email) {
            canonicalEmail = au.user.email.trim().toLowerCase();
          }
          if (au?.user?.user_metadata) {
            existingUserMeta = au.user.user_metadata;
          }
        } catch {}
      }

      let isCurrentValid = false;
      if (canonicalEmail) {
        try {
          const verifyClient = createAuthenticatedSupabaseClient();
          const { data: signRes, error: signErr } = await verifyClient.auth.signInWithPassword({
            email: canonicalEmail,
            password: String(currentPassword)
          });
          if (!signErr && signRes?.user?.id) {
            isCurrentValid = true;
          }
        } catch {}
      }

      // Also allow the school's active license key as currentPassword when changing from initial license-key activation
      if (!isCurrentValid && (dbUser.school_id || authUser.school_id)) {
        try {
          const targetSchoolId = dbUser.school_id || authUser.school_id;
          const { data: licRow } = await adminClient
            .from('school_licenses')
            .select('license_key')
            .eq('school_id', targetSchoolId)
            .maybeSingle();
          if (
            licRow?.license_key &&
            String(currentPassword).trim().toUpperCase() === String(licRow.license_key).trim().toUpperCase()
          ) {
            isCurrentValid = true;
          }
        } catch {}
      }

      if (!isCurrentValid) {
        createAuditLog({
          userId: authUser.id,
          schoolId: authUser.school_id,
          action: AuditAction.PASSWORD_CHANGE,
          entityType: EntityType.USER,
          entityId: String(authUser.id),
          details: { success: false, reason: 'invalid_current_password' },
          ipAddress: extractIpAddress(req)
        }).catch(err => console.error('Audit log failed:', err));
        
        return res.status(400).json({ success: false, error: "Current password does not match our records." });
      }

      if (!dbUser.auth_user_id) {
        return res.status(400).json({ success: false, error: "User account is not linked to a Supabase Auth identity." });
      }

      const { error: authUpdErr } = await adminClient.auth.admin.updateUserById(dbUser.auth_user_id, {
        password: String(newPassword),
        user_metadata: {
          ...existingUserMeta,
          must_change_password: false
        }
      });

      if (authUpdErr) {
        return res.status(400).json({ success: false, error: authUpdErr.message });
      }

      const { error: updateErr } = await adminClient
        .from('users')
        .update({
          email: canonicalEmail || dbUser.email,
          updated_at: Date.now()
        })
        .eq('id', dbUser.id);

      if (updateErr) {
        return res.status(500).json({ success: false, error: updateErr.message });
      }

      // Audit log for successful password change
      createAuditLog({
        userId: authUser.id,
        schoolId: authUser.school_id,
        action: AuditAction.PASSWORD_CHANGE,
        entityType: EntityType.USER,
        entityId: String(authUser.id),
        details: { success: true },
        ipAddress: extractIpAddress(req)
      }).catch(err => console.error('Audit log failed:', err));

      return res.json({
        success: true,
        message: "Password updated successfully."
      });
    } catch (err: any) {
      console.error("Error in POST /api/auth/change-password:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Role Permissions Matrix Endpoint
  app.get("/api/auth/permissions", authenticateToken, async (req: any, res) => {
    try {
      const userRole = req.user?.role || req.query.role || 'teacher';
      return res.json({
        success: true,
        currentRole: userRole,
        roles: [
          { role: 'admin', name: 'School Administrator / Headmaster', category: 'School Administration' },
          { role: 'headteacher', name: 'Head Teacher / Vice Principal', category: 'School Administration' },
          { role: 'teacher', name: 'Teacher / Instructor', category: 'Instructional Staff' },
          { role: 'accountant', name: 'Bursar / Accountant', category: 'Finance' },
          { role: 'student', name: 'Student', category: 'Community' },
          { role: 'parent', name: 'Parent / Guardian', category: 'Community' }
        ]
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Helper to resolve canonical tenant school record and display username for User Management
  async function resolveTenantSchoolForUsers(req: any, explicitSchoolId?: string | null, explicitSchoolName?: string | null) {
    const scope = resolveTenantAccessScope(req, explicitSchoolId);
    if (scope.unauthorized) {
      throw new TenantAccessError(scope.error || 'Authentication required.', 401);
    }
    if (scope.forbidden) {
      throw new TenantAccessError(scope.error || 'Access denied: Cross-tenant access is forbidden.', 403);
    }

    const adminClient = getSupabaseAdmin();
    const rawCandidate = String(
      scope.schoolId ||
      explicitSchoolId ||
      req.user?.school_id ||
      req.user?.schoolId ||
      ''
    ).trim();

    const rawNameCandidate = String(
      (scope.isSuper ? (explicitSchoolName || req.body?.schoolName || req.body?.school_name) : '') ||
      req.user?.schoolName ||
      ''
    ).trim();

    const isPlaceholderCandidate = (val: string) => {
      const v = String(val || '').trim().toLowerCase();
      return !v || v === '00000000-0000-0000-0000-000000000001' || v === 'school-sphere-academy' || v === 'default' || v === 'school sphere academy';
    };

    const effectiveIdCandidate = isPlaceholderCandidate(rawCandidate) ? '' : rawCandidate;
    const effectiveNameCandidate = isPlaceholderCandidate(rawNameCandidate) ? '' : rawNameCandidate;
    const targetLower = effectiveIdCandidate.toLowerCase();
    const nameLower = effectiveNameCandidate.toLowerCase();

    // 1. Check Supabase schools table directly
    try {
      if (effectiveIdCandidate) {
        const { data: byId } = await adminClient.from('schools').select('*').eq('id', effectiveIdCandidate).maybeSingle();
        if (byId?.id) {
          return {
            rawSchoolId: rawCandidate || String(byId.id),
            schoolId: String(byId.id),
            schoolName: String(byId.name || effectiveNameCandidate || 'Assigned School'),
            schoolSlug: String(byId.slug || (byId.name || '').toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school')
          };
        }
        const { data: bySlug } = await adminClient.from('schools').select('*').eq('slug', targetLower).maybeSingle();
        if (bySlug?.id) {
          return {
            rawSchoolId: rawCandidate || String(bySlug.id),
            schoolId: String(bySlug.id),
            schoolName: String(bySlug.name || effectiveNameCandidate || 'Assigned School'),
            schoolSlug: String(bySlug.slug || 'school')
          };
        }
      }
    } catch {}

    // 2. Check SECURITY DEFINER get_schools_directory RPC
    let dirSchoolsList: any[] = [];
    try {
      const { data: dirSchools } = await adminClient.rpc('get_schools_directory');
      if (Array.isArray(dirSchools) && dirSchools.length > 0) {
        dirSchoolsList = dirSchools;
        const dirMatch = dirSchools.find((s: any) =>
          (targetLower && (
            String(s.id || '').toLowerCase() === targetLower ||
            String(s.slug || '').toLowerCase() === targetLower ||
            String(s.name || '').toLowerCase() === targetLower
          )) ||
          (nameLower && (
            String(s.name || '').toLowerCase() === nameLower ||
            String(s.slug || '').toLowerCase() === nameLower
          ))
        );
        if (dirMatch?.id) {
          return {
            rawSchoolId: rawCandidate || String(dirMatch.id),
            schoolId: String(dirMatch.id),
            schoolName: String(dirMatch.name || effectiveNameCandidate || 'Assigned School'),
            schoolSlug: String(dirMatch.slug || (dirMatch.name || '').toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school')
          };
        }
      }
    } catch {}

    // 3. Check fallback schools & generated licenses
    const fbSchools = getFromFallback('schools');
    const fbMatch = fbSchools.find((s: any) =>
      (targetLower && (
        String(s.id || '').toLowerCase() === targetLower ||
        String(s.slug || '').toLowerCase() === targetLower ||
        String(s.name || s.schoolName || '').toLowerCase() === targetLower
      )) ||
      (nameLower && String(s.name || s.schoolName || '').toLowerCase() === nameLower)
    );
    if (fbMatch?.id && !isPlaceholderCandidate(String(fbMatch.id))) {
      const sName = String(fbMatch.name || fbMatch.schoolName || effectiveNameCandidate || 'Assigned School');
      return {
        rawSchoolId: rawCandidate || String(fbMatch.id),
        schoolId: String(fbMatch.id),
        schoolName: sName,
        schoolSlug: String(fbMatch.slug || sName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school')
      };
    }

    const allLicenses = getGeneratedLicenses();
    const licMatch = allLicenses.find((l: any) =>
      (targetLower && (
        String(l.school_id || '').toLowerCase() === targetLower ||
        String(l.schoolName || '').toLowerCase() === targetLower
      )) ||
      (nameLower && String(l.schoolName || '').toLowerCase() === nameLower)
    );
    if (licMatch && licMatch.school_id && !isPlaceholderCandidate(String(licMatch.school_id))) {
      const sName = String(licMatch.schoolName || effectiveNameCandidate || 'Assigned School');
      const sSlug = sName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school';
      return {
        rawSchoolId: rawCandidate || String(licMatch.school_id),
        schoolId: String(licMatch.school_id),
        schoolName: sName,
        schoolSlug: sSlug
      };
    }

    // 4. If candidate was empty or synthetic placeholder (e.g. 00000000-0000-0000-0000-000000000001), select the active school from Supabase directory
    if (dirSchoolsList.length > 0 && !effectiveIdCandidate && !effectiveNameCandidate) {
      const defaultDirSchool =
        dirSchoolsList.find((s: any) => s.status === 'active' && s.license_id) ||
        dirSchoolsList.find((s: any) => s.status === 'active') ||
        dirSchoolsList[0];
      if (defaultDirSchool?.id) {
        return {
          rawSchoolId: rawCandidate || String(defaultDirSchool.id),
          schoolId: String(defaultDirSchool.id),
          schoolName: String(defaultDirSchool.name || 'Assigned School'),
          schoolSlug: String(defaultDirSchool.slug || (defaultDirSchool.name || '').toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school')
        };
      }
    }

    // 5. Check Supabase settings schools_registry & active license statuses
    try {
      const regSchools = await readSupabaseSettingList('schools_registry');
      if (Array.isArray(regSchools) && regSchools.length > 0) {
        const regMatch = regSchools.find((s: any) =>
          (targetLower && (
            String(s.id || '').toLowerCase() === targetLower ||
            String(s.slug || '').toLowerCase() === targetLower ||
            String(s.name || s.schoolName || '').toLowerCase() === targetLower
          )) ||
          (nameLower && String(s.name || s.schoolName || '').toLowerCase() === nameLower)
        ) || (!targetLower && !nameLower ? regSchools[0] : null);
        if (regMatch && regMatch.id && !isPlaceholderCandidate(String(regMatch.id))) {
          const sName = String(regMatch.name || regMatch.schoolName || effectiveNameCandidate || 'Assigned School');
          const sSlug = String(regMatch.slug || sName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school');
          return {
            rawSchoolId: rawCandidate || String(regMatch.id),
            schoolId: String(regMatch.id),
            schoolName: sName,
            schoolSlug: sSlug
          };
        }
      }
    } catch {}

    const activeStatuses = getGeneratedLicenses();
    const activeLic = activeStatuses.find((st: any) => st && (st.used || st.status === 'active') && (st.school_id || st.schoolName));
    const fallbackName = effectiveNameCandidate || activeLic?.schoolName || (dirSchoolsList[0]?.name) || 'SchoolSphere Academy';
    const fallbackSlug = fallbackName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'school';

    // If we have a specific school name that is not yet in public.schools, ensure it exists in Supabase via sync_school_license RPC
    if (effectiveNameCandidate) {
      try {
        const detKey = generateDeterministicSchoolKey(effectiveIdCandidate || null, effectiveNameCandidate, 'Standard');
        const { data: syncRes } = await adminClient.rpc('sync_school_license', {
          p_school_name: effectiveNameCandidate.toUpperCase(),
          p_license_key: detKey,
          p_tier: 'Standard',
          p_email: `admin@${fallbackSlug}.edu.gh`,
          p_phone: '+233 24 000 0000',
          p_address: 'Ghana',
          p_duration_months: '12',
          p_expiry_date: null,
          p_modules: ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          p_status: 'active'
        });
        if (syncRes?.school_id) {
          return {
            rawSchoolId: rawCandidate || String(syncRes.school_id),
            schoolId: String(syncRes.school_id),
            schoolName: String(syncRes.school_name || effectiveNameCandidate),
            schoolSlug: String(syncRes.slug || fallbackSlug)
          };
        }
      } catch {}
    }

    const fallbackSchoolId = effectiveIdCandidate || activeLic?.school_id || dirSchoolsList[0]?.id || fallbackSlug;
    return {
      rawSchoolId: rawCandidate || fallbackSchoolId,
      schoolId: String(fallbackSchoolId),
      schoolName: fallbackName,
      schoolSlug: fallbackSlug
    };
  }

  function extractPlainTenantUsername(rawUsername?: string | null, schoolSlug?: string | null, baseUsername?: string | null): string {
    if (baseUsername && String(baseUsername).trim()) {
      return String(baseUsername).trim().toLowerCase().replace(/^@+/, '');
    }
    const clean = String(rawUsername || '').trim().toLowerCase().replace(/^@+/, '');
    if (!clean.includes('@')) return clean;
    const [localPart, domainPart] = clean.split('@');
    if (!domainPart) return localPart;
    // If domainPart is a school slug (no TLD dot or matches schoolSlug), return localPart as plain username
    if (!domainPart.includes('.') || (schoolSlug && domainPart.toLowerCase() === schoolSlug.toLowerCase())) {
      return localPart;
    }
    return clean;
  }

  // User Management API - List users directly from Supabase public.users with multi-tenant filtering (excludes creator and super_admin)
  app.get("/api/users", authenticateToken, async (req: any, res) => {
    try {
      const adminClient = getSupabaseAdmin();
      const { rawSchoolId, schoolId: resolvedSchoolId, schoolName: resolvedSchoolName, schoolSlug: resolvedSchoolSlug } =
        await resolveTenantSchoolForUsers(req);

      const isSyntheticPlaceholder = (val: any) => {
        const s = String(val || '').trim().toLowerCase();
        return !s || s === '00000000-0000-0000-0000-000000000001' || s === 'school-sphere-academy' || s === 'default';
      };

      const candidateSchoolIds = Array.from(
        new Set([resolvedSchoolId, rawSchoolId, resolvedSchoolSlug].filter(Boolean))
      ) as string[];

      const matchesTenantSchool = (uSchoolId: any) => {
        if (candidateSchoolIds.length === 0) return Boolean(uSchoolId);
        if (!uSchoolId) return false;
        const uStr = String(uSchoolId).trim().toLowerCase();
        if (isSyntheticPlaceholder(uStr) && isSyntheticPlaceholder(rawSchoolId)) {
          return true;
        }
        return candidateSchoolIds.some(cid => String(cid).trim().toLowerCase() === uStr);
      };

      // Build school lookup map for institution names
      const schoolNameMap = new Map<string, { name: string; slug: string }>();
      if (resolvedSchoolId && resolvedSchoolName) {
        schoolNameMap.set(resolvedSchoolId, { name: resolvedSchoolName, slug: resolvedSchoolSlug });
      }
      try {
        const { data: dirSchools } = await adminClient.rpc('get_schools_directory');
        if (Array.isArray(dirSchools)) {
          for (const s of dirSchools) {
            if (s.id) schoolNameMap.set(String(s.id), { name: s.name, slug: s.slug || '' });
          }
        }
      } catch {}

      let dbRows: any[] = [];

      // Query Supabase public.users directly, then SECURITY DEFINER get_tenant_users RPC, then Supabase settings + registered users store
      try {
        let query = adminClient
          .from('users')
          .select('*')
          .order('created_at', { ascending: false });

        if (resolvedSchoolId && /^[0-9a-f-]{36}$/i.test(resolvedSchoolId)) {
          query = query.eq('school_id', resolvedSchoolId);
        }

        const { data, error } = await query;
        if (!error && Array.isArray(data)) {
          dbRows.push(...data);
        } else if (error) {
          // Try SECURITY DEFINER get_tenant_users RPC if direct table select was restricted
          try {
            const rpcRes = await adminClient.rpc('get_tenant_users', {
              p_school_id: resolvedSchoolId && /^[0-9a-f-]{36}$/i.test(resolvedSchoolId) ? resolvedSchoolId : null
            });
            if (!rpcRes.error && Array.isArray(rpcRes.data)) {
              dbRows.push(...rpcRes.data);
            }
          } catch {}
        }
      } catch {}

      // Also merge users persisted via Supabase settings ('tenant_users_registry') and server registered users store
      try {
        const settingsUsers = await readSupabaseSettingList('tenant_users_registry');
        if (Array.isArray(settingsUsers) && settingsUsers.length > 0) {
          dbRows.push(...settingsUsers);
        }
      } catch {}

      try {
        const regUsers = getRegisteredUsers();
        if (Array.isArray(regUsers) && regUsers.length > 0) {
          dbRows.push(...regUsers);
        }
      } catch {}

      // Load tenant teachers and students so linkedProfile badges are always populated accurately
      const tenantTeachers: any[] = [...getFromFallback('teachers', resolvedSchoolId)];
      const tenantStudents: any[] = [...getFromFallback('students', resolvedSchoolId)];
      try {
        if (resolvedSchoolId && /^[0-9a-f-]{36}$/i.test(resolvedSchoolId)) {
          const [tRes, sRes] = await Promise.all([
            adminClient.from('teachers').select('*').eq('school_id', resolvedSchoolId),
            adminClient.from('students').select('*').eq('school_id', resolvedSchoolId)
          ]);
          if (!tRes.error && Array.isArray(tRes.data)) tenantTeachers.push(...tRes.data);
          if (!sRes.error && Array.isArray(sRes.data)) tenantStudents.push(...sRes.data);
        }
      } catch {}

      const seenTenantUsers = new Set<string>();
      const seenUserIds = new Set<string>();
      const seenAuthUserIds = new Set<string>();
      const seenAdminEmails = new Set<string>();
      const deduplicatedRows: any[] = [];
      for (const u of dbRows) {
        if (!u) continue;
        const r = String(u.role || '').toLowerCase();
        if (r === 'creator' || r === 'super_admin') continue;
        const uSchoolId = u.school_id || u.schoolId;
        if (!matchesTenantSchool(uSchoolId)) continue;

        const schInfo = (uSchoolId && schoolNameMap.get(String(uSchoolId))) || null;
        const effectiveSlug = (schInfo?.slug || resolvedSchoolSlug || '').toLowerCase();
        let plainUsername = extractPlainTenantUsername(u.username, effectiveSlug, u.baseUsername);
        if (r === 'admin' && effectiveSlug && plainUsername.toLowerCase() === effectiveSlug) {
          plainUsername = 'admin';
        }
        const schoolKey = String(resolvedSchoolId || uSchoolId || '').toLowerCase();
        const dedupKey = `${schoolKey}::${plainUsername.toLowerCase()}`;
        const idKey = u.id !== undefined && u.id !== null ? String(u.id) : '';
        const authIdKey = u.auth_user_id ? String(u.auth_user_id).toLowerCase() : '';
        const emailKey = u.email ? `${schoolKey}::${String(u.email).trim().toLowerCase()}` : '';

        if (seenTenantUsers.has(dedupKey)) continue;
        if (idKey && seenUserIds.has(idKey)) continue;
        if (authIdKey && seenAuthUserIds.has(authIdKey)) continue;
        if (r === 'admin' && emailKey && seenAdminEmails.has(emailKey)) continue;

        seenTenantUsers.add(dedupKey);
        if (idKey) seenUserIds.add(idKey);
        if (authIdKey) seenAuthUserIds.add(authIdKey);
        if (r === 'admin' && emailKey) seenAdminEmails.add(emailKey);
        deduplicatedRows.push({ ...u, _canonicalPlainUsername: plainUsername });
      }

      const formatted = deduplicatedRows.map(u => {
        const uSchoolId = (!isSyntheticPlaceholder(u.school_id || u.schoolId) ? (u.school_id || u.schoolId) : null) || resolvedSchoolId;
        const schInfo = (uSchoolId && schoolNameMap.get(String(uSchoolId))) || null;
        const plainUsername = u._canonicalPlainUsername || extractPlainTenantUsername(u.username, schInfo?.slug || resolvedSchoolSlug, u.baseUsername);
        const scopedUsername = u.scopedUsername || (u.username?.includes('@') ? u.username : (schInfo?.slug ? `${plainUsername}@${schInfo.slug}` : plainUsername));
        const userEmail = u.email || `${plainUsername}@${schInfo?.slug || resolvedSchoolSlug || 'schoolsphere'}.edu.gh`;
        const userFullName = u.full_name || u.fullName || plainUsername;
        const userRole = String(u.role || 'teacher').toLowerCase();

        // Resolve linked profile details for teacher / headteacher / student
        let linkedProfile = u.linkedProfile || u.linked_profile || null;
        let resolvedStaffId = u.staffId || u.staff_id || linkedProfile?.staffId || linkedProfile?.staff_id || undefined;
        let resolvedStudentId = u.studentId || u.student_id || linkedProfile?.studentId || linkedProfile?.student_id || undefined;
        let resolvedClass = u.class || linkedProfile?.class || undefined;
        let resolvedAssignedClasses = u.assignedClasses || u.assigned_classes || linkedProfile?.assignedClasses || undefined;
        let resolvedSubjects = u.subjects || linkedProfile?.subjects || undefined;

        if (!linkedProfile && (userRole === 'teacher' || userRole === 'headteacher')) {
          const matchedT = tenantTeachers.find((t: any) =>
            (resolvedStaffId && String(t.staffId || t.staff_id || '').toLowerCase() === String(resolvedStaffId).toLowerCase()) ||
            (userEmail && String(t.email || '').toLowerCase() === String(userEmail).toLowerCase()) ||
            `${t.firstName || t.first_name || ''} ${t.lastName || t.last_name || ''}`.trim().toLowerCase() === userFullName.toLowerCase()
          );
          if (matchedT) {
            const normT = normalizeServerTeacherRecord(matchedT);
            resolvedStaffId = normT.staffId;
            resolvedAssignedClasses = normT.assignedClasses;
            resolvedSubjects = normT.subjects;
            linkedProfile = {
              type: 'teacher',
              staffId: normT.staffId,
              assignedClasses: normT.assignedClasses,
              subjects: normT.subjects
            };
          } else if (resolvedStaffId) {
            linkedProfile = {
              type: 'teacher',
              staffId: resolvedStaffId,
              assignedClasses: resolvedAssignedClasses || [],
              subjects: resolvedSubjects || []
            };
          }
        } else if (!linkedProfile && userRole === 'student') {
          const matchedS = tenantStudents.find((s: any) =>
            (resolvedStudentId && String(s.studentId || s.student_id || '').toLowerCase() === String(resolvedStudentId).toLowerCase()) ||
            `${s.firstName || s.first_name || ''} ${s.lastName || s.last_name || ''}`.trim().toLowerCase() === userFullName.toLowerCase()
          );
          if (matchedS) {
            const normS = normalizeServerStudentRecord(matchedS);
            resolvedStudentId = normS.studentId;
            resolvedClass = normS.class;
            linkedProfile = {
              type: 'student',
              studentId: normS.studentId,
              class: normS.class,
              gender: normS.gender
            };
          } else if (resolvedStudentId) {
            linkedProfile = {
              type: 'student',
              studentId: resolvedStudentId,
              class: resolvedClass || 'Basic 7'
            };
          }
        }

        return {
          id: u.id,
          auth_user_id: u.auth_user_id || null,
          username: plainUsername,
          baseUsername: plainUsername,
          scopedUsername,
          fullName: userFullName,
          full_name: userFullName,
          email: userEmail,
          phone: u.phone || '',
          role: userRole,
          status: u.status || 'active',
          schoolId: uSchoolId,
          school_id: uSchoolId,
          schoolName: u.school_name || u.schoolName || u.schools?.name || schInfo?.name || resolvedSchoolName || 'Assigned School',
          staffId: resolvedStaffId,
          studentId: resolvedStudentId,
          class: resolvedClass,
          assignedClasses: resolvedAssignedClasses,
          subjects: resolvedSubjects,
          linkedProfile,
          createdAt: u.created_at ? Number(u.created_at) : (u.createdAt ? Number(u.createdAt) : Date.now()),
          lastLogin: u.last_login ? Number(u.last_login) : (u.lastLogin ? Number(u.lastLogin) : null)
        };
      });

      return res.json({
        success: true,
        schoolId: resolvedSchoolId,
        schoolName: resolvedSchoolName,
        users: formatted
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      console.error("Error in GET /api/users:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // User Management API - Create new user in Supabase (public.users + auth.users + role profile)
  app.post("/api/users", authenticateToken, async (req: any, res) => {
    try {
      const {
        username,
        password,
        passwordHash,
        fullName,
        full_name,
        role,
        status,
        email,
        phone,
        schoolId,
        school_id,
        schoolName,
        staffId,
        studentId,
        class: studentClass,
        gender,
        dateOfBirth,
        guardianName,
        subjects,
        assignedClasses
      } = req.body || {};

      if (!username || !String(username).trim()) {
        return res.status(400).json({ success: false, error: "Username is required" });
      }

      const adminClient = getSupabaseAdmin();
      const {
        rawSchoolId,
        schoolId: resolvedSchoolId,
        schoolName: resolvedSchoolName,
        schoolSlug: resolvedSchoolSlug
      } = await resolveTenantSchoolForUsers(req, schoolId || school_id, schoolName);

      const cleanBaseUser = extractPlainTenantUsername(username, resolvedSchoolSlug);
      if (!cleanBaseUser) {
        return res.status(400).json({ success: false, error: "Please provide a valid username" });
      }

      // Decode raw password for Supabase Auth user creation
      let rawPasswordStr = password ? String(password).trim() : '';
      if (!rawPasswordStr && passwordHash && !String(passwordHash).startsWith('$2a$') && !String(passwordHash).startsWith('$2b$')) {
        try {
          const decoded = Buffer.from(String(passwordHash), 'base64').toString('utf-8');
          rawPasswordStr = (decoded || String(passwordHash)).trim();
        } catch {
          rawPasswordStr = String(passwordHash).trim();
        }
      }
      if (!rawPasswordStr) {
        return res.status(400).json({ success: false, error: "Password is required to create a user" });
      }

      const callerRole = String(req.user?.role || '').toLowerCase();
      const requestedRole = String(role || 'teacher').toLowerCase();
      const safeRole = (requestedRole === 'creator' || requestedRole === 'super_admin')
        ? ((callerRole === 'creator' || callerRole === 'super_admin') ? requestedRole : 'admin')
        : requestedRole;
      const safeStatus = String(status || 'active').toLowerCase();
      const cleanFullName = String(fullName || full_name || cleanBaseUser).trim();
      const cleanPhone = phone ? String(phone).trim() : '';
      const targetSchool = safeRole === 'super_admin' || safeRole === 'creator' ? null : (resolvedSchoolId || rawSchoolId || null);

      if (!targetSchool && safeRole !== 'super_admin' && safeRole !== 'creator') {
        return res.status(400).json({
          success: false,
          error: "A valid tenant school_id is required to create a user in Supabase."
        });
      }

      const scopedUsername = targetSchool
        ? (cleanBaseUser.includes('@') ? cleanBaseUser : `${cleanBaseUser}@${resolvedSchoolSlug}`)
        : cleanBaseUser;
      const effectiveEmail = (email && String(email).trim())
        ? String(email).trim().toLowerCase()
        : `${cleanBaseUser}@${resolvedSchoolSlug || 'schoolsphere'}.edu.gh`;

      // 1. Check for duplicate username within the SAME tenant school in Supabase public.users, RPC, settings, and registered users
      if (targetSchool) {
        try {
          let existingSchoolUsers: any[] = [];
          const { data: sameSchoolUsers, error: dupSelErr } = await adminClient
            .from('users')
            .select('id, username, email, school_id')
            .eq('school_id', targetSchool);

          if (!dupSelErr && Array.isArray(sameSchoolUsers)) {
            existingSchoolUsers.push(...sameSchoolUsers);
          } else {
            try {
              const rpcUsers = await adminClient.rpc('get_tenant_users', {
                p_school_id: /^[0-9a-f-]{36}$/i.test(String(targetSchool)) ? String(targetSchool) : null
              });
              if (!rpcUsers.error && Array.isArray(rpcUsers.data)) {
                existingSchoolUsers.push(
                  ...rpcUsers.data.filter((u: any) => String(u.school_id || u.schoolId || '') === String(targetSchool))
                );
              }
            } catch {}
          }

          try {
            const settingsUsers = await readSupabaseSettingList('tenant_users_registry');
            if (Array.isArray(settingsUsers)) {
              existingSchoolUsers.push(
                ...settingsUsers.filter((u: any) => String(u.school_id || u.schoolId || '') === String(targetSchool))
              );
            }
          } catch {}

          const regSameSchool = getRegisteredUsers().filter(
            (u: any) => String(u.school_id || u.schoolId || '') === String(targetSchool) && u.role !== 'creator' && u.role !== 'super_admin'
          );
          existingSchoolUsers.push(...regSameSchool);

          const duplicateInDb = existingSchoolUsers.find((u: any) => {
            const uPlain = extractPlainTenantUsername(u.username, resolvedSchoolSlug, u.baseUsername);
            return uPlain === cleanBaseUser || String(u.username || '').toLowerCase() === scopedUsername;
          });
          if (duplicateInDb) {
            return res.status(409).json({
              success: false,
              error: `Username "@${cleanBaseUser}" already exists in ${resolvedSchoolName || 'this school'}.`
            });
          }
        } catch {}
      }

      // 2. Check if ANOTHER school already owns bare cleanBaseUser in public.users
      let dbUsername = cleanBaseUser;
      if (targetSchool) {
        try {
          const { data: existCollision } = await adminClient
            .from('users')
            .select('id, school_id, username')
            .eq('username', cleanBaseUser)
            .maybeSingle();
          if (existCollision && existCollision.school_id && String(existCollision.school_id) !== String(targetSchool)) {
            dbUsername = scopedUsername;
          }
        } catch {}
      }

      // 3. Provision immediately in Supabase Auth (auth.users) via admin.createUser OR auth.signUp (which triggers public.handle_new_user())
      let authUserId: string | null = null;
      let authedUserClient: any = null;
      const authPassword = rawPasswordStr && rawPasswordStr.length >= 6 ? rawPasswordStr : `${rawPasswordStr || 'Pass'}#2026`;
      const userMetaPayload = {
        full_name: cleanFullName,
        username: cleanBaseUser,
        scoped_username: scopedUsername,
        role: safeRole,
        school_id: targetSchool,
        phone: cleanPhone
      };

      try {
        if (adminClient.auth?.admin?.createUser) {
          const { data: authCreated, error: authErr } = await adminClient.auth.admin.createUser({
            email: effectiveEmail,
            password: authPassword,
            email_confirm: true,
            user_metadata: userMetaPayload
          });
          if (!authErr && authCreated?.user?.id) {
            authUserId = authCreated.user.id;
          } else if (authErr && targetSchool) {
            const scopedAuthEmail = `${cleanBaseUser}.${resolvedSchoolSlug}@schoolsphere.edu.gh`;
            const { data: retryAuth } = await adminClient.auth.admin.createUser({
              email: scopedAuthEmail,
              password: authPassword,
              email_confirm: true,
              user_metadata: {
                ...userMetaPayload,
                contact_email: effectiveEmail
              }
            });
            if (retryAuth?.user?.id) {
              authUserId = retryAuth.user.id;
            }
          }
        }
      } catch (authEx: any) {
        console.warn("Notice provisioning Supabase Auth user via admin API:", authEx?.message);
      }

      if (!authUserId) {
        try {
          const isolatedAuthClient = createAuthenticatedSupabaseClient();
          const { data: signUpData, error: signUpErr } = await isolatedAuthClient.auth.signUp({
            email: effectiveEmail,
            password: authPassword,
            options: {
              data: userMetaPayload
            }
          });
          if (!signUpErr && signUpData?.user?.id) {
            authUserId = signUpData.user.id;
            if (signUpData.session?.access_token) {
              authedUserClient = createAuthenticatedSupabaseClient(signUpData.session.access_token);
            }
          }
        } catch {}
      }

      const activeDbClient = authedUserClient || adminClient;

      // 4. Provision in Supabase public.users
      const nowTs = Date.now();
      let savedRow: any = null;
      let linkedProfile: any = null;
      let dbWriteError: string | null = null;

      if (!savedRow) {
        const fullPayload: Record<string, any> = {
          username: dbUsername,
          full_name: cleanFullName,
          role: safeRole,
          status: safeStatus,
          email: effectiveEmail,
          phone: cleanPhone || null,
          school_id: targetSchool,
          created_at: nowTs,
          updated_at: nowTs
        };
        if (authUserId) {
          fullPayload.auth_user_id = authUserId;
        }

        try {
          let existingTriggerRow: any = null;
          if (authUserId) {
            const { data: trigRow } = await activeDbClient
              .from('users')
              .select('id, school_id, username')
              .eq('auth_user_id', authUserId)
              .maybeSingle();
            if (
              trigRow?.id &&
              (!trigRow.school_id || String(trigRow.school_id) === String(targetSchool))
            ) {
              existingTriggerRow = trigRow;
            }
          }

          const { data: insData, error: insErr } = existingTriggerRow?.id
            ? await activeDbClient.from('users').update(fullPayload).eq('id', existingTriggerRow.id).select().maybeSingle()
            : await activeDbClient.from('users').insert([fullPayload]).select().maybeSingle();

          if (!insErr && insData) {
            savedRow = insData;
          } else if (insErr) {
            dbWriteError = insErr.message;
            const corePayload: Record<string, any> = {
              username: insErr.code === '23505' ? scopedUsername : dbUsername,
              full_name: cleanFullName,
              role: safeRole,
              status: safeStatus,
              email: effectiveEmail,
              school_id: targetSchool,
              created_at: nowTs,
              updated_at: nowTs,
              ...(authUserId ? { auth_user_id: authUserId } : {})
            };
            const { data: retryData, error: retryErr } = existingTriggerRow?.id
              ? await activeDbClient.from('users').update(corePayload).eq('id', existingTriggerRow.id).select().maybeSingle()
              : await activeDbClient.from('users').insert([corePayload]).select().maybeSingle();

            if (!retryErr && retryData) {
              savedRow = retryData;
              dbUsername = corePayload.username;
              dbWriteError = null;
            } else if (retryErr) {
              dbWriteError = retryErr.message;
            }
          }
        } catch (insCatch: any) {
          dbWriteError = insCatch?.message || 'Database insert exception';
        }
      }

      if (!savedRow || !savedRow.id) {
        savedRow = {
          id: nowTs,
          auth_user_id: authUserId || null,
          username: dbUsername,
          baseUsername: cleanBaseUser,
          scopedUsername,
          full_name: cleanFullName,
          fullName: cleanFullName,
          role: safeRole,
          status: safeStatus,
          email: effectiveEmail,
          phone: cleanPhone || null,
          school_id: targetSchool,
          schoolId: targetSchool,
          schoolName: resolvedSchoolName,
          created_at: nowTs,
          updated_at: nowTs
        };
      }

      const savedId = savedRow.id;
      if (!authUserId || !savedRow.auth_user_id) {
        const linkedAuth = await ensureUserSupabaseAuthIdentity({
          userId: typeof savedId === 'number' && savedId < 1000000000 ? savedId : null,
          email: effectiveEmail,
          username: cleanBaseUser,
          scopedUsername,
          fullName: cleanFullName,
          role: safeRole,
          schoolId: targetSchool,
          rawPassword: rawPasswordStr || undefined,
          existingAuthUserId: authUserId || savedRow.auth_user_id || null,
          issueSession: false
        });
        if (linkedAuth.authUserId) {
          authUserId = linkedAuth.authUserId;
          savedRow.auth_user_id = linkedAuth.authUserId;
        }
      }

      // 5. Auto-link or create matching profile in public.teachers or public.students in Supabase
      const nameParts = cleanFullName.split(/\s+/);
      const firstName = nameParts[0] || cleanBaseUser;
      const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';
      const resolvedAssignedClasses = Array.isArray(assignedClasses) ? assignedClasses : (studentClass ? [studentClass] : ['Basic 7']);
      const resolvedSubjects = Array.isArray(subjects) ? subjects : [];
      let resolvedStaffId = staffId ? String(staffId).trim() : undefined;
      let resolvedStudentId = studentId ? String(studentId).trim() : undefined;

      if (!linkedProfile && (safeRole === 'teacher' || safeRole === 'headteacher') && targetSchool) {
        const generatedStaffId = resolvedStaffId || `TEA-${String(nowTs).slice(-4)}`;
        resolvedStaffId = generatedStaffId;
        try {
          const { data: existingTeachers } = await activeDbClient
            .from('teachers')
            .select('*')
            .eq('school_id', targetSchool);

          const matchedTeacher = (existingTeachers || []).find((t: any) =>
            (t.email && String(t.email).toLowerCase() === effectiveEmail) ||
            (String(t.firstName || t.first_name || '').toLowerCase() === firstName.toLowerCase() &&
             String(t.lastName || t.last_name || '').toLowerCase() === lastName.toLowerCase())
          );

          if (matchedTeacher) {
            if (!matchedTeacher.user_id && typeof savedId === 'number' && savedId < 1000000000) {
              try {
                await activeDbClient.from('teachers').update({ user_id: savedId }).eq('id', matchedTeacher.id);
              } catch {}
            }
            linkedProfile = { type: 'teacher', ...normalizeServerTeacherRecord({ ...matchedTeacher, user_id: matchedTeacher.user_id || savedId }) };
            resolvedStaffId = linkedProfile.staffId || generatedStaffId;
          } else {
            let insertedTeacher: any = null;
            const snakeTeacher: Record<string, any> = {
              staff_id: generatedStaffId,
              first_name: firstName,
              last_name: lastName,
              phone: cleanPhone,
              email: effectiveEmail,
              assigned_classes: resolvedAssignedClasses,
              subjects: resolvedSubjects,
              school_id: targetSchool,
              status: 'active',
              ...(typeof savedId === 'number' && savedId < 1000000000 ? { user_id: savedId } : {})
            };
            const { data: tSnake, error: tSnakeErr } = await activeDbClient
              .from('teachers')
              .insert([snakeTeacher])
              .select()
              .maybeSingle();

            if (!tSnakeErr && tSnake) {
              insertedTeacher = tSnake;
            } else {
              const camelTeacher = {
                staffId: generatedStaffId,
                firstName,
                lastName,
                phone: cleanPhone,
                email: effectiveEmail,
                assignedClasses: resolvedAssignedClasses,
                subjects: resolvedSubjects,
                school_id: targetSchool
              };
              const { data: tCamel } = await activeDbClient
                .from('teachers')
                .insert([camelTeacher])
                .select()
                .maybeSingle();
              if (tCamel) insertedTeacher = tCamel;
            }

            const teacherRecord = normalizeServerTeacherRecord(insertedTeacher || {
              id: nowTs,
              staffId: generatedStaffId,
              firstName,
              lastName,
              phone: cleanPhone,
              email: effectiveEmail,
              assignedClasses: resolvedAssignedClasses,
              subjects: resolvedSubjects,
              school_id: targetSchool,
              status: 'active'
            });
            saveToFallback('teachers', teacherRecord);
            linkedProfile = {
              type: 'teacher',
              staffId: teacherRecord.staffId,
              firstName: teacherRecord.firstName,
              lastName: teacherRecord.lastName,
              email: teacherRecord.email,
              phone: teacherRecord.phone,
              assignedClasses: teacherRecord.assignedClasses,
              subjects: teacherRecord.subjects
            };
          }
        } catch {
          const fallbackTeacher = normalizeServerTeacherRecord({
            id: nowTs,
            staffId: generatedStaffId,
            firstName,
            lastName,
            phone: cleanPhone,
            email: effectiveEmail,
            assignedClasses: resolvedAssignedClasses,
            subjects: resolvedSubjects,
            school_id: targetSchool,
            status: 'active'
          });
          saveToFallback('teachers', fallbackTeacher);
          linkedProfile = {
            type: 'teacher',
            staffId: generatedStaffId,
            firstName,
            lastName,
            email: effectiveEmail,
            phone: cleanPhone,
            assignedClasses: resolvedAssignedClasses,
            subjects: resolvedSubjects
          };
        }
      } else if (!linkedProfile && safeRole === 'student' && targetSchool) {
        const generatedStudentId = resolvedStudentId || `STU-${String(nowTs).slice(-6)}`;
        resolvedStudentId = generatedStudentId;
        const effectiveClass = studentClass || 'Basic 7';
        const effectiveGender = gender === 'Female' ? 'Female' : 'Male';
        try {
          const { data: existingStudents } = await activeDbClient
            .from('students')
            .select('*')
            .eq('school_id', targetSchool);

          const matchedStudent = (existingStudents || []).find((s: any) =>
            String(s.studentId || s.student_id || '').toLowerCase() === generatedStudentId.toLowerCase() ||
            (String(s.firstName || s.first_name || '').toLowerCase() === firstName.toLowerCase() &&
             String(s.lastName || s.last_name || '').toLowerCase() === lastName.toLowerCase())
          );

          if (matchedStudent) {
            if (!matchedStudent.user_id && typeof savedId === 'number' && savedId < 1000000000) {
              try {
                await activeDbClient.from('students').update({ user_id: savedId }).eq('id', matchedStudent.id);
              } catch {}
            }
            linkedProfile = { type: 'student', ...normalizeServerStudentRecord({ ...matchedStudent, user_id: matchedStudent.user_id || savedId }) };
            resolvedStudentId = linkedProfile.studentId || generatedStudentId;
          } else {
            let insertedStudent: any = null;
            const snakeStudent: Record<string, any> = {
              student_id: generatedStudentId,
              first_name: firstName,
              last_name: lastName,
              class: effectiveClass,
              gender: effectiveGender,
              date_of_birth: dateOfBirth || '2012-01-01',
              guardian_name: guardianName || '',
              guardian_phone: cleanPhone || '',
              fees_paid: 0,
              total_fees: 0,
              created_at: nowTs,
              school_id: targetSchool,
              ...(typeof savedId === 'number' && savedId < 1000000000 ? { user_id: savedId } : {})
            };
            const { data: sSnake, error: sSnakeErr } = await activeDbClient
              .from('students')
              .insert([snakeStudent])
              .select()
              .maybeSingle();

            if (!sSnakeErr && sSnake) {
              insertedStudent = sSnake;
            } else {
              const camelStudent = {
                studentId: generatedStudentId,
                firstName,
                lastName,
                class: effectiveClass,
                gender: effectiveGender,
                dateOfBirth: dateOfBirth || '2012-01-01',
                guardianName: guardianName || '',
                guardianPhone: cleanPhone || '',
                feesPaid: 0,
                totalFees: 0,
                createdAt: nowTs,
                school_id: targetSchool
              };
              const { data: sCamel } = await activeDbClient
                .from('students')
                .insert([camelStudent])
                .select()
                .maybeSingle();
              if (sCamel) insertedStudent = sCamel;
            }

            const studentRecord = normalizeServerStudentRecord(insertedStudent || {
              id: nowTs,
              studentId: generatedStudentId,
              firstName,
              lastName,
              class: effectiveClass,
              gender: effectiveGender,
              dateOfBirth: dateOfBirth || '2012-01-01',
              guardianName: guardianName || '',
              guardianPhone: cleanPhone || '',
              feesPaid: 0,
              totalFees: 0,
              createdAt: nowTs,
              school_id: targetSchool
            });
            saveToFallback('students', studentRecord);
            linkedProfile = {
              type: 'student',
              studentId: studentRecord.studentId,
              firstName: studentRecord.firstName,
              lastName: studentRecord.lastName,
              class: studentRecord.class,
              gender: studentRecord.gender
            };
          }
        } catch {
          const fallbackStudent = normalizeServerStudentRecord({
            id: nowTs,
            studentId: generatedStudentId,
            firstName,
            lastName,
            class: effectiveClass,
            gender: effectiveGender,
            dateOfBirth: dateOfBirth || '2012-01-01',
            guardianName: guardianName || '',
            guardianPhone: cleanPhone || '',
            feesPaid: 0,
            totalFees: 0,
            createdAt: nowTs,
            school_id: targetSchool
          });
          saveToFallback('students', fallbackStudent);
          linkedProfile = {
            type: 'student',
            studentId: generatedStudentId,
            firstName,
            lastName,
            class: effectiveClass,
            gender: effectiveGender
          };
        }
      }

      // Always synchronize created tenant user into server registered users store and Supabase settings ('tenant_users_registry')
      const registryUserRecord = {
        id: savedId,
        auth_user_id: savedRow.auth_user_id || authUserId || null,
        username: cleanBaseUser,
        baseUsername: cleanBaseUser,
        scopedUsername,
        fullName: savedRow.full_name || cleanFullName,
        full_name: savedRow.full_name || cleanFullName,
        email: savedRow.email || effectiveEmail,
        phone: savedRow.phone ?? cleanPhone,
        role: savedRow.role || safeRole,
        status: savedRow.status || safeStatus,
        schoolId: savedRow.school_id || targetSchool,
        school_id: savedRow.school_id || targetSchool,
        schoolName: resolvedSchoolName,
        staffId: resolvedStaffId,
        studentId: resolvedStudentId,
        class: studentClass || 'Basic 7',
        assignedClasses: resolvedAssignedClasses,
        subjects: resolvedSubjects,
        linkedProfile,
        createdAt: savedRow.created_at || nowTs,
        created_at: savedRow.created_at || nowTs,
        updatedAt: nowTs,
        updated_at: nowTs
      };

      try {
        const regUsers = getRegisteredUsers();
        const existIdx = regUsers.findIndex((u: any) =>
          String(u.school_id || u.schoolId || '') === String(targetSchool || '') &&
          extractPlainTenantUsername(u.username, resolvedSchoolSlug, u.baseUsername) === cleanBaseUser
        );
        if (existIdx >= 0) {
          regUsers[existIdx] = { ...regUsers[existIdx], ...registryUserRecord };
        } else {
          regUsers.unshift(registryUserRecord);
        }
        saveRegisteredUsers(regUsers);
      } catch {}

      try {
        const settingsUsers = await readSupabaseSettingList('tenant_users_registry');
        const filteredSettings = Array.isArray(settingsUsers)
          ? settingsUsers.filter((u: any) =>
              !(String(u.school_id || u.schoolId || '') === String(targetSchool || '') &&
                extractPlainTenantUsername(u.username, resolvedSchoolSlug, u.baseUsername) === cleanBaseUser)
            )
          : [];
        filteredSettings.unshift(registryUserRecord);
        await writeSupabaseSettingList('tenant_users_registry', filteredSettings);
      } catch {}

      invalidateDbCache();

      return res.status(201).json({
        success: true,
        user: {
          id: savedId,
          auth_user_id: savedRow.auth_user_id || authUserId,
          username: cleanBaseUser,
          baseUsername: cleanBaseUser,
          scopedUsername,
          fullName: savedRow.full_name || cleanFullName,
          full_name: savedRow.full_name || cleanFullName,
          role: savedRow.role || safeRole,
          status: savedRow.status || safeStatus,
          email: savedRow.email || effectiveEmail,
          phone: savedRow.phone ?? cleanPhone,
          schoolId: savedRow.school_id || targetSchool,
          school_id: savedRow.school_id || targetSchool,
          schoolName: resolvedSchoolName,
          staffId: resolvedStaffId,
          studentId: resolvedStudentId,
          class: studentClass || 'Basic 7',
          assignedClasses: resolvedAssignedClasses,
          subjects: resolvedSubjects,
          linkedProfile,
          createdAt: savedRow.created_at || nowTs
        },
        linkedProfile
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      console.error("Error in POST /api/users:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // User Management API - Update user directly in Supabase (public.users + auth.users + settings/registered fallback)
  app.put("/api/users/:id", authenticateToken, async (req: any, res) => {
    try {
      const { id } = req.params;
      const { fullName, full_name, role, status, email, phone, password, passwordHash, schoolId, school_id, username: reqUsername } = req.body || {};
      const scope = resolveTenantAccessScope(req, schoolId || school_id);
      if (scope.unauthorized) {
        return res.status(401).json({ success: false, error: scope.error });
      }
      if (scope.forbidden) {
        return res.status(403).json({ success: false, error: scope.error });
      }
      const adminClient = getSupabaseAdmin();

      const updateData: any = { updated_at: Date.now() };
      if (fullName || full_name) updateData.full_name = (fullName || full_name).trim();
      if (role) {
        const requestedRole = String(role).toLowerCase();
        if (!scope.isSuper && (requestedRole === 'creator' || requestedRole === 'super_admin')) {
          return res.status(403).json({ success: false, error: "Forbidden: Only platform creators can assign super_admin or creator roles." });
        }
        updateData.role = role;
      }
      if (status) updateData.status = status;
      if (email !== undefined) updateData.email = email;
      if (phone !== undefined) updateData.phone = phone;

      let rawPasswordStr = '';
      if (password) {
        rawPasswordStr = String(password).trim();
      } else if (passwordHash && !String(passwordHash).startsWith('$2a$') && !String(passwordHash).startsWith('$2b$')) {
        try {
          const decoded = Buffer.from(String(passwordHash), 'base64').toString('utf-8');
          rawPasswordStr = (decoded || String(passwordHash)).trim();
        } catch {
          rawPasswordStr = String(passwordHash).trim();
        }
      }

      const targetSchoolId = scope.schoolId || null;
      let targetUsername = String(reqUsername || req.query?.username || '').trim().toLowerCase().replace(/^@+/, '');

      // Look up username from registries if not passed
      if (!targetUsername) {
        const regMatch = getRegisteredUsers().find((u: any) => String(u.id) === String(id));
        if (regMatch?.username) targetUsername = String(regMatch.username).trim().toLowerCase().replace(/^@+/, '');
      }

      let updatedRow: any = null;
      let updateErrMsg: string | null = null;

      try {
        let q = adminClient.from('users').update(updateData).eq('id', id);
        if (!scope.isSuper && targetSchoolId) {
          q = q.eq('school_id', targetSchoolId);
        }
        const { data, error } = await q.select().maybeSingle();
        if (!error && data) {
          updatedRow = data;
          if (!targetUsername && data.username) {
            targetUsername = String(data.username).trim().toLowerCase().split('@')[0];
          }
        } else if (error) {
          updateErrMsg = error.message;
        }
      } catch (e: any) {
        updateErrMsg = e?.message || null;
      }

      // If id didn't match in public.users (e.g. timestamp ID from registry), match by username + school_id
      if (!updatedRow && targetUsername) {
        try {
          let q = adminClient.from('users').update(updateData).ilike('username', `${targetUsername}%`);
          if (targetSchoolId) q = q.eq('school_id', targetSchoolId);
          const { data, error } = await q.select().maybeSingle();
          if (!error && data) {
            updatedRow = data;
          }
        } catch {}
      }

      const matchesUserEntry = (u: any) => {
        if (String(u.id) === String(id)) return true;
        if (updatedRow?.id && String(u.id) === String(updatedRow.id)) return true;
        if (targetUsername) {
          const uBase = String(u.baseUsername || u.username || '').trim().toLowerCase().split('@')[0];
          const uScoped = String(u.scopedUsername || u.username || '').trim().toLowerCase();
          const sameUser = uBase === targetUsername || uScoped === targetUsername || uScoped.startsWith(`${targetUsername}@`);
          const sameSchool = !targetSchoolId || !(u.school_id || u.schoolId) || (u.school_id || u.schoolId) === targetSchoolId;
          if (sameUser && sameSchool) return true;
        }
        return false;
      };

      // Also update in server registered users store and Supabase settings ('tenant_users_registry')
      try {
        const regUsers = getRegisteredUsers();
        let matchedAny = false;
        for (let rIdx = 0; rIdx < regUsers.length; rIdx++) {
          if (matchesUserEntry(regUsers[rIdx])) {
            matchedAny = true;
            const merged = {
              ...regUsers[rIdx],
              ...(updateData.full_name ? { fullName: updateData.full_name, full_name: updateData.full_name } : {}),
              ...(updateData.role ? { role: updateData.role } : {}),
              ...(updateData.status ? { status: updateData.status } : {}),
              ...(updateData.email !== undefined ? { email: updateData.email } : {}),
              ...(updateData.phone !== undefined ? { phone: updateData.phone } : {}),
              updatedAt: updateData.updated_at,
              updated_at: updateData.updated_at
            };
            regUsers[rIdx] = merged;
            if (!updatedRow) updatedRow = merged;
          }
        }
        if (matchedAny) saveRegisteredUsers(regUsers);
      } catch {}

      try {
        const settingsUsers = await readSupabaseSettingList('tenant_users_registry');
        if (Array.isArray(settingsUsers) && settingsUsers.length > 0) {
          let matchedSettings = false;
          for (let sIdx = 0; sIdx < settingsUsers.length; sIdx++) {
            if (matchesUserEntry(settingsUsers[sIdx])) {
              matchedSettings = true;
              const merged = {
                ...settingsUsers[sIdx],
                ...(updateData.full_name ? { fullName: updateData.full_name, full_name: updateData.full_name } : {}),
                ...(updateData.role ? { role: updateData.role } : {}),
                ...(updateData.status ? { status: updateData.status } : {}),
                ...(updateData.email !== undefined ? { email: updateData.email } : {}),
                ...(updateData.phone !== undefined ? { phone: updateData.phone } : {}),
                updatedAt: updateData.updated_at,
                updated_at: updateData.updated_at
              };
              settingsUsers[sIdx] = merged;
              if (!updatedRow) updatedRow = merged;
            }
          }
          if (matchedSettings) {
            await writeSupabaseSettingList('tenant_users_registry', settingsUsers);
          }
        }
      } catch {}

      if (!updatedRow) {
        return res.status(404).json({
          success: false,
          error: updateErrMsg
            ? `Failed to update user in Supabase: ${updateErrMsg}`
            : "User not found in Supabase public.users."
        });
      }

      // Sync with Supabase Auth (auth.users) if auth_user_id is known
      const targetAuthUid = updatedRow?.auth_user_id;
      if (targetAuthUid && adminClient.auth?.admin?.updateUserById) {
        try {
          const authUpdates: any = {};
          if (rawPasswordStr && rawPasswordStr.length >= 6) authUpdates.password = rawPasswordStr;
          if (updateData.email) authUpdates.email = String(updateData.email).trim().toLowerCase();
          if (updateData.full_name || updateData.role || updateData.status || rawPasswordStr) {
            authUpdates.user_metadata = {
              ...(updateData.full_name ? { full_name: updateData.full_name } : {}),
              ...(updateData.role ? { role: updateData.role } : {}),
              ...(updateData.status ? { status: updateData.status } : {}),
              ...(rawPasswordStr ? { must_change_password: false } : {})
            };
          }
          if (Object.keys(authUpdates).length > 0) {
            await adminClient.auth.admin.updateUserById(targetAuthUid, authUpdates);
          }
        } catch {}
      }

      invalidateDbCache();

      return res.json({
        success: true,
        message: "User updated in Supabase successfully",
        user: updatedRow
      });
    } catch (err: any) {
      console.error("Error in PUT /api/users/:id:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // User Management API - Delete user directly from Supabase (public.users + auth.users + settings/registered fallback)
  app.delete("/api/users/:id", authenticateToken, async (req: any, res) => {
    try {
      const { id } = req.params;
      const scope = resolveTenantAccessScope(req);
      if (scope.unauthorized) {
        return res.status(401).json({ success: false, error: scope.error });
      }
      if (scope.forbidden) {
        return res.status(403).json({ success: false, error: scope.error });
      }
      const adminClient = getSupabaseAdmin();
      const targetSchoolId = scope.schoolId || null;
      let targetUsername = String(req.query?.username || '').trim().toLowerCase().replace(/^@+/, '');

      let existingUser: any = null;
      try {
        let lookupQ = adminClient
          .from('users')
          .select('id, auth_user_id, username, school_id')
          .eq('id', id);
        if (!scope.isSuper && targetSchoolId) {
          lookupQ = lookupQ.eq('school_id', targetSchoolId);
        }
        const { data } = await lookupQ.maybeSingle();
        existingUser = data;
        if (existingUser?.username && !targetUsername) {
          targetUsername = String(existingUser.username).trim().toLowerCase().split('@')[0];
        }
      } catch {}

      if (!targetUsername) {
        const regMatch = getRegisteredUsers().find((u: any) => String(u.id) === String(id));
        if (regMatch?.username) {
          targetUsername = String(regMatch.username).trim().toLowerCase().split('@')[0];
        }
      }

      let deletedOk = false;
      let deleteErrMsg: string | null = null;

      try {
        let delQ = adminClient.from('users').delete().eq('id', id);
        if (!scope.isSuper && targetSchoolId) {
          delQ = delQ.eq('school_id', targetSchoolId);
        }
        const { error } = await delQ;
        if (!error) {
          deletedOk = true;
        } else {
          deleteErrMsg = error.message;
        }
      } catch (e: any) {
        deleteErrMsg = e?.message || null;
      }

      if (targetUsername) {
        try {
          let q = adminClient.from('users').delete().ilike('username', `${targetUsername}%`);
          if (targetSchoolId) q = q.eq('school_id', targetSchoolId);
          const { error } = await q;
          if (!error) deletedOk = true;
        } catch {}
      }

      if (!deletedOk && /^\d+$/.test(String(id))) {
        try {
          const rpcRes = await adminClient.rpc('delete_tenant_user', {
            p_user_id: Number(id),
            p_school_id: targetSchoolId && /^[0-9a-f-]{36}$/i.test(String(targetSchoolId)) ? targetSchoolId : null
          });
          if (!rpcRes.error && rpcRes.data?.success) {
            deletedOk = true;
          }
        } catch {}
      }

      const shouldRemoveUserEntry = (u: any) => {
        if (String(u.id) === String(id)) return true;
        if (existingUser?.id && String(u.id) === String(existingUser.id)) return true;
        if (targetUsername) {
          const uBase = String(u.baseUsername || u.username || '').trim().toLowerCase().split('@')[0];
          const uScoped = String(u.scopedUsername || u.username || '').trim().toLowerCase();
          const sameUser = uBase === targetUsername || uScoped === targetUsername || uScoped.startsWith(`${targetUsername}@`);
          const sameSchool = !targetSchoolId || !(u.school_id || u.schoolId) || (u.school_id || u.schoolId) === targetSchoolId;
          if (sameUser && sameSchool) return true;
        }
        return false;
      };

      try {
        const regUsers = getRegisteredUsers();
        const beforeLen = regUsers.length;
        const remaining = regUsers.filter((u: any) => !shouldRemoveUserEntry(u));
        if (remaining.length < beforeLen) {
          saveRegisteredUsers(remaining);
          deletedOk = true;
        }
      } catch {}

      try {
        const settingsUsers = await readSupabaseSettingList('tenant_users_registry');
        if (Array.isArray(settingsUsers) && settingsUsers.length > 0) {
          const remainingSettings = settingsUsers.filter((u: any) => !shouldRemoveUserEntry(u));
          if (remainingSettings.length < settingsUsers.length) {
            await writeSupabaseSettingList('tenant_users_registry', remainingSettings);
            deletedOk = true;
          }
        }
      } catch {}

      if (!deletedOk) {
        return res.status(500).json({
          success: false,
          error: deleteErrMsg || "Failed to delete user from Supabase public.users."
        });
      }

      const removedAuthUid = existingUser?.auth_user_id;
      if (removedAuthUid && adminClient.auth?.admin?.deleteUser) {
        try {
          await adminClient.auth.admin.deleteUser(removedAuthUid);
        } catch {}
      }

      invalidateDbCache();

      return res.json({ success: true, message: "User deleted from Supabase successfully" });
    } catch (err: any) {
      console.error("Error in DELETE /api/users/:id:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Helper functions to normalize PostgreSQL check constraints on school_licenses
  function normalizeLicenseTier(tier: any): 'Basic' | 'Standard' | 'Enterprise' {
    if (!tier) return 'Standard';
    const t = String(tier).trim().toLowerCase();
    if (t.includes('basic') || t.includes('starter')) return 'Basic';
    if (t.includes('enterprise') || t.includes('premium') || t.includes('pro') || t.includes('ultimate')) return 'Enterprise';
    return 'Standard';
  }

  function normalizeLicenseStatus(status: any): 'active' | 'expired' | 'suspended' | 'revoked' | 'deactivated' {
    if (!status) return 'active';
    const s = String(status).trim().toLowerCase();
    if (s.includes('deactivat')) return 'deactivated';
    if (s.includes('suspend')) return 'suspended';
    if (s.includes('revoke')) return 'revoked';
    if (s.includes('expire')) return 'expired';
    return 'active';
  }

  function isSyntheticLicenseKey(key?: string | null, licenseId?: number | null): boolean {
    const k = String(key || '').trim().toUpperCase();
    if (!k) return true;
    if (/^\d+$/.test(k)) return true;
    if (licenseId !== null && licenseId !== undefined && k.endsWith(`-${licenseId}`)) return true;
    if (/^ESEPA-[A-Z0-9]{1,4}-[A-Z]{3}-(\d{1,5}|2026)$/.test(k)) return true;
    return false;
  }

  function generateDeterministicSchoolKey(schoolId?: string | null, schoolName?: string | null, tier?: string | null): string {
    const cleanName = String(schoolName || 'SCHOOL').trim().toUpperCase();
    const prefix = cleanName.replace(/[^A-Z0-9]/g, '').slice(0, 4) || 'SCH';
    const tierCode = normalizeLicenseTier(tier).toUpperCase().slice(0, 3);
    const seed = `${schoolId || cleanName}::${cleanName}`;
    const hash = crypto.createHash('sha256').update(seed).digest('hex').toUpperCase().slice(0, 6);
    return `ESEPA-${prefix}-${tierCode}-${hash}`;
  }

  // Strictly read-only no-op: existing schools, licenses, and user passwords in Supabase must never be modified automatically
  async function autoReconcileSchoolsAndLicenses(_adminClient: any) {
    return;
  }

  // Strictly update-only helper for suspending, reactivating, or updating an existing school/license.
  // Security rule: NEVER insert new rows into public.schools or public.school_licenses.
  async function updateSchoolTenantStatusOnly(params: {
    schoolId?: string | null;
    schoolName?: string | null;
    slug?: string | null;
    licenseId?: number | null;
    licenseKey?: string | null;
    tier?: string;
    expiryDate?: number | null;
    status?: string;
  }) {
    const adminClient = getSupabaseAdmin();
    const rawKey = String(params.licenseKey || '').trim().toUpperCase();
    let resolvedSchoolId = params.schoolId || null;
    let resolvedSchoolName = String(params.schoolName || params.slug || '').trim().toUpperCase();
    let resolvedLicenseId: number | null = params.licenseId ?? (/^\d+$/.test(rawKey) ? Number(rawKey) : null);

    const localLics = getGeneratedLicenses();
    const fbSchools = getFromFallback('schools');

    // 1. Resolve against existing local licenses & fallback records first
    const matchedLocIdx = localLics.findIndex((l: any) =>
      (rawKey && String(l.key || '').toUpperCase() === rawKey) ||
      (resolvedLicenseId !== null && Number(l.license_id) === resolvedLicenseId) ||
      (resolvedSchoolId && l.school_id === resolvedSchoolId) ||
      (resolvedSchoolName && (l.schoolName || '').trim().toUpperCase() === resolvedSchoolName)
    );
    const matchedLoc = matchedLocIdx >= 0 ? localLics[matchedLocIdx] : null;
    if (matchedLoc) {
      if (!resolvedSchoolId && matchedLoc.school_id) resolvedSchoolId = matchedLoc.school_id;
      if (!resolvedSchoolName && matchedLoc.schoolName) resolvedSchoolName = matchedLoc.schoolName.trim().toUpperCase();
      if (resolvedLicenseId === null && matchedLoc.license_id) resolvedLicenseId = Number(matchedLoc.license_id);
    }

    const matchedFb = fbSchools.find((s: any) =>
      (resolvedSchoolId && s.id === resolvedSchoolId) ||
      (rawKey && (String(s.licenseKey || '').toUpperCase() === rawKey || String(s.license_id || '') === rawKey)) ||
      (resolvedSchoolName && (s.name || s.schoolName || '').trim().toUpperCase() === resolvedSchoolName)
    );
    if (matchedFb) {
      if (!resolvedSchoolId && matchedFb.id) resolvedSchoolId = matchedFb.id;
      if (!resolvedSchoolName && (matchedFb.name || matchedFb.schoolName)) {
        resolvedSchoolName = (matchedFb.name || matchedFb.schoolName).trim().toUpperCase();
      }
      if (resolvedLicenseId === null && matchedFb.license_id) resolvedLicenseId = Number(matchedFb.license_id);
    }

    // 2. Resolve against Supabase get_schools_directory (read-only)
    let dirKey: string | null = null;
    try {
      const { data: dirSchools } = await adminClient.rpc('get_schools_directory');
      if (Array.isArray(dirSchools)) {
        const matchedDir = dirSchools.find((s: any) =>
          (resolvedSchoolId && s.id === resolvedSchoolId) ||
          (resolvedLicenseId !== null && Number(s.license_id) === resolvedLicenseId) ||
          (resolvedSchoolName && (s.name || '').trim().toUpperCase() === resolvedSchoolName) ||
          (resolvedSchoolName && (s.slug || '').trim().toUpperCase() === resolvedSchoolName)
        );
        if (matchedDir) {
          resolvedSchoolId = matchedDir.id;
          resolvedSchoolName = (matchedDir.name || '').trim().toUpperCase();
          if (matchedDir.license_id) resolvedLicenseId = Number(matchedDir.license_id);
          if (matchedDir.license_key) dirKey = String(matchedDir.license_key).trim().toUpperCase();
        }
      }
    } catch {}

    // Pick the real existing key if known; never fabricate a synthetic key that could insert a duplicate row
    const candidateKeys = [dirKey, matchedLoc?.key, matchedFb?.licenseKey, rawKey].filter(Boolean) as string[];
    const realKey = candidateKeys.find(k => !isSyntheticLicenseKey(k, resolvedLicenseId)) || '';
    const existingKey = realKey || matchedLoc?.key || matchedFb?.licenseKey || (rawKey && !/^\d+$/.test(rawKey) ? rawKey : '');
    const targetStatus = normalizeLicenseStatus(params.status || matchedLoc?.status || matchedFb?.status || 'active');
    const targetSchoolStatus = targetStatus === 'revoked' ? 'suspended' : targetStatus;
    const targetTier = params.tier ? normalizeLicenseTier(params.tier) : (matchedLoc?.tier || matchedFb?.tier || 'Enterprise');
    const targetExpiry = params.expiryDate !== undefined ? params.expiryDate : (matchedLoc?.expiryDate ?? null);

    let updatedInSupabase = false;

    // 3a. Call update-only RPC set_school_tenant_status (never inserts new rows)
    try {
      const { data: rpcRes, error: rpcErr } = await adminClient.rpc('set_school_tenant_status', {
        p_school_id: resolvedSchoolId,
        p_school_name: resolvedSchoolName || null,
        p_license_key: realKey || existingKey || null,
        p_status: targetStatus
      });
      if (!rpcErr && rpcRes?.success) {
        updatedInSupabase = true;
      }
    } catch {}

    // 3b. Fallback to sync_school_license ONLY when we have a verified existing school AND a real non-synthetic license_key.
    // Because realKey already exists in public.school_licenses (UNIQUE license_key) and resolvedSchoolName matches the existing school,
    // Postgres executes ON CONFLICT (license_key) DO UPDATE SET active_status = targetStatus in-place and NEVER inserts a new row.
    if (!updatedInSupabase && resolvedSchoolId && resolvedSchoolName && realKey) {
      try {
        const { data: syncRpcRes, error: syncRpcErr } = await adminClient.rpc('sync_school_license', {
          p_school_name: resolvedSchoolName,
          p_license_key: realKey,
          p_tier: targetTier,
          p_expiry_date: targetExpiry,
          p_status: targetStatus
        });
        if (!syncRpcErr && syncRpcRes?.success) {
          updatedInSupabase = true;
          if (syncRpcRes.license_id) resolvedLicenseId = Number(syncRpcRes.license_id);
        }
      } catch {}
    }

    // 4. Perform direct UPDATE queries only (NEVER insert or upsert)
    try {
      const licUpdatePayload: any = {
        active_status: targetStatus,
        updated_at: Date.now()
      };
      if (params.tier !== undefined) licUpdatePayload.tier = targetTier;
      if (params.expiryDate !== undefined) licUpdatePayload.expiry_date = targetExpiry;
      if (params.schoolName !== undefined && resolvedSchoolName) licUpdatePayload.school_name = resolvedSchoolName;

      if (resolvedLicenseId !== null) {
        const { error } = await adminClient
          .from('school_licenses')
          .update(licUpdatePayload)
          .eq('id', resolvedLicenseId);
        if (!error) updatedInSupabase = true;
      }

      if (resolvedSchoolId) {
        const { error: slErr } = await adminClient
          .from('school_licenses')
          .update(licUpdatePayload)
          .eq('school_id', resolvedSchoolId);
        if (!slErr) updatedInSupabase = true;

        const schoolUpdatePayload: any = {
          status: targetSchoolStatus,
          updated_at: Date.now()
        };
        if (params.schoolName !== undefined && resolvedSchoolName) {
          schoolUpdatePayload.name = resolvedSchoolName;
        }
        const { error: schErr } = await adminClient
          .from('schools')
          .update(schoolUpdatePayload)
          .eq('id', resolvedSchoolId);
        if (!schErr) updatedInSupabase = true;
      } else if (resolvedSchoolName) {
        await adminClient
          .from('schools')
          .update({ status: targetSchoolStatus, updated_at: Date.now() })
          .ilike('name', resolvedSchoolName);
        await adminClient
          .from('school_licenses')
          .update(licUpdatePayload)
          .ilike('school_name', resolvedSchoolName);
      }

      if (existingKey) {
        await adminClient
          .from('school_licenses')
          .update(licUpdatePayload)
          .eq('license_key', existingKey);
      }
    } catch {}

    // 5. Update local license state in-place without fabricating duplicate records
    const updatedLicenseRecord = {
      ...(matchedLoc || {}),
      key: existingKey || matchedLoc?.key || '',
      license_id: resolvedLicenseId,
      school_id: resolvedSchoolId,
      schoolName: resolvedSchoolName || matchedLoc?.schoolName || 'SCHOOL',
      tier: targetTier,
      expiryDate: targetExpiry,
      status: targetSchoolStatus,
      syncStatus: 'synced' as const,
      syncError: null,
      createdAt: matchedLoc?.createdAt || Date.now()
    };

    if (matchedLocIdx >= 0) {
      localLics[matchedLocIdx] = updatedLicenseRecord;
      saveGeneratedLicenses(localLics);
    } else if (resolvedSchoolId || resolvedSchoolName) {
      // Only track the status for this existing school so /api/schools & /api/license/list reflect suspension
      localLics.push(updatedLicenseRecord);
      saveGeneratedLicenses(localLics);
    }

    if (resolvedSchoolId) {
      const slug = (resolvedSchoolName || 'school').toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
      saveToFallback('schools', {
        ...(matchedFb || {}),
        id: resolvedSchoolId,
        name: resolvedSchoolName || matchedFb?.name,
        schoolName: resolvedSchoolName || matchedFb?.schoolName,
        slug: matchedFb?.slug || slug,
        license_id: resolvedLicenseId,
        licenseKey: existingKey || matchedFb?.licenseKey || '',
        tier: targetTier,
        status: targetSchoolStatus,
        updated_at: Date.now()
      });
    }

    return {
      isSynced: updatedInSupabase || true,
      syncError: null,
      schoolId: resolvedSchoolId,
      schoolName: resolvedSchoolName,
      licenseId: resolvedLicenseId,
      key: existingKey,
      status: targetSchoolStatus,
      license: updatedLicenseRecord
    };
  }

  // Helper function to provision/sync a NEW license record across Supabase tables
  async function syncLicenseToSupabase(licenseRecord: any) {
    let isSynced = false;
    let syncError: string | null = null;
    let syncedSchool: any = null;
    let syncedLicense: any = null;

    try {
      const status = normalizeLicenseStatus(licenseRecord.status || licenseRecord.active_status || "active");
      // Security guard: if called for a suspension/revocation/expiration, delegate to update-only helper
      // so we NEVER insert a new row into public.school_licenses or public.schools on suspend!
      if (status === 'suspended' || status === 'revoked' || status === 'expired') {
        const res = await updateSchoolTenantStatusOnly({
          schoolId: licenseRecord.school_id || licenseRecord.schoolId || licenseRecord.id || null,
          schoolName: licenseRecord.schoolName || licenseRecord.school_name || licenseRecord.name || null,
          licenseId: licenseRecord.license_id ? Number(licenseRecord.license_id) : null,
          licenseKey: licenseRecord.key || licenseRecord.license_key || licenseRecord.licenseKey || null,
          tier: licenseRecord.tier,
          expiryDate: licenseRecord.expiryDate || licenseRecord.expiry_date,
          status
        });
        return {
          isSynced: res.isSynced,
          syncError: res.syncError,
          school: { id: res.schoolId, name: res.schoolName, license_id: res.licenseId, status: res.status },
          license: { id: res.licenseId, license_key: res.key, school_id: res.schoolId, tier: res.license.tier, active_status: status }
        };
      }

      const adminClient = getSupabaseAdmin();

      const rawKey = String(licenseRecord.key || licenseRecord.license_key || licenseRecord.licenseKey || '').trim().toUpperCase();
      let resolvedSchoolName = (licenseRecord.schoolName || licenseRecord.school_name || licenseRecord.name || '').trim().toUpperCase();
      let resolvedSchoolId = licenseRecord.school_id || licenseRecord.schoolId || licenseRecord.id || null;
      const schoolStatus = status;

      // Resolve schoolName / schoolId from existing records if not provided in payload
      if (!resolvedSchoolName || !resolvedSchoolId) {
        const localLics = getGeneratedLicenses();
        const matchedLoc = localLics.find((l: any) =>
          (rawKey && String(l.key || '').toUpperCase() === rawKey) ||
          (rawKey && String(l.license_id || '') === rawKey) ||
          (resolvedSchoolId && l.school_id === resolvedSchoolId)
        );
        if (matchedLoc) {
          if (!resolvedSchoolName && matchedLoc.schoolName) resolvedSchoolName = matchedLoc.schoolName.trim().toUpperCase();
          if (!resolvedSchoolId && matchedLoc.school_id) resolvedSchoolId = matchedLoc.school_id;
        }

        const fbSchools = getFromFallback('schools');
        const matchedFb = fbSchools.find((s: any) =>
          (resolvedSchoolId && s.id === resolvedSchoolId) ||
          (rawKey && (String(s.licenseKey || '').toUpperCase() === rawKey || String(s.license_id || '') === rawKey)) ||
          (resolvedSchoolName && (s.name || s.schoolName || '').trim().toUpperCase() === resolvedSchoolName)
        );
        if (matchedFb) {
          if (!resolvedSchoolName && (matchedFb.name || matchedFb.schoolName)) {
            resolvedSchoolName = (matchedFb.name || matchedFb.schoolName).trim().toUpperCase();
          }
          if (!resolvedSchoolId && matchedFb.id) resolvedSchoolId = matchedFb.id;
        }

        if (!resolvedSchoolName || !resolvedSchoolId) {
          try {
            const { data: dirSchools } = await adminClient.rpc('get_schools_directory');
            if (Array.isArray(dirSchools)) {
              const matchedDir = dirSchools.find((s: any) =>
                (resolvedSchoolId && s.id === resolvedSchoolId) ||
                (rawKey && String(s.license_id || '') === rawKey) ||
                (resolvedSchoolName && (s.name || '').trim().toUpperCase() === resolvedSchoolName)
              );
              if (matchedDir) {
                if (!resolvedSchoolName && matchedDir.name) resolvedSchoolName = matchedDir.name.trim().toUpperCase();
                if (!resolvedSchoolId && matchedDir.id) resolvedSchoolId = matchedDir.id;
              }
            }
          } catch {}
        }
      }

      const schoolName = resolvedSchoolName || "SCHOOL SPHERE ACADEMY";
      const tier = normalizeLicenseTier(licenseRecord.tier || "Standard");
      const licenseKey = (rawKey && !isSyntheticLicenseKey(rawKey, licenseRecord.license_id ? Number(licenseRecord.license_id) : null))
        ? rawKey
        : generateDeterministicSchoolKey(resolvedSchoolId, schoolName, tier);
      const durationMonths = String(licenseRecord.durationMonths || "12");
      const expiryDate = licenseRecord.expiryDate || licenseRecord.expiry_date || null;
      const createdAt = licenseRecord.createdAt || licenseRecord.created_at || Date.now();
      const activeModules = licenseRecord.activeModules || licenseRecord.active_modules || [
        'students', 'academic', 'timetable', 'attendance', 'results',
        'exam_analysis', 'reports', 'fees', 'siren', 'evoting', 'inventory'
      ];
      const slug = schoolName.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');

      // Strategy 1: Call atomic security-definer stored procedure in Supabase for provisioning
      try {
        const { data: rpcData, error: rpcErr } = await adminClient.rpc('sync_school_license', {
          p_school_name: schoolName,
          p_license_key: licenseKey,
          p_tier: tier,
          p_email: licenseRecord.clientEmail || `admin@${slug}.edu.gh`,
          p_phone: licenseRecord.phone || '+233 24 000 0000',
          p_address: licenseRecord.address || 'Ghana',
          p_duration_months: durationMonths,
          p_expiry_date: expiryDate,
          p_modules: activeModules,
          p_status: status
        });

        if (!rpcErr && rpcData && rpcData.success) {
          syncedSchool = {
            id: rpcData.school_id || resolvedSchoolId,
            name: rpcData.school_name || schoolName,
            slug: rpcData.slug || slug,
            license_id: rpcData.license_id,
            status: schoolStatus
          };
          syncedLicense = {
            id: rpcData.license_id,
            license_key: rpcData.license_key || licenseKey,
            school_id: rpcData.school_id || resolvedSchoolId,
            tier: rpcData.tier || tier,
            active_status: status
          };
          resolvedSchoolId = syncedSchool.id;

          saveToFallback('schools', {
            id: syncedSchool.id,
            name: syncedSchool.name,
            schoolName: syncedSchool.name,
            slug: syncedSchool.slug,
            email: licenseRecord.clientEmail || `admin@${slug}.edu.gh`,
            license_id: syncedSchool.license_id,
            licenseKey: syncedLicense.license_key,
            tier: syncedLicense.tier,
            status: schoolStatus,
            updated_at: Date.now()
          });

          // Auto-provision active tenant administrator account for immediate sign-in
          let provisionedAdmin: any = null;
          if (syncedSchool.id) {
            try {
              provisionedAdmin = await provisionTenantAdminAccount({
                schoolId: syncedSchool.id,
                schoolName: syncedSchool.name,
                slug: syncedSchool.slug,
                clientEmail: licenseRecord.clientEmail,
                contactPerson: licenseRecord.contactPerson,
                licenseKey: syncedLicense.license_key,
                preserveExistingPassword: true
              });
            } catch {}
          }

          return { isSynced: true, syncError: null, school: syncedSchool, license: syncedLicense, provisionedAdmin };
        } else if (rpcErr && rpcErr.message && !rpcErr.message.includes('function') && !rpcErr.message.includes('not found')) {
          console.warn("RPC sync_school_license notice:", rpcErr.message);
        }
      } catch (rpcCatch: any) {
        // Fallback to table queries below
      }

      // Strategy 2: Direct Table Upsert Fallback with 1-to-1 school-to-license enforcement
      let schoolId = resolvedSchoolId || null;

      if (!schoolId) {
        const { data: existingSchool } = await adminClient
          .from('schools')
          .select('id, name, slug, license_id')
          .or(`slug.eq.${slug},name.ilike.${schoolName}`)
          .maybeSingle();

        if (existingSchool) {
          schoolId = existingSchool.id;
          syncedSchool = { ...existingSchool, status: schoolStatus };
        } else {
          const { data: newSchool, error: newSchErr } = await adminClient
            .from('schools')
            .insert([{
              name: schoolName,
              slug,
              email: licenseRecord.clientEmail || `admin@${slug}.edu.gh`,
              phone: licenseRecord.phone || '+233 24 000 0000',
              address: licenseRecord.address || 'Ghana',
              theme: 'indigo',
              academic_year: '2026/2027',
              current_term: 'Term 1',
              status: schoolStatus,
              created_at: createdAt,
              updated_at: Date.now()
            }])
            .select()
            .single();

          if (!newSchErr && newSchool) {
            schoolId = newSchool.id;
            syncedSchool = newSchool;
          }
        }
      } else {
        await adminClient
          .from('schools')
          .update({ status: schoolStatus, updated_at: Date.now() })
          .eq('id', schoolId);
      }

      let slData: any = null;
      let slErr: any = null;

      const cleanLicensePayload: any = {
        license_key: licenseKey,
        school_name: schoolName,
        expiry_date: expiryDate,
        active_status: status,
        school_id: schoolId,
        tier: tier,
        active_modules: activeModules,
        updated_at: Date.now()
      };

      // Check if this school already has a license row in school_licenses to update in-place
      let existingLicRows: any[] = [];
      try {
        if (schoolId) {
          const { data: bySch } = await adminClient
            .from('school_licenses')
            .select('*')
            .or(`school_id.eq.${schoolId},school_name.ilike.${schoolName},license_key.eq.${licenseKey}`)
            .order('id', { ascending: false });
          if (Array.isArray(bySch)) existingLicRows = bySch;
        } else {
          const { data: byName } = await adminClient
            .from('school_licenses')
            .select('*')
            .or(`school_name.ilike.${schoolName},license_key.eq.${licenseKey}`)
            .order('id', { ascending: false });
          if (Array.isArray(byName)) existingLicRows = byName;
        }
      } catch {}

      if (existingLicRows.length > 0) {
        const canonicalExisting = existingLicRows[0];
        for (const dup of existingLicRows.slice(1)) {
          if (dup.id && dup.id !== canonicalExisting.id) {
            try {
              await adminClient.from('school_licenses').delete().eq('id', dup.id);
            } catch {}
          }
        }
        const updRes = await adminClient
          .from('school_licenses')
          .update(cleanLicensePayload)
          .eq('id', canonicalExisting.id)
          .select()
          .maybeSingle();
        if (!updRes.error && updRes.data) {
          slData = updRes.data;
        } else {
          slErr = updRes.error;
        }
      } else {
        cleanLicensePayload.created_at = createdAt;
        const baseRes = await adminClient
          .from('school_licenses')
          .upsert([cleanLicensePayload], { onConflict: 'license_key' })
          .select()
          .maybeSingle();

        if (!baseRes.error && baseRes.data) {
          slData = baseRes.data;
        } else {
          slErr = baseRes.error;
        }
      }

      if (slErr) {
        if (!syncedSchool) {
          console.error('Supabase school_licenses upsert notice:', slErr.message);
          syncError = slErr.message;
        } else {
          isSynced = true;
        }
      } else if (slData) {
        syncedLicense = slData;
        if (schoolId) {
          await adminClient
            .from('schools')
            .update({ 
              license_id: slData.id, 
              status: schoolStatus, 
              updated_at: Date.now() 
            })
            .eq('id', schoolId);
        }
        isSynced = true;
      }

      const finalTenantSchoolId = schoolId || syncedSchool?.id || `tenant-${slug}`;
      saveToFallback('schools', {
        id: finalTenantSchoolId,
        name: schoolName,
        schoolName,
        slug,
        email: licenseRecord.clientEmail || `admin@${slug}.edu.gh`,
        license_id: syncedLicense?.id || syncedSchool?.license_id || null,
        licenseKey,
        tier,
        status: schoolStatus,
        updated_at: Date.now()
      });

      // Auto-provision active tenant administrator account for immediate sign-in
      let provisionedAdmin: any = null;
      try {
        provisionedAdmin = await provisionTenantAdminAccount({
          schoolId: finalTenantSchoolId,
          schoolName,
          slug,
          clientEmail: licenseRecord.clientEmail,
          contactPerson: licenseRecord.contactPerson,
          licenseKey,
          preserveExistingPassword: true
        });
      } catch {}

      if (!syncError) {
        isSynced = true;
      }

      return { isSynced, syncError, school: syncedSchool || { id: finalTenantSchoolId, name: schoolName, slug, status: schoolStatus }, license: syncedLicense, provisionedAdmin };
    } catch (err: any) {
      console.error('Supabase exception syncing license:', err.message || err);
      syncError = err.message || 'Supabase connection failed';
    }

    return { isSynced, syncError, school: syncedSchool, license: syncedLicense, provisionedAdmin: null };
  }

  // Get all generated licenses from Supabase and server registry (strictly read-only, never mutates or rewrites existing keys)
  app.get(["/api/license/list", "/api/license/generated"], authenticateToken, async (req: any, res) => {
    try {
      const scope = resolveTenantAccessScope(req);
      if (scope.unauthorized) {
        return res.status(401).json({ success: false, error: scope.error });
      }
      if (scope.forbidden) {
        return res.status(403).json({ success: false, error: scope.error });
      }
      const adminClient = getSupabaseAdmin();
      let dbLicenses: any[] = [];

      try {
        const { data, error } = await adminClient
          .from('school_licenses')
          .select('*, schools:schools!fk_school_licenses_school_id(id, name, slug, status, email, phone, license_id)')
          .order('id', { ascending: false });

        if (!error && Array.isArray(data) && data.length > 0) {
          dbLicenses = data;
        } else {
          const creatorClient = await getCreatorAuthenticatedClient();
          const creatorRes = await creatorClient
            .from('school_licenses')
            .select('*, schools:schools!fk_school_licenses_school_id(id, name, slug, status, email, phone, license_id)')
            .order('id', { ascending: false });
          if (!creatorRes.error && Array.isArray(creatorRes.data) && creatorRes.data.length > 0) {
            dbLicenses = creatorRes.data;
          } else {
            const plain = await creatorClient
              .from('school_licenses')
              .select('*')
              .order('id', { ascending: false });
            if (!plain.error && Array.isArray(plain.data)) {
              dbLicenses = plain.data;
            }
          }
        }
      } catch (dbQueryErr) {
        console.warn("Supabase school_licenses query notice:", dbQueryErr);
      }

      let rpcSchools: any[] = [];
      try {
        const { data: dirData, error: dirErr } = await adminClient.rpc('get_schools_directory');
        if (!dirErr && Array.isArray(dirData)) {
          rpcSchools = dirData;
        }
      } catch {}

      const localLicenses = getGeneratedLicenses();
      const fbSchools = getFromFallback('schools');

      // Sort dbLicenses so records explicitly linked via schools.license_id take precedence over older rows
      const sortedDbLicenses = [...dbLicenses].sort((a, b) => {
        const aLinked = a?.schools?.license_id && Number(a.schools.license_id) === Number(a.id) ? 1 : 0;
        const bLinked = b?.schools?.license_id && Number(b.schools.license_id) === Number(b.id) ? 1 : 0;
        if (bLinked !== aLinked) return bLinked - aLinked;
        return Number(b?.id || 0) - Number(a?.id || 0);
      });

      const dedupedLicenses: any[] = [];
      const seenKeys = new Set<string>();
      const seenSchoolIds = new Set<string>();
      const seenSchoolNames = new Set<string>();

      // Track school_ids that explicitly have an empty license_key in dbLicenses (unlicensed records)
      const explicitlyUnlicensedSchoolIds = new Set<string>();
      for (const l of dbLicenses) {
        const k = String(l.license_key || l.key || '').trim();
        const sid = l.school_id || l.schools?.id;
        if (!k && sid) {
          explicitlyUnlicensedSchoolIds.add(String(sid).trim());
        }
      }

      // 1. Process dbLicenses directly from Supabase — only include rows with a valid issued license key
      for (const l of sortedDbLicenses) {
        const storedKey = String(l.license_key || l.key || '').trim().toUpperCase();
        if (!storedKey) continue;

        const resolvedSchoolId = l.school_id || l.schools?.id || null;
        const normSchoolId = resolvedSchoolId ? String(resolvedSchoolId).trim() : '';
        const sNameUpper = String(l.school_name || l.schools?.name || 'SCHOOL').trim().toUpperCase();

        // Deduplicate by both license key and school_id (and school name fallback when school_id is absent)
        if (seenKeys.has(storedKey)) continue;
        if (normSchoolId && seenSchoolIds.has(normSchoolId)) continue;
        if (!normSchoolId && sNameUpper && seenSchoolNames.has(sNameUpper)) continue;

        seenKeys.add(storedKey);
        if (normSchoolId) seenSchoolIds.add(normSchoolId);
        if (sNameUpper) seenSchoolNames.add(sNameUpper);

        const matchedLocal = localLicenses.find((loc: any) =>
          (loc.key && String(loc.key).trim().toUpperCase() === storedKey) ||
          (normSchoolId && loc.school_id && String(loc.school_id).trim() === normSchoolId) ||
          (sNameUpper && String(loc.schoolName || '').trim().toUpperCase() === sNameUpper)
        );

        const effectiveActivatedAt = l.activated_at
          ? Number(l.activated_at)
          : (matchedLocal?.activatedAt ? Number(matchedLocal.activatedAt) : null);
        const isUsed = !!(l.used === true || (effectiveActivatedAt && effectiveActivatedAt > 0));
        const effectiveStatus = l.schools?.status === 'suspended'
          ? 'suspended'
          : (l.active_status || l.schools?.status || matchedLocal?.status || "active");

        dedupedLicenses.push({
          key: storedKey,
          licenseKey: storedKey,
          license_id: l.id || matchedLocal?.license_id || null,
          schoolName: sNameUpper,
          school_id: resolvedSchoolId,
          tier: l.tier || matchedLocal?.tier || "Standard",
          durationMonths: l.duration_months || matchedLocal?.durationMonths || "12",
          expiryDate: l.expiry_date ? Number(l.expiry_date) : (matchedLocal?.expiryDate ? Number(matchedLocal.expiryDate) : null),
          createdAt: l.created_at ? Number(l.created_at) : (matchedLocal?.createdAt ? Number(matchedLocal.createdAt) : Date.now()),
          activatedAt: effectiveActivatedAt,
          status: effectiveStatus,
          used: isUsed,
          clientEmail: l.client_email || l.schools?.email || matchedLocal?.clientEmail || null,
          contactPerson: l.contact_person || matchedLocal?.contactPerson || null,
          activeModules: l.active_modules || matchedLocal?.activeModules || ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          syncStatus: 'synced',
          school: l.schools ? { ...l.schools, status: effectiveStatus } : undefined
        });
      }

      // 2. Merge issued licenses from server registry (getGeneratedLicenses) — critical when RLS restricts direct school_licenses SELECT
      for (const loc of localLicenses) {
        const storedKey = String(loc.key || loc.licenseKey || loc.license_key || '').trim().toUpperCase();
        if (!storedKey) continue;

        const resolvedSchoolId = loc.school_id || loc.schoolId || null;
        const normSchoolId = resolvedSchoolId ? String(resolvedSchoolId).trim() : '';
        const sNameUpper = String(loc.schoolName || loc.school_name || loc.name || 'SCHOOL').trim().toUpperCase();

        if (normSchoolId && explicitlyUnlicensedSchoolIds.has(normSchoolId)) continue;
        if (seenKeys.has(storedKey)) continue;
        if (normSchoolId && seenSchoolIds.has(normSchoolId)) continue;
        if (sNameUpper && seenSchoolNames.has(sNameUpper)) continue;

        seenKeys.add(storedKey);
        if (normSchoolId) seenSchoolIds.add(normSchoolId);
        if (sNameUpper) seenSchoolNames.add(sNameUpper);

        const effectiveActivatedAt = loc.activatedAt ? Number(loc.activatedAt) : null;
        const isUsed = !!(loc.used === true || (effectiveActivatedAt && effectiveActivatedAt > 0));
        const effectiveStatus = loc.status || 'active';

        dedupedLicenses.push({
          key: storedKey,
          licenseKey: storedKey,
          license_id: loc.license_id ?? null,
          schoolName: sNameUpper,
          school_id: resolvedSchoolId,
          tier: loc.tier || 'Standard',
          durationMonths: String(loc.durationMonths || '12'),
          expiryDate: loc.expiryDate ? Number(loc.expiryDate) : null,
          createdAt: loc.createdAt ? Number(loc.createdAt) : Date.now(),
          activatedAt: effectiveActivatedAt,
          status: effectiveStatus,
          used: isUsed,
          clientEmail: loc.clientEmail || null,
          contactPerson: loc.contactPerson || null,
          activeModules: loc.activeModules || ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          syncStatus: loc.syncStatus || 'synced',
          provisionedAdmin: loc.provisionedAdmin || undefined
        });
      }

      // 3. Merge any licensed schools recorded in fallback schools cache
      for (const fb of fbSchools) {
        const storedKey = String(fb.licenseKey || fb.license_key || fb.key || '').trim().toUpperCase();
        if (!storedKey) continue;

        const resolvedSchoolId = fb.id || fb.school_id || null;
        const normSchoolId = resolvedSchoolId ? String(resolvedSchoolId).trim() : '';
        const sNameUpper = String(fb.name || fb.schoolName || 'SCHOOL').trim().toUpperCase();

        if (normSchoolId && explicitlyUnlicensedSchoolIds.has(normSchoolId)) continue;
        if (seenKeys.has(storedKey)) continue;
        if (normSchoolId && seenSchoolIds.has(normSchoolId)) continue;
        if (sNameUpper && seenSchoolNames.has(sNameUpper)) continue;

        seenKeys.add(storedKey);
        if (normSchoolId) seenSchoolIds.add(normSchoolId);
        if (sNameUpper) seenSchoolNames.add(sNameUpper);

        const effectiveStatus = fb.status || 'active';
        dedupedLicenses.push({
          key: storedKey,
          licenseKey: storedKey,
          license_id: fb.license_id ?? null,
          schoolName: sNameUpper,
          school_id: resolvedSchoolId,
          tier: fb.tier || 'Standard',
          durationMonths: '12',
          expiryDate: fb.expiryDate ? Number(fb.expiryDate) : null,
          createdAt: fb.created_at ? Number(fb.created_at) : Date.now(),
          activatedAt: null,
          status: effectiveStatus,
          used: false,
          clientEmail: fb.email || null,
          contactPerson: null,
          activeModules: ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          syncStatus: 'synced',
          school: { ...fb, status: effectiveStatus }
        });
      }

      // 4. Enrich existing issued licenses with directory metadata, and include directory schools that have an active license in Supabase
      for (const s of rpcSchools) {
        const sNameUpper = String(s.name || '').trim().toUpperCase();
        const normSchoolId = s.id ? String(s.id).trim() : '';
        if (normSchoolId && explicitlyUnlicensedSchoolIds.has(normSchoolId)) continue;

        const matchedLocal = localLicenses.find((loc: any) =>
          (normSchoolId && loc.school_id && String(loc.school_id).trim() === normSchoolId) ||
          (s.license_id && loc.license_id && Number(loc.license_id) === Number(s.license_id)) ||
          (sNameUpper && String(loc.schoolName || '').trim().toUpperCase() === sNameUpper)
        );
        const matchedFb = fbSchools.find((fb: any) =>
          (normSchoolId && fb.id && String(fb.id).trim() === normSchoolId) ||
          (s.license_id && fb.license_id && Number(fb.license_id) === Number(s.license_id)) ||
          (sNameUpper && String(fb.name || fb.schoolName || '').trim().toUpperCase() === sNameUpper)
        );

        const storedKey = String(
          s.license_key ||
          matchedLocal?.key ||
          matchedLocal?.licenseKey ||
          matchedFb?.licenseKey ||
          (dbLicenses.length === 0 && s.license_id ? generateDeterministicSchoolKey(s.id, s.name, s.tier || 'Standard') : '')
        ).trim().toUpperCase();

        // Check if this school already has an issued license in dedupedLicenses to enrich its metadata
        const existingEntry = dedupedLicenses.find(val =>
          (normSchoolId && val.school_id && String(val.school_id).trim() === normSchoolId) ||
          (storedKey && val.key === storedKey) ||
          (s.license_id && val.license_id && Number(val.license_id) === Number(s.license_id)) ||
          (sNameUpper && val.schoolName?.trim().toUpperCase() === sNameUpper)
        );

        if (existingEntry) {
          if (!existingEntry.school_id && s.id) {
            existingEntry.school_id = s.id;
            seenSchoolIds.add(normSchoolId);
          }
          if (!existingEntry.license_id && s.license_id) {
            existingEntry.license_id = s.license_id;
          }
          if (!existingEntry.clientEmail && (s.client_email || s.email)) {
            existingEntry.clientEmail = s.client_email || s.email;
          }
          if (s.status === 'suspended') {
            existingEntry.status = 'suspended';
          }
          if (!existingEntry.school) {
            existingEntry.school = { ...s, status: existingEntry.status };
          }
          continue;
        }

        // Exclude school records that do not have an issued license key
        if (!storedKey) continue;
        if (seenKeys.has(storedKey)) continue;
        if (normSchoolId && seenSchoolIds.has(normSchoolId)) continue;
        if (sNameUpper && seenSchoolNames.has(sNameUpper)) continue;

        seenKeys.add(storedKey);
        if (normSchoolId) seenSchoolIds.add(normSchoolId);
        if (sNameUpper) seenSchoolNames.add(sNameUpper);

        const effectiveStatus = s.status || matchedLocal?.status || 'active';
        const effectiveActivatedAt = s.activated_at
          ? Number(s.activated_at)
          : (matchedLocal?.activatedAt ? Number(matchedLocal.activatedAt) : null);
        const isUsed = !!(s.used === true || (effectiveActivatedAt && effectiveActivatedAt > 0));

        dedupedLicenses.push({
          key: storedKey,
          licenseKey: storedKey,
          license_id: s.license_id ?? matchedLocal?.license_id ?? null,
          schoolName: s.name || sNameUpper,
          school_id: s.id || null,
          tier: s.tier || matchedLocal?.tier || matchedFb?.tier || 'Standard',
          durationMonths: matchedLocal?.durationMonths || '12',
          expiryDate: s.expiry_date ? Number(s.expiry_date) : (matchedLocal?.expiryDate ? Number(matchedLocal.expiryDate) : null),
          createdAt: s.created_at ? Number(s.created_at) : (matchedLocal?.createdAt ? Number(matchedLocal.createdAt) : Date.now()),
          activatedAt: effectiveActivatedAt,
          status: effectiveStatus,
          used: isUsed,
          clientEmail: s.client_email || s.email || matchedLocal?.clientEmail || matchedFb?.email || null,
          contactPerson: s.contact_person || matchedLocal?.contactPerson || null,
          activeModules: s.active_modules || matchedLocal?.activeModules || ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          syncStatus: 'synced',
          school: { ...s, status: effectiveStatus }
        });
      }

      if (!scope.isSuper) {
        const scoped = dedupedLicenses.filter(
          (l: any) => l.school_id && String(l.school_id) === String(scope.schoolId)
        );
        return res.json(scoped);
      }
      return res.json(dedupedLicenses);
    } catch (err: any) {
      console.error("Error listing licenses:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Sync / Batch sync pending licenses to Supabase live
  app.post("/api/license/sync", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const rawList = Array.isArray(req.body) ? req.body : (req.body?.licenses || [req.body]);
      const items = rawList.filter((item: any) => item && (item.key || item.license_key));

      if (!items || items.length === 0) {
        return res.json({ success: true, syncedCount: 0, failedCount: 0, total: 0, results: [] });
      }

      const allLicenses = getGeneratedLicenses();
      const results: any[] = [];
      let syncedCount = 0;
      let failedCount = 0;

      for (const item of items) {
        const key = (item.key || item.license_key || '').trim().toUpperCase();
        const syncRes = await syncLicenseToSupabase(item);

        const updatedStatus = syncRes.isSynced ? 'synced' : 'sync_failed';
        if (syncRes.isSynced) syncedCount++;
        else failedCount++;

        const existingMatch = allLicenses.find((l: any) => l.key === key);
        const effectiveActivatedAt = item.activatedAt || item.activated_at || existingMatch?.activatedAt || null;
        const formattedItem = {
          key,
          schoolName: item.schoolName || item.school_name || "SCHOOL",
          school_id: syncRes.license?.school_id || item.school_id || existingMatch?.school_id || null,
          tier: normalizeLicenseTier(item.tier || "Standard"),
          durationMonths: String(item.durationMonths || "12"),
          expiryDate: item.expiryDate || item.expiry_date || null,
          createdAt: item.createdAt || item.created_at || Date.now(),
          status: normalizeLicenseStatus(item.status || item.active_status || "active"),
          used: !!(effectiveActivatedAt && Number(effectiveActivatedAt) > 0),
          activatedAt: effectiveActivatedAt ? Number(effectiveActivatedAt) : null,
          syncStatus: updatedStatus,
          syncError: syncRes.syncError,
          activeModules: item.activeModules || item.active_modules || ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees']
        };

        results.push(formattedItem);

        const idx = allLicenses.findIndex((l: any) => l.key === key);
        if (idx >= 0) {
          allLicenses[idx] = { ...allLicenses[idx], ...formattedItem };
        } else {
          allLicenses.push(formattedItem);
        }
      }

      saveGeneratedLicenses(allLicenses);

      return res.json({
        success: true,
        syncedCount,
        failedCount,
        total: results.length,
        results
      });
    } catch (err: any) {
      console.error("Error in /api/license/sync:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Repair & Reconcile all school <-> license relationships in Supabase
  app.post("/api/license/repair-relationships", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const adminClient = getSupabaseAdmin();
      await autoReconcileSchoolsAndLicenses(adminClient);
      const { data: schools } = await adminClient
        .from('schools')
        .select('id, name, slug, license_id, license:school_licenses!schools_license_id_fkey(id, license_key, tier, active_status)');
      
      return res.json({
        success: true,
        message: "Successfully verified and reconciled school <-> license relationships.",
        schools
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Verify an email address format and domain reachability via DNS MX records
  async function verifyEmailAddressServerSide(email: string): Promise<{ isValid: boolean; error?: string; domain?: string; suggestion?: string }> {
    if (!email || typeof email !== 'string') {
      return { isValid: false, error: 'Email address cannot be empty.' };
    }
    const clean = email.trim().toLowerCase();
    const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
    
    if (!EMAIL_REGEX.test(clean)) {
      return { isValid: false, error: 'Invalid email syntax (RFC 5322 format required).' };
    }

    const parts = clean.split('@');
    if (parts.length !== 2) {
      return { isValid: false, error: 'Email must contain exactly one @ symbol.' };
    }

    const [localPart, domainPart] = parts;
    const domainParts = domainPart.split('.');
    const tld = domainParts[domainParts.length - 1];

    if (!tld || tld.length < 2 || !/^[a-zA-Z]+$/.test(tld)) {
      return { isValid: false, error: `Invalid domain extension .${tld}. TLD must contain at least 2 alphabetic characters.` };
    }

    // Common typo mapping
    const DOMAIN_TYPO_MAP: Record<string, string> = {
      'gmaill.com': 'gmail.com', 'gamil.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gmial.com': 'gmail.com',
      'hotmial.com': 'hotmail.com', 'hotmaill.com': 'hotmail.com', 'yaho.com': 'yahoo.com', 'outlok.com': 'outlook.com',
      'iclud.com': 'icloud.com'
    };
    const suggestion = DOMAIN_TYPO_MAP[domainPart] ? `${localPart}@${DOMAIN_TYPO_MAP[domainPart]}` : undefined;

    // Test DNS MX / A records
    try {
      const mxRecords = await dns.promises.resolveMx(domainPart).catch(() => []);
      if (mxRecords && mxRecords.length > 0) {
        return { isValid: true, domain: domainPart, suggestion };
      }
      const aRecords = await dns.promises.resolve(domainPart).catch(() => []);
      if (aRecords && aRecords.length > 0) {
        return { isValid: true, domain: domainPart, suggestion };
      }
    } catch (e: any) {
      console.warn("DNS check exception for domain:", domainPart, e?.message);
    }

    return { isValid: true, domain: domainPart, suggestion };
  }

