  // Dedicated test endpoint for verifying SMTP / Email settings with live feedback
  app.post("/api/email/test-smtp", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { to, customHost, customPort, customUser, customPass, customFrom } = req.body || {};
      const targetRecipient = (to || process.env.SMTP_USER || "amoakoemmanuel2026@gmail.com").trim();

      const host = customHost || process.env.SMTP_HOST || "smtp.gmail.com";
      const port = Number(customPort || process.env.SMTP_PORT || "587");
      const user = customUser || process.env.SMTP_USER;
      const pass = customPass || process.env.SMTP_PASS;
      const from = customFrom || process.env.SMTP_FROM || `"SchoolSphere Licensing" <${user || "no-reply@schoolsphere.xyz"}>`;

      const testCode = `ESEPA-TEST-${Math.random().toString(36).substring(2, 8).toUpperCase()}`;

      if (!user || !pass) {
        return res.status(400).json({
          success: false,
          error: "SMTP credentials not provided in request or environment variables (SMTP_USER / SMTP_PASS).",
          host,
          port,
          from,
          hasUser: !!user,
          hasPass: !!pass
        });
      }

      const transporter = nodemailer.createTransport({
        host,
        port,
        secure: port === 465,
        auth: { user, pass },
        tls: { rejectUnauthorized: false }
      });

      // Verify connection configuration
      await transporter.verify();

      const info = await transporter.sendMail({
        from,
        to: targetRecipient,
        subject: `[Test] SchoolSphere License Verification - ${testCode}`,
        html: `
          <div style="font-family: sans-serif; max-width: 500px; padding: 20px; border: 1px solid #e2e8f0; border-radius: 12px;">
            <h2 style="color: #1e1b4b; margin: 0 0 10px 0;">SMTP Test Successful!</h2>
            <p style="color: #334155; font-size: 14px;">This test email verifies that your server-side SMTP configuration is operating properly.</p>
            <div style="background: #0f172a; color: #38bdf8; font-family: monospace; font-size: 20px; font-weight: bold; padding: 14px; text-align: center; border-radius: 8px; margin: 16px 0;">
              ${testCode}
            </div>
            <p style="color: #64748b; font-size: 12px;">Sent from SchoolSphere Backend SMTP Engine at ${new Date().toISOString()}</p>
          </div>
        `
      });

      return res.json({
        success: true,
        message: `Test email successfully delivered to ${targetRecipient}!`,
        messageId: info.messageId,
        testCode,
        config: { host, port, user, from }
      });
    } catch (err: any) {
      console.error("Error in /api/email/test-smtp:", err);
      return res.status(500).json({
        success: false,
        error: err.message || "Failed to send test email via SMTP.",
        details: sanitizeErrorMessage(err)
      });
    }
  });

  // Generate a new license key and live sync to Supabase database (with verified email delivery)
  app.post("/api/license/generate", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { 
        schoolName, 
        durationMonths, 
        tier, 
        activeModules, 
        clientEmail, 
        contactPerson, 
        sendEmail, 
        redirectUrl,
        googleAccessToken
      } = req.body || {};

      if (!schoolName) {
        return res.status(400).json({ success: false, error: "School name is required" });
      }

      // Verify email if provided
      let cleanClientEmail: string | null = null;
      let emailValidationResult: any = null;
      if (clientEmail && clientEmail.trim()) {
        cleanClientEmail = clientEmail.trim().toLowerCase();
        emailValidationResult = await verifyEmailAddressServerSide(cleanClientEmail);
        if (!emailValidationResult.isValid) {
          return res.status(400).json({ 
            success: false, 
            error: `Invalid client email address: ${emailValidationResult.error || 'Please provide a valid email format.'}`,
            suggestion: emailValidationResult.suggestion 
          });
        }
      }

      const schoolPrefix = schoolName.trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "SCH";
      const normalizedTier = normalizeLicenseTier(tier || "Standard");
      const tierPrefix = normalizedTier.toUpperCase().slice(0, 3);
      const randomHash = Math.random().toString(36).substring(2, 8).toUpperCase();
      const key = `ESEPA-${schoolPrefix}-${tierPrefix}-${randomHash}`;

      const now = Date.now();
      let expiryDate: number | null = null;
      if (durationMonths && durationMonths !== "perpetual") {
        const months = parseInt(durationMonths) || 12;
        expiryDate = now + (months * 30 * 24 * 60 * 60 * 1000);
      }

      const modules = activeModules || [
        'students', 'academic', 'timetable', 'attendance', 'results',
        'exam_analysis', 'reports', 'fees', 'siren', 'evoting', 'inventory'
      ];

      const cleanContactPerson = contactPerson ? contactPerson.trim() : null;

      // Sync directly into Supabase database (schools + school_licenses)
      const syncRes = await syncLicenseToSupabase({
        key,
        schoolName: schoolName.trim().toUpperCase(),
        tier: normalizedTier,
        durationMonths: durationMonths || "12",
        expiryDate,
        createdAt: now,
        status: "active",
        activeModules: modules,
        clientEmail: cleanClientEmail,
        contactPerson: cleanContactPerson
      });

      if (!syncRes.isSynced) {
        return res.status(500).json({
          success: false,
          error: syncRes.syncError || "Failed to persist license key to Supabase database."
        });
      }

      // Handle sending license directly to client's email via multi-provider dispatcher
      let emailDispatched = false;
      let magicLinkUrl: string | null = null;
      let emailOtpCode: string | null = null;
      let emailNotice: string | null = null;
      let dispatchMethod: string = 'prepared';
      let mailContent: any = null;

      const headerGoogleToken = typeof req.headers['x-google-access-token'] === 'string'
        ? req.headers['x-google-access-token'].trim()
        : null;
      const candidateGoogleToken = googleAccessToken || headerGoogleToken || null;
      const effectiveGoogleToken =
        candidateGoogleToken &&
        typeof candidateGoogleToken === 'string' &&
        !candidateGoogleToken.trim().startsWith('eyJ') &&
        candidateGoogleToken.trim().split('.').length !== 3
          ? candidateGoogleToken.trim()
          : null;

      if (cleanClientEmail && (sendEmail !== false)) {
        const effectiveRedirect = redirectUrl || `https://ai.studio/apps/a3dcbc82-0bbd-43c0-9bc8-6b9090159f51?license=${encodeURIComponent(key)}`;

        // 1. Generate magic onboarding access link from Supabase
        const adminClient = getSupabaseAdmin();
        try {
          const { data: linkData } = await adminClient.auth.admin.generateLink({
            type: 'magiclink',
            email: cleanClientEmail,
            options: { redirectTo: effectiveRedirect }
          });
          if (linkData?.properties?.action_link) {
            magicLinkUrl = linkData.properties.action_link;
            emailOtpCode = linkData.properties.email_otp || null;
          }
        } catch (linkErr: any) {
          console.warn("Notice in generateLink:", linkErr?.message);
        }

        // 2. Dispatch license email via unified server engine (SMTP / Resend / Gmail API / direct prepared template)
        try {
          mailContent = await dispatchLicenseEmailServer({
            recipientEmail: cleanClientEmail,
            licenseKey: key,
            schoolName: schoolName.trim().toUpperCase(),
            tier: normalizedTier,
            durationMonths: durationMonths || "12",
            contactPerson: cleanContactPerson || undefined,
            activeModules: modules,
            magicLinkUrl: magicLinkUrl || undefined,
            googleToken: effectiveGoogleToken || undefined
          });

          emailDispatched = mailContent.dispatched;
          dispatchMethod = mailContent.method;
          if (emailDispatched) {
            emailNotice = `License dispatched directly via ${dispatchMethod.toUpperCase()} to ${cleanClientEmail}.`;
          } else {
            emailNotice = `License generated and delivery prepared for ${cleanClientEmail}.`;
          }
        } catch (dispatchErr: any) {
          console.warn("Notice in dispatchLicenseEmailServer:", dispatchErr?.message || dispatchErr);
        }

        // 3. Fallback to Supabase Auth email if not dispatched by other channels
        if (!emailDispatched) {
          try {
            const { error: otpError } = await adminClient.auth.signInWithOtp({
              email: cleanClientEmail,
              options: {
                emailRedirectTo: effectiveRedirect,
                shouldCreateUser: true,
                data: {
                  full_name: cleanContactPerson || `${schoolName} Administrator`,
                  role: 'admin',
                  license_key: key
                }
              }
            });

            if (!otpError) {
              emailDispatched = true;
              dispatchMethod = 'supabase';
              emailNotice = `License activation details dispatched to ${cleanClientEmail}.`;
            }
          } catch (emailErr: any) {
            console.warn("Notice sending fallback email:", emailErr?.message);
          }
        }
      } else if (cleanClientEmail) {
        mailContent = buildLicenseEmailContent({
          recipientEmail: cleanClientEmail,
          licenseKey: key,
          schoolName: schoolName.trim().toUpperCase(),
          tier: normalizedTier,
          durationMonths: durationMonths || "12",
          contactPerson: cleanContactPerson || undefined,
          activeModules: modules
        });
      }

      const finalKey = syncRes.license?.license_key || key;
      const newLicense = {
        key: finalKey,
        licenseKey: finalKey,
        license_id: syncRes.license?.id || syncRes.school?.license_id || null,
        schoolName: schoolName.trim().toUpperCase(),
        school_id: syncRes.school?.id || syncRes.license?.school_id || null,
        tier: normalizedTier,
        durationMonths: durationMonths || "12",
        expiryDate,
        createdAt: now,
        status: "active",
        used: false,
        activatedAt: null,
        clientEmail: cleanClientEmail,
        contactPerson: cleanContactPerson,
        emailVerified: cleanClientEmail ? true : false,
        lastEmailSentAt: emailDispatched ? Date.now() : null,
        emailDispatchMethod: dispatchMethod,
        syncStatus: 'synced' as const,
        syncError: null,
        activeModules: modules
      };

      const licenses = getGeneratedLicenses().filter(
        (l: any) =>
          l.key !== finalKey &&
          (!newLicense.school_id || l.school_id !== newLicense.school_id) &&
          String(l.schoolName || '').trim().toUpperCase() !== newLicense.schoolName
      );
      licenses.unshift(newLicense);
      saveGeneratedLicenses(licenses);

      // Record dispatch in Supabase DB
      if (cleanClientEmail) {
        try {
          const adminClient = getSupabaseAdmin();
          await adminClient.from('email_dispatch_logs').insert([{
            license_key: key,
            school_name: schoolName.trim().toUpperCase(),
            recipient_email: cleanClientEmail,
            contact_person: cleanContactPerson,
            dispatch_method: dispatchMethod || 'email',
            sent_at: Date.now()
          }]);
        } catch (e) {}
      }

      return res.json({ 
        success: true, 
        syncedToSupabase: syncRes.isSynced,
        syncStatus: newLicense.syncStatus,
        syncError: syncRes.syncError,
        license: newLicense,
        provisionedAdmin: (syncRes as any).provisionedAdmin || {
          username: cleanClientEmail ? cleanClientEmail.split('@')[0] : 'admin',
          scopedUsername: `admin@${schoolName.trim().toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '')}`,
          email: cleanClientEmail || `admin@${schoolName.trim().toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '')}.edu.gh`,
          initialPasswordHint: key
        },
        emailDispatched,
        dispatchMethod,
        emailRecipient: cleanClientEmail,
        emailNotice,
        magicLinkUrl,
        emailOtpCode,
        mailSubject: mailContent?.subject,
        mailBodyText: mailContent?.textBody,
        mailBodyHtml: mailContent?.htmlBody,
        mailtoUrl: mailContent?.mailtoUrl,
        activationUrl: mailContent?.activationUrl || (magicLinkUrl || `https://ai.studio/apps/a3dcbc82-0bbd-43c0-9bc8-6b9090159f51?license=${encodeURIComponent(key)}`),
        message: emailNotice || `License ${key} generated and administrator account provisioned for ${schoolName}.`
      });
    } catch (err: any) {
      console.error("Error in /api/license/generate:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Dedicated endpoint to send / resend any license key directly to client's email via Gmail or Supabase
  app.post("/api/license/send-email", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { licenseKey, recipientEmail, schoolName, contactPerson, redirectUrl, customMessage, googleAccessToken } = req.body || {};
      if (!licenseKey || !recipientEmail) {
        return res.status(400).json({ success: false, error: "License key and recipient email are required." });
      }

      const keyUpper = licenseKey.trim().toUpperCase();
      const cleanEmail = recipientEmail.trim().toLowerCase();

      // Verify email syntax & domain reachability
      const emailCheck = await verifyEmailAddressServerSide(cleanEmail);
      if (!emailCheck.isValid) {
        return res.status(400).json({
          success: false,
          error: `Invalid email address: ${emailCheck.error || 'Please provide a valid email format.'}`,
          suggestion: emailCheck.suggestion
        });
      }

      const adminClient = getSupabaseAdmin();

      // Retrieve license record
      const generated = getGeneratedLicenses();
      const localMatch = generated.find((l: any) => l.key === keyUpper);
      const effectiveSchoolName = (schoolName || localMatch?.schoolName || "SchoolSphere Institution").trim();
      const effectiveTier = localMatch?.tier || 'Standard';
      const effectiveDuration = localMatch?.durationMonths || '12';
      const effectiveModules = localMatch?.activeModules || [];

      // 1. Generate magic onboarding access link
      let magicLinkUrl: string | null = null;
      let emailOtpCode: string | null = null;
      const effectiveRedirect = redirectUrl || `https://ai.studio/apps/a3dcbc82-0bbd-43c0-9bc8-6b9090159f51?license=${encodeURIComponent(keyUpper)}`;

      try {
        const { data: linkData } = await adminClient.auth.admin.generateLink({
          type: 'magiclink',
          email: cleanEmail,
          options: { redirectTo: effectiveRedirect }
        });

        if (linkData?.properties?.action_link) {
          magicLinkUrl = linkData.properties.action_link;
          emailOtpCode = linkData.properties.email_otp || null;
        }
      } catch (genErr: any) {
        console.warn("Notice in generateLink:", genErr?.message);
      }

      let emailDispatched = false;
      let dispatchMethod: string = 'prepared';
      let mailContent: any = null;

      const headerGoogleToken = typeof req.headers['x-google-access-token'] === 'string'
        ? req.headers['x-google-access-token'].trim()
        : null;
      const authHeader = req.headers.authorization;
      const bearerToken = authHeader?.startsWith('Bearer ') ? authHeader.substring(7).trim() : null;
      const candidateGoogleToken = googleAccessToken || headerGoogleToken || (bearerToken && !bearerToken.startsWith('eyJ') && bearerToken.split('.').length !== 3 ? bearerToken : null);
      const effectiveGoogleToken =
        candidateGoogleToken &&
        typeof candidateGoogleToken === 'string' &&
        !candidateGoogleToken.trim().startsWith('eyJ') &&
        candidateGoogleToken.trim().split('.').length !== 3
          ? candidateGoogleToken.trim()
          : null;

      // 2. Dispatch license email via unified server engine (SMTP / Resend / Gmail API / direct prepared template)
      try {
        mailContent = await dispatchLicenseEmailServer({
          recipientEmail: cleanEmail,
          licenseKey: keyUpper,
          schoolName: effectiveSchoolName,
          tier: effectiveTier,
          durationMonths: effectiveDuration,
          contactPerson: contactPerson || localMatch?.contactPerson,
          activeModules: effectiveModules,
          magicLinkUrl: magicLinkUrl || undefined,
          customMessage,
          googleToken: effectiveGoogleToken || undefined
        });

        emailDispatched = mailContent.dispatched;
        dispatchMethod = mailContent.method;
      } catch (dispatchErr: any) {
        console.warn("Notice in dispatchLicenseEmailServer:", dispatchErr?.message || dispatchErr);
      }

      // 3. Fallback to Supabase Auth OTP / Notification if not sent by other providers
      if (!emailDispatched) {
        try {
          const { error: otpError } = await adminClient.auth.signInWithOtp({
            email: cleanEmail,
            options: {
              emailRedirectTo: effectiveRedirect,
              shouldCreateUser: true,
              data: {
                full_name: contactPerson || `${effectiveSchoolName} Administrator`,
                role: 'admin',
                license_key: keyUpper
              }
            }
          });

          if (!otpError) {
            emailDispatched = true;
            dispatchMethod = 'supabase';
          }
        } catch (otpErr: any) {
          console.warn("Notice in signInWithOtp:", otpErr?.message);
        }
      }

      // 4. Update local and Supabase license metadata with client email and timestamp
      const now = Date.now();
      if (localMatch) {
        localMatch.clientEmail = cleanEmail;
        if (contactPerson) localMatch.contactPerson = contactPerson;
        localMatch.lastEmailSentAt = now;
        localMatch.emailDispatchMethod = dispatchMethod;
        localMatch.emailVerified = true;
        saveGeneratedLicenses(generated);
      }

      // Persist directly into Supabase database (school_licenses & schools)
      try {
        await adminClient
          .from('school_licenses')
          .update({ 
            client_email: cleanEmail,
            contact_person: contactPerson || localMatch?.contactPerson || null,
            last_email_sent_at: now,
            updated_at: now 
          })
          .eq('license_key', keyUpper);
      } catch (dbErr: any) {
        console.warn("Notice updating license email in DB:", dbErr?.message);
      }

      // Record dispatch in email_dispatch_logs in Supabase
      try {
        await adminClient.from('email_dispatch_logs').insert([{
          license_key: keyUpper,
          school_name: effectiveSchoolName,
          recipient_email: cleanEmail,
          contact_person: contactPerson || localMatch?.contactPerson,
          dispatch_method: dispatchMethod,
          sent_at: now
        }]);
      } catch (e) {}

      return res.json({
        success: true,
        message: emailDispatched 
          ? `License key "${keyUpper}" dispatched via ${dispatchMethod.toUpperCase()} to ${cleanEmail}.`
          : `License key "${keyUpper}" delivery details generated for ${cleanEmail}.`,
        emailDispatched,
        licenseKey: keyUpper,
        recipientEmail: cleanEmail,
        dispatchMethod,
        schoolName: effectiveSchoolName,
        magicLinkUrl,
        emailOtpCode,
        mailSubject: mailContent?.subject,
        mailBodyText: mailContent?.textBody,
        mailBodyHtml: mailContent?.htmlBody,
        mailtoUrl: mailContent?.mailtoUrl,
        activationUrl: mailContent?.activationUrl || (magicLinkUrl || `https://ai.studio/apps/a3dcbc82-0bbd-43c0-9bc8-6b9090159f51?license=${encodeURIComponent(keyUpper)}`)
      });
    } catch (err: any) {
      console.error("Error in /api/license/send-email:", err);
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Dedicated endpoint for logging email dispatch directly from client-side Gmail API calls
  app.post("/api/license/log-email-dispatch", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { licenseKey, recipientEmail, schoolName, contactPerson, method = 'gmail', gmailMessageId } = req.body || {};
      const keyUpper = (licenseKey || '').trim().toUpperCase();
      const cleanEmail = (recipientEmail || '').trim().toLowerCase();
      const now = Date.now();

      // 1. Update local cache
      const generated = getGeneratedLicenses();
      const localMatch = generated.find((l: any) => l.key === keyUpper);
      if (localMatch) {
        localMatch.clientEmail = cleanEmail;
        if (contactPerson) localMatch.contactPerson = contactPerson;
        localMatch.lastEmailSentAt = now;
        localMatch.emailDispatchMethod = method;
        localMatch.emailVerified = true;
        saveGeneratedLicenses(generated);
      }

      // 2. Update Supabase database
      const adminClient = getSupabaseAdmin();
      try {
        await adminClient
          .from('school_licenses')
          .update({
            client_email: cleanEmail,
            contact_person: contactPerson || null,
            last_email_sent_at: now,
            updated_at: now
          })
          .eq('license_key', keyUpper);
      } catch (e) {}

      // 3. Insert audit log
      try {
        await adminClient.from('email_dispatch_logs').insert([{
          license_key: keyUpper,
          school_name: schoolName || localMatch?.schoolName || 'Unknown',
          recipient_email: cleanEmail,
          contact_person: contactPerson,
          dispatch_method: method,
          gmail_message_id: gmailMessageId || null,
          sent_at: now
        }]);
      } catch (e) {}

      return res.json({ success: true, stored: true });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Validate a license key directly against Supabase database
  app.post("/api/license/validate", async (req, res) => {
    try {
      const { key, licenseKey } = req.body || {};
      const targetKey = (key || licenseKey || '').trim().toUpperCase();

      if (!targetKey) {
        return res.status(400).json({ success: false, error: "License key is required" });
      }

      const adminClient = getSupabaseAdmin();

      // 1. Query Supabase school_licenses joined with schools
      const { data: licRow, error: licErr } = await adminClient
        .from('school_licenses')
        .select('*, schools!fk_school_licenses_school_id(id, name, slug, status)')
        .eq('license_key', targetKey)
        .maybeSingle();

      if (!licErr && licRow) {
        const isExpired = licRow.expiry_date && Number(licRow.expiry_date) < Date.now();
        const isActive = licRow.active_status === 'active' && !isExpired;
        const localMatch = getGeneratedLicenses().find((l: any) => l.key === targetKey);
        const isUsed = licRow.used === true || (licRow.activated_at && Number(licRow.activated_at) > 0) || localMatch?.used === true || (localMatch?.activatedAt && Number(localMatch.activatedAt) > 0);
        const effectiveActivatedAt = licRow.activated_at ? Number(licRow.activated_at) : (localMatch?.activatedAt ? Number(localMatch.activatedAt) : null);

        return res.json({
          success: true,
          active: isActive,
          tier: licRow.tier || localMatch?.tier || 'Standard',
          schoolName: licRow.school_name || licRow.schools?.name || localMatch?.schoolName || '',
          schoolId: licRow.school_id || localMatch?.school_id || null,
          expiryDate: licRow.expiry_date || localMatch?.expiryDate || null,
          activeModules: licRow.active_modules || localMatch?.activeModules || [],
          status: licRow.active_status || localMatch?.status || 'active',
          used: !!isUsed,
          activatedAt: effectiveActivatedAt
        });
      }

      // 2. Check registry of licenses in Supabase licenses table
      const { data: altLicRow } = await adminClient
        .from('licenses')
        .select('*')
        .eq('license_key', targetKey)
        .maybeSingle();

      if (altLicRow) {
        const isExpired = altLicRow.expires_at && new Date(altLicRow.expires_at).getTime() < Date.now();
        const isActive = (altLicRow.status === 'active' || altLicRow.active === true) && !isExpired;
        return res.json({
          success: true,
          active: isActive,
          tier: altLicRow.tier || 'Enterprise',
          schoolName: altLicRow.school_name || '',
          schoolId: altLicRow.school_id || null,
          expiryDate: altLicRow.expires_at || null,
          activeModules: altLicRow.active_modules || ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees'],
          status: isActive ? 'active' : 'expired',
          used: !!altLicRow.used,
          activatedAt: altLicRow.activated_at || null
        });
      }

      // 3. Check local generated licenses and auto-sync
      const generated = getGeneratedLicenses();
      const localMatch = generated.find((l: any) => l.key && l.key.trim().toUpperCase() === targetKey);
      if (localMatch) {
        const isUsed = !!(localMatch.activatedAt && Number(localMatch.activatedAt) > 0);
        const isExpired = localMatch.expiryDate && Number(localMatch.expiryDate) < Date.now();
        return res.json({
          success: true,
          active: localMatch.status === 'active' && !isExpired,
          status: localMatch.status || 'active',
          used: isUsed,
          activatedAt: localMatch.activatedAt || null,
          tier: localMatch.tier || 'Standard',
          schoolName: localMatch.schoolName,
          schoolId: localMatch.school_id || null,
          expiryDate: localMatch.expiryDate,
          activeModules: localMatch.activeModules || []
        });
      }

      // 4. Check fallback schools & get_schools_directory RPC
      const fbSchool = getFromFallback('schools').find((s: any) =>
        (s.licenseKey && s.licenseKey.trim().toUpperCase() === targetKey) ||
        (s.key && s.key.trim().toUpperCase() === targetKey)
      );
      if (fbSchool) {
        return res.json({
          success: true,
          active: fbSchool.status !== 'suspended',
          status: fbSchool.status || 'active',
          used: false,
          activatedAt: null,
          tier: fbSchool.tier || 'Standard',
          schoolName: fbSchool.name || fbSchool.schoolName || '',
          schoolId: fbSchool.id || null,
          expiryDate: null,
          activeModules: ['students', 'academic', 'timetable', 'attendance', 'results', 'reports', 'fees']
        });
      }

      return res.status(404).json({ success: false, error: "Invalid license key. Not found in registry." });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Update a license (edit tier, status, schoolName, duration, expiry, activeModules, clientEmail, contactPerson) in-place in Supabase
  const handleUpdateLicense = async (req: Request, res: Response) => {
    try {
      const {
        key,
        licenseKey,
        tier,
        status,
        schoolName,
        schoolId,
        school_id,
        expiryDate,
        durationMonths,
        activeModules,
        clientEmail,
        contactPerson,
        phone
      } = req.body || {};
      const rawKey = String(key || licenseKey || '').trim().toUpperCase();
      const targetSchoolId = schoolId || school_id || null;
      const targetSchoolName = (schoolName || '').trim().toUpperCase();

      if (!rawKey && !targetSchoolId && !targetSchoolName) {
        return res.status(400).json({ success: false, error: "License key or school identifier is required to update" });
      }

      let computedExpiry = expiryDate;
      if (computedExpiry === undefined && durationMonths !== undefined) {
        if (durationMonths === 'perpetual') {
          computedExpiry = null;
        } else {
          const months = parseInt(String(durationMonths), 10) || 12;
          computedExpiry = Date.now() + months * 30 * 24 * 60 * 60 * 1000;
        }
      }

      const updateRes = await updateSchoolTenantStatusOnly({
        schoolId: targetSchoolId,
        schoolName: targetSchoolName || undefined,
        licenseKey: rawKey || undefined,
        tier,
        expiryDate: computedExpiry,
        status
      });

      // Also persist additional fields (activeModules, clientEmail, contactPerson, durationMonths) directly to public.school_licenses & public.schools
      const adminClient = getSupabaseAdmin();
      const extraLicPatch: Record<string, any> = { updated_at: Date.now() };
      if (Array.isArray(activeModules)) extraLicPatch.active_modules = activeModules;
      if (clientEmail !== undefined) extraLicPatch.client_email = clientEmail ? String(clientEmail).trim().toLowerCase() : null;
      if (contactPerson !== undefined) extraLicPatch.contact_person = contactPerson ? String(contactPerson).trim() : null;
      if (durationMonths !== undefined) extraLicPatch.duration_months = String(durationMonths);
      if (phone !== undefined) extraLicPatch.phone = phone ? String(phone).trim() : null;

      if (Object.keys(extraLicPatch).length > 1) {
        try {
          if (rawKey) {
            await adminClient.from('school_licenses').update(extraLicPatch).eq('license_key', rawKey);
          } else if (updateRes.schoolId) {
            await adminClient.from('school_licenses').update(extraLicPatch).eq('school_id', updateRes.schoolId);
          }
        } catch {}
      }

      if (updateRes.schoolId && (clientEmail !== undefined || phone !== undefined || targetSchoolName)) {
        try {
          const schPatch: Record<string, any> = { updated_at: Date.now() };
          if (clientEmail !== undefined && clientEmail) schPatch.email = String(clientEmail).trim().toLowerCase();
          if (phone !== undefined && phone) schPatch.phone = String(phone).trim();
          if (targetSchoolName) schPatch.name = targetSchoolName;
          await adminClient.from('schools').update(schPatch).eq('id', updateRes.schoolId);
        } catch {}
      }

      return res.json({ 
        success: true, 
        syncedToSupabase: updateRes.isSynced,
        syncStatus: 'synced',
        syncError: updateRes.syncError,
        message: "License updated in-place and synced to Supabase database successfully", 
        license: {
          ...updateRes.license,
          ...(Array.isArray(activeModules) ? { activeModules } : {}),
          ...(clientEmail !== undefined ? { clientEmail } : {}),
          ...(contactPerson !== undefined ? { contactPerson } : {})
        }
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  };

  app.post("/api/license/update", authenticateToken, requireRoles("super_admin", "creator"), handleUpdateLicense);
  app.put("/api/license/update", authenticateToken, requireRoles("super_admin", "creator"), handleUpdateLicense);

  // Revoke a license key and suspend school access in-place in Supabase (never inserts new rows)
  app.post("/api/license/revoke", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { key, licenseKey, schoolId, school_id, schoolName, slug, status } = req.body || {};
      const rawKey = String(key ?? licenseKey ?? '').trim().toUpperCase();
      const targetSchoolId = schoolId || school_id || null;
      const targetSchoolName = String(schoolName || slug || '').trim().toUpperCase();
      const targetStatus = normalizeLicenseStatus(status || 'revoked');

      if (!rawKey && !targetSchoolId && !targetSchoolName) {
        return res.status(400).json({ success: false, error: "License key or school identifier is required to revoke" });
      }

      const updateRes = await updateSchoolTenantStatusOnly({
        schoolId: targetSchoolId,
        schoolName: targetSchoolName || undefined,
        slug: slug || undefined,
        licenseKey: rawKey || undefined,
        status: targetStatus
      });

      return res.json({
        success: true,
        status: targetStatus,
        schoolStatus: updateRes.status,
        schoolId: updateRes.schoolId,
        schoolName: updateRes.schoolName,
        key: updateRes.key || rawKey,
        message: `School license status updated to ${targetStatus} in Supabase.`
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // =========================================================================
  // CREATOR HUB TELEMETRY & SALES SUITE CRM ENDPOINTS (SUPABASE SINGLE SOURCE OF TRUTH)
  // =========================================================================

  // Live Platform Telemetry Counts, Real-Time Presence & Login Stream from Supabase for CreatorHub
  app.get("/api/creator/telemetry", authenticateToken, requireRoles("super_admin", "creator"), async (_req, res) => {
    try {
      const adminClient = getSupabaseAdmin();
      const fetchTableRows = async (table: string): Promise<any[]> => {
        try {
          const { data, error } = await adminClient.from(table).select('*');
          if (!error && Array.isArray(data)) return data;
        } catch {}
        return [];
      };

      const [
        studentsRows,
        rawDbTeachers,
        classesRows,
        subjectsRows,
        attendanceRows,
        resultsRows,
        reportsRows,
        feesRows,
        smsRows,
        pollsRows,
        candidatesRows,
        votesRows,
        inventoryRows,
        expensesRows,
        rawDbSchools,
        rawDbLicenses,
        dbUsersRes,
        dbAuditRes
      ] = await Promise.all([
        fetchTableRows('students'),
        fetchTableRows('teachers'),
        fetchTableRows('classes'),
        fetchTableRows('subjects'),
        fetchTableRows('attendance'),
        fetchTableRows('results'),
        fetchTableRows('term_reports'),
        fetchTableRows('fee_transactions'),
        fetchTableRows('sms_logs'),
        fetchTableRows('polls'),
        fetchTableRows('candidates'),
        fetchTableRows('votes'),
        fetchTableRows('inventory_items'),
        fetchTableRows('school_expenses'),
        fetchTableRows('schools'),
        fetchTableRows('school_licenses'),
        Promise.resolve(adminClient.from('users').select('*').order('last_login', { ascending: false, nullsFirst: false })).catch(() => ({ data: [] as any[] })),
        Promise.resolve(adminClient.from('audit_logs').select('*').order('timestamp', { ascending: false }).limit(250)).catch(() => ({ data: [] as any[] }))
      ]);

      const rawDbUsers = Array.isArray(dbUsersRes?.data) ? dbUsersRes.data : [];
      const rawDbAudits = Array.isArray(dbAuditRes?.data) ? dbAuditRes.data : [];

      const students = studentsRows.length;
      const teachers = rawDbTeachers.length;
      const classes = classesRows.length;
      const subjects = subjectsRows.length;
      const attendance = attendanceRows.length;
      const results = resultsRows.length;
      const reports = reportsRows.length;
      const fees = feesRows.length;
      const sms = smsRows.length;
      const polls = pollsRows.length;
      const candidates = candidatesRows.length;
      const votes = votesRows.length;
      const inventory = inventoryRows.length;
      const expenses = expensesRows.length;
      const schools = rawDbSchools.length;
      const licenses = rawDbLicenses.length;
      const users = rawDbUsers.length;
      const auditLogsCount = rawDbAudits.length;

      const totalRecords =
        students +
        teachers +
        classes +
        subjects +
        attendance +
        results +
        reports +
        fees +
        sms +
        polls +
        candidates +
        votes +
        inventory +
        expenses +
        schools +
        licenses +
        users +
        auditLogsCount;

      const schoolMap = new Map<string, string>();
      for (const s of rawDbSchools) {
        if (s?.id && s?.name) {
          schoolMap.set(String(s.id), String(s.name));
        }
      }
      const fbSchools = getFromFallback('schools');
      if (Array.isArray(fbSchools)) {
        for (const s of fbSchools) {
          if (s?.id && (s?.name || s?.schoolName) && !schoolMap.has(String(s.id))) {
            schoolMap.set(String(s.id), String(s.name || s.schoolName));
          }
        }
      }

      const now = Date.now();
      const ONLINE_WINDOW_MS = 180000; // 3 minutes active heartbeat window

      const activeSessions = getActiveUserSessions(ONLINE_WINDOW_MS);
      const userByIdMap = new Map<string, any>();
      const userByEmailMap = new Map<string, any>();
      const userByUsernameMap = new Map<string, any>();

      for (const u of rawDbUsers) {
        if (!u) continue;
        if (u.id !== undefined && u.id !== null) userByIdMap.set(String(u.id), u);
        if (u.auth_user_id) userByIdMap.set(String(u.auth_user_id), u);
        if (u.email) userByEmailMap.set(String(u.email).trim().toLowerCase(), u);
        if (u.username) userByUsernameMap.set(String(u.username).trim().toLowerCase(), u);
      }

      // Map latest audit timestamp per user from public.audit_logs
      const latestAuditByUserKey = new Map<string, { timestamp: number; logId: any; action: string }>();
      for (const log of rawDbAudits) {
        if (!log) continue;
        const actionStr = String(log.action || 'AUDIT_EVENT').toUpperCase();
        const ts = Number(log.timestamp || log.created_at || 0);
        if (!ts || ts <= 0) continue;
        const details =
          typeof log.details === 'string'
            ? (() => {
                try {
                  return JSON.parse(log.details);
                } catch {
                  return {};
                }
              })()
            : log.details || {};
        const keysToMap = [
          log.user_id !== undefined && log.user_id !== null ? `id:${log.user_id}` : '',
          details.email ? `email:${String(details.email).trim().toLowerCase()}` : '',
          details.username ? `user:${String(details.username).trim().toLowerCase()}` : ''
        ].filter(Boolean);
        for (const k of keysToMap) {
          const prev = latestAuditByUserKey.get(k);
          if (!prev || ts > prev.timestamp) {
            latestAuditByUserKey.set(k, { timestamp: ts, logId: log.id, action: actionStr });
          }
        }
      }

      // Build unified allUsers directory from public.users and public.teachers with verified live presence
      const allUsersList: any[] = [];
      const seenUserKeys = new Set<string>();

      // 1. First incorporate active sessions from server heartbeat store
      for (const sess of activeSessions) {
        const matchedDbUser =
          (sess.userId ? userByIdMap.get(String(sess.userId)) : null) ||
          (sess.authUserId ? userByIdMap.get(String(sess.authUserId)) : null) ||
          (sess.email ? userByEmailMap.get(sess.email.toLowerCase()) : null) ||
          (sess.username ? userByUsernameMap.get(sess.username.toLowerCase()) : null);

        const role = String(sess.role || matchedDbUser?.role || 'admin').toLowerCase();
        const schoolId = sess.schoolId || matchedDbUser?.school_id || null;
        const schoolName =
          sess.schoolName && sess.schoolName !== 'SchoolSphere Portal'
            ? sess.schoolName
            : schoolId && schoolMap.has(String(schoolId))
              ? schoolMap.get(String(schoolId))!
              : role === 'creator' || role === 'super_admin'
                ? 'Platform Global Scope'
                : 'SchoolSphere Portal';

        const dedupeKey = String(
          matchedDbUser?.id || sess.authUserId || sess.email || `${sess.username}@${schoolId || 'global'}`
        ).toLowerCase();

        if (seenUserKeys.has(dedupeKey)) continue;
        seenUserKeys.add(dedupeKey);

        const verifiedLoginTs = Number(sess.loginTimestamp || matchedDbUser?.last_login || now);

        allUsersList.push({
          id: matchedDbUser?.id || sess.userId || sess.sessionKey,
          dbId: matchedDbUser?.id || null,
          sourceTable: 'public.users',
          authUserId: sess.authUserId || matchedDbUser?.auth_user_id || null,
          username: sess.username || matchedDbUser?.username || 'user',
          fullName: sess.fullName || matchedDbUser?.full_name || sess.username || 'User',
          email: sess.email || matchedDbUser?.email || '',
          role,
          schoolId,
          schoolName,
          isOnline: Boolean(sess.isOnline),
          lastActiveTimestamp: Number(sess.lastActiveTimestamp || now),
          loginTimestamp: verifiedLoginTs,
          createdAt: Number(matchedDbUser?.created_at || 0) || null,
          authStatus: sess.isOnline ? 'Online · Authenticated' : 'Logged Out'
        });
      }

      // 2. Add remaining users from Supabase public.users (strictly preserving null last_login as Never Logged In)
      for (const u of rawDbUsers) {
        if (!u.school_id && !u.role && !u.username && !u.email) continue;
        const role = String(u.role || 'admin').toLowerCase();
        const schoolId = u.school_id || null;
        const dedupeKey = String(u.id || u.auth_user_id || u.email || `${u.username}@${schoolId || 'global'}`).toLowerCase();
        if (seenUserKeys.has(dedupeKey)) continue;

        const emailLower = String(u.email || '').trim().toLowerCase();
        const unameLower = String(u.username || '').trim().toLowerCase();
        const alreadyInList = allUsersList.some(
          (item) =>
            (u.id !== undefined && u.id !== null && String(item.dbId) === String(u.id)) ||
            (emailLower && item.email && item.email.toLowerCase() === emailLower) ||
            (unameLower && item.username?.toLowerCase() === unameLower && String(item.schoolId || '') === String(schoolId || ''))
        );
        if (alreadyInList) continue;
        seenUserKeys.add(dedupeKey);

        const auditMatch =
          latestAuditByUserKey.get(`id:${u.id}`) ||
          (emailLower ? latestAuditByUserKey.get(`email:${emailLower}`) : undefined) ||
          (unameLower ? latestAuditByUserKey.get(`user:${unameLower}`) : undefined);

        const rawLastLoginMs = Number(u.last_login || 0);
        const verifiedLoginMs = Math.max(rawLastLoginMs, auditMatch?.timestamp || 0);
        const hasEverLoggedIn = verifiedLoginMs > 0;

        const schoolName =
          schoolId && schoolMap.has(String(schoolId))
            ? schoolMap.get(String(schoolId))!
            : role === 'creator' || role === 'super_admin'
              ? 'Platform Global Scope'
              : 'SchoolSphere Portal';

        allUsersList.push({
          id: u.id,
          dbId: u.id,
          sourceTable: 'public.users',
          authUserId: u.auth_user_id || null,
          username: u.username || (emailLower ? emailLower.split('@')[0] : 'user'),
          fullName: u.full_name || u.username || 'User',
          email: u.email || '',
          role,
          schoolId,
          schoolName,
          isOnline: false,
          lastActiveTimestamp: hasEverLoggedIn ? verifiedLoginMs : null,
          loginTimestamp: hasEverLoggedIn ? verifiedLoginMs : null,
          createdAt: Number(u.created_at || 0) || null,
          authStatus: hasEverLoggedIn
            ? auditMatch?.action === 'USER_LOGOUT'
              ? 'Logged Out'
              : 'Session Recorded'
            : 'Never Logged In'
        });
      }

      // 3. Also include staff profiles from Supabase public.teachers not yet in public.users
      for (const t of rawDbTeachers) {
        if (!t) continue;
        const emailLower = String(t.email || '').trim().toLowerCase();
        const tName = String(t.name || [t.first_name, t.last_name].filter(Boolean).join(' ') || '').trim();
        const schoolId = t.school_id || null;
        const unameLower = emailLower ? emailLower.split('@')[0] : tName.toLowerCase().replace(/\s+/g, '.');

        const alreadyInList = allUsersList.some(
          (item) =>
            (t.user_id && String(item.dbId) === String(t.user_id)) ||
            (emailLower && item.email && item.email.toLowerCase() === emailLower) ||
            (tName && String(item.fullName || '').trim().toLowerCase() === tName.toLowerCase() && String(item.schoolId || '') === String(schoolId || ''))
        );
        if (alreadyInList) continue;

        const schoolName =
          schoolId && schoolMap.has(String(schoolId)) ? schoolMap.get(String(schoolId))! : 'SchoolSphere Portal';

        allUsersList.push({
          id: `teacher-${t.id}`,
          dbId: t.id,
          sourceTable: 'public.teachers',
          authUserId: null,
          username: t.staff_id || unameLower || 'teacher',
          fullName: tName || 'Teacher',
          email: t.email || '',
          role: 'teacher',
          schoolId,
          schoolName,
          isOnline: false,
          lastActiveTimestamp: null,
          loginTimestamp: null,
          createdAt: Number(t.created_at || 0) || null,
          authStatus: 'Never Logged In'
        });
      }

      const onlineUsers = allUsersList
        .filter((u) => u.isOnline)
        .sort((a, b) => (b.lastActiveTimestamp || 0) - (a.lastActiveTimestamp || 0));

      // Build chronological Recent Logins & Audit Stream from public.audit_logs & verified public.users.last_login > 0
      const recentLogins: any[] = [];
      const seenLoginEvents = new Set<string>();

      const pushLoginEntry = (entry: {
        id: string;
        auditLogId?: number | string | null;
        sourceTable?: string;
        action?: string;
        userId?: any;
        authUserId?: string | null;
        username?: string;
        fullName?: string;
        email?: string;
        role?: string;
        schoolId?: string | null;
        schoolName?: string;
        status?: string;
        loginTimestamp: number;
        lastActiveTimestamp?: number;
        ipAddress?: string;
      }) => {
        if (!entry.loginTimestamp || entry.loginTimestamp <= 0) return;
        const matchedUser =
          (entry.userId !== undefined && entry.userId !== null ? userByIdMap.get(String(entry.userId)) : null) ||
          (entry.authUserId ? userByIdMap.get(String(entry.authUserId)) : null) ||
          (entry.email ? userByEmailMap.get(String(entry.email).toLowerCase()) : null) ||
          (entry.username ? userByUsernameMap.get(String(entry.username).toLowerCase()) : null);

        const email = String(entry.email || matchedUser?.email || '').trim().toLowerCase();
        const username = String(entry.username || matchedUser?.username || (email ? email.split('@')[0] : 'user')).trim();
        const fullName = String(entry.fullName || matchedUser?.full_name || username).trim();
        const role = String(entry.role || matchedUser?.role || 'admin').toLowerCase();
        const schoolId = entry.schoolId || matchedUser?.school_id || null;
        const schoolName =
          entry.schoolName && entry.schoolName !== 'SchoolSphere Portal'
            ? entry.schoolName
            : schoolId && schoolMap.has(String(schoolId))
              ? schoolMap.get(String(schoolId))!
              : role === 'creator' || role === 'super_admin'
                ? 'Platform Global Scope'
                : 'SchoolSphere Portal';

        // Deduplicate events within 5 seconds for same user & action
        const timeBucket = Math.floor(entry.loginTimestamp / 5000);
        const eventKey = `${email || username}::${timeBucket}::${entry.action || entry.status || 'auth'}`;
        if (seenLoginEvents.has(eventKey)) return;
        seenLoginEvents.add(eventKey);

        const matchingLiveUser = allUsersList.find(
          (u) =>
            (matchedUser?.id && String(u.dbId) === String(matchedUser.id)) ||
            (email && u.email && u.email.toLowerCase() === email) ||
            (u.username?.toLowerCase() === username.toLowerCase() && String(u.schoolId || '') === String(schoolId || ''))
        );

        const isOnline = Boolean(matchingLiveUser?.isOnline);
        const lastActiveTimestamp = Number(
          matchingLiveUser?.lastActiveTimestamp || entry.lastActiveTimestamp || entry.loginTimestamp
        );

        recentLogins.push({
          id: entry.id,
          auditLogId: entry.auditLogId || null,
          dbId: matchedUser?.id || entry.userId || null,
          sourceTable: entry.sourceTable || 'public.audit_logs',
          action: entry.action || 'USER_LOGIN',
          userId: matchedUser?.id || entry.userId || username,
          authUserId: entry.authUserId || matchedUser?.auth_user_id || null,
          username,
          fullName,
          email,
          role,
          schoolId,
          schoolName,
          isOnline,
          loginTimestamp: entry.loginTimestamp,
          lastActiveTimestamp,
          authStatus: entry.status || 'Authenticated',
          ipAddress: entry.ipAddress || undefined
        });
      };

      // 1. Authoritative Supabase public.audit_logs entries (both USER_LOGIN / USER_LOGOUT and authenticated audit actions)
      for (const log of rawDbAudits) {
        if (!log) continue;
        const actionStr = String(log.action || 'AUDIT_EVENT').toUpperCase();
        const details =
          typeof log.details === 'string'
            ? (() => {
                try {
                  return JSON.parse(log.details);
                } catch {
                  return {};
                }
              })()
            : log.details || {};
        const statusLabel =
          actionStr === 'USER_LOGIN_FAILED'
            ? 'Failed Attempt'
            : actionStr === 'USER_LOGOUT'
              ? 'Logged Out'
              : actionStr === 'USER_LOGIN'
                ? details.authStatus || 'Authenticated (USER_LOGIN)'
                : `Audit: ${actionStr}`;

        pushLoginEntry({
          id: `audit-${log.id}`,
          auditLogId: log.id,
          sourceTable: 'public.audit_logs',
          action: actionStr,
          userId: log.user_id ?? log.entity_id,
          authUserId: details.authUserId || null,
          username: details.username,
          fullName: details.fullName || details.full_name || details.squelchedBy,
          email: details.email,
          role: details.role,
          schoolId: log.school_id || null,
          schoolName: details.schoolName || details.school_name,
          status: statusLabel,
          loginTimestamp: Number(log.timestamp || log.created_at || 0),
          ipAddress: log.ip_address
        });
      }

      // 2. In-memory login activities (for current server instance before/during DB flush)
      for (const act of getRecentLoginActivities()) {
        pushLoginEntry({
          id: act.id,
          sourceTable: 'public.audit_logs',
          action: String(act.status || '').toLowerCase().includes('fail') ? 'USER_LOGIN_FAILED' : 'USER_LOGIN',
          userId: act.user_id,
          authUserId: act.auth_user_id,
          username: act.username,
          fullName: act.full_name,
          email: act.email,
          role: act.role,
          schoolId: act.organization_id || null,
          schoolName: act.school_name,
          status: act.status,
          loginTimestamp: Number(act.login_timestamp || 0),
          lastActiveTimestamp: Number(act.last_active_timestamp || act.login_timestamp || 0),
          ipAddress: act.ip_address
        });
      }

      // 3. Users in public.users who have a real last_login > 0 (never include users where last_login is null!)
      for (const u of rawDbUsers) {
        const lastLoginMs = Number(u.last_login || 0);
        if (lastLoginMs > 0) {
          const alreadyHasRecentAudit = recentLogins.some(
            (r) =>
              (String(r.dbId) === String(u.id) || (u.email && r.email === String(u.email).toLowerCase())) &&
              Math.abs(r.loginTimestamp - lastLoginMs) < 60000
          );
          if (!alreadyHasRecentAudit) {
            pushLoginEntry({
              id: `user-last-login-${u.id}`,
              sourceTable: 'public.users',
              action: 'LAST_LOGIN',
              userId: u.id,
              authUserId: u.auth_user_id,
              username: u.username,
              fullName: u.full_name || u.username,
              email: u.email,
              role: u.role,
              schoolId: u.school_id,
              status: 'Last Login (public.users)',
              loginTimestamp: lastLoginMs,
              lastActiveTimestamp: lastLoginMs
            });
          }
        }
      }

      recentLogins.sort((a, b) => b.loginTimestamp - a.loginTimestamp);

      // Compute authentic monthlyGrowthSeries directly from real Supabase created_at and timestamp fields (zero synthetic multipliers)
      const toValidMs = (raw: any): number | null => {
        if (raw === null || raw === undefined || raw === '') return null;
        if (typeof raw === 'number' && Number.isFinite(raw) && raw > 946684800000) return raw;
        if (typeof raw === 'number' && Number.isFinite(raw) && raw > 946684800 && raw < 10000000000) return raw * 1000;
        if (typeof raw === 'string') {
          const trimmed = raw.trim();
          if (/^\d+$/.test(trimmed)) {
            const n = Number(trimmed);
            if (n > 946684800000) return n;
            if (n > 946684800 && n < 10000000000) return n * 1000;
          }
          const parsed = Date.parse(trimmed);
          if (!isNaN(parsed) && parsed > 946684800000) return parsed;
        }
        return null;
      };

      const allRecordTimestamps: number[] = [];
      const pushRowTs = (rows: any[]) => {
        for (const r of rows) {
          const ms = toValidMs(
            r?.created_at ?? r?.timestamp ?? r?.date ?? r?.last_updated ?? r?.activated_at ?? r?.updated_at
          );
          if (ms) allRecordTimestamps.push(ms);
        }
      };

      pushRowTs(studentsRows);
      pushRowTs(rawDbTeachers);
      pushRowTs(classesRows);
      pushRowTs(subjectsRows);
      pushRowTs(attendanceRows);
      pushRowTs(resultsRows);
      pushRowTs(reportsRows);
      pushRowTs(feesRows);
      pushRowTs(smsRows);
      pushRowTs(pollsRows);
      pushRowTs(candidatesRows);
      pushRowTs(votesRows);
      pushRowTs(inventoryRows);
      pushRowTs(expensesRows);
      pushRowTs(rawDbSchools);
      pushRowTs(rawDbLicenses);
      pushRowTs(rawDbUsers);
      pushRowTs(rawDbAudits);

      const allLoginTimestamps: number[] = [];
      for (const r of recentLogins) {
        const ms = toValidMs(r.loginTimestamp);
        if (ms) allLoginTimestamps.push(ms);
      }

      // Build chronological monthly buckets covering the last 6 calendar months (plus any earlier month with real records)
      const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      const monthKeySet = new Set<string>();
      const nowDate = new Date(now);
      for (let i = 5; i >= 0; i--) {
        const d = new Date(nowDate.getFullYear(), nowDate.getMonth() - i, 1);
        const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        monthKeySet.add(ym);
      }
      for (const ms of [...allRecordTimestamps, ...allLoginTimestamps]) {
        const d = new Date(ms);
        const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        monthKeySet.add(ym);
      }

      const sortedMonthKeys = Array.from(monthKeySet).sort();
      const displayMonthKeys = sortedMonthKeys.slice(-6);
      const earlierMonthKeys = sortedMonthKeys.slice(0, Math.max(0, sortedMonthKeys.length - 6));

      const recordsByMonth = new Map<string, number>();
      const loginsByMonth = new Map<string, number>();

      for (const ms of allRecordTimestamps) {
        const d = new Date(ms);
        const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        recordsByMonth.set(ym, (recordsByMonth.get(ym) || 0) + 1);
      }
      for (const ms of allLoginTimestamps) {
        const d = new Date(ms);
        const ym = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        loginsByMonth.set(ym, (loginsByMonth.get(ym) || 0) + 1);
      }

      // Only count records that have an actual timestamp in their respective month; untimestamped rows are added to the current month's real snapshot
      const untimestampedCount = Math.max(0, totalRecords - allRecordTimestamps.length);
      let cumulativeRecords = 0;
      for (const ym of earlierMonthKeys) {
        cumulativeRecords += recordsByMonth.get(ym) || 0;
      }

      const monthlyGrowthSeries = displayMonthKeys.map((ym, idx) => {
        const [yrStr, moStr] = ym.split('-');
        const moIdx = Math.max(0, Math.min(11, parseInt(moStr, 10) - 1));
        const isLastBucket = idx === displayMonthKeys.length - 1;
        const newInMonth = (recordsByMonth.get(ym) || 0) + (isLastBucket ? untimestampedCount : 0);
        cumulativeRecords += newInMonth;
        const loginsInMonth = loginsByMonth.get(ym) || 0;
        return {
          monthKey: ym,
          name: `${monthNames[moIdx]} ${yrStr.slice(2)}`,
          records: cumulativeRecords,
          newRecords: newInMonth,
          logins: loginsInMonth
        };
      });

      return res.json({
        success: true,
        counts: {
          students,
          teachers,
          classes,
          subjects,
          attendance,
          results,
          reports,
          fees,
          sms,
          polls,
          candidates,
          votes,
          inventory,
          expenses,
          schools,
          licenses,
          users,
          auditLogs: auditLogsCount
        },
        totalRecords,
        monthlyGrowthSeries,
        onlineUsers,
        recentLogins: recentLogins.slice(0, 100),
        allUsers: allUsersList,
        timestamp: now
      });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // Helper to read/write auxiliary JSON arrays in memory + public.school_settings.streams
  const inMemoryAuxiliarySettings = new Map<string, any[]>();

  async function readSupabaseSettingList(settingKey: string): Promise<any[]> {
    if (inMemoryAuxiliarySettings.has(settingKey)) {
      return inMemoryAuxiliarySettings.get(settingKey) || [];
    }
    try {
      const adminClient = getSupabaseAdmin();
      const { data } = await adminClient
        .from('school_settings')
        .select('streams')
        .limit(50);
      if (Array.isArray(data)) {
        for (const row of data) {
          const val = (row?.streams as any)?.settings_kv?.[settingKey] ?? (row?.streams as any)?.[settingKey];
          if (Array.isArray(val)) {
            inMemoryAuxiliarySettings.set(settingKey, val);
            return val;
          }
        }
      }
    } catch {}
    return [];
  }

  async function writeSupabaseSettingList(settingKey: string, list: any[]): Promise<void> {
    inMemoryAuxiliarySettings.set(settingKey, Array.isArray(list) ? list : []);
    try {
      const adminClient = getSupabaseAdmin();
      const { data: existing } = await adminClient
        .from('school_settings')
        .select('school_id, grade_boundaries, terms, streams')
        .limit(1)
        .maybeSingle();
      if (existing?.school_id) {
        const prevStreams = (existing.streams && typeof existing.streams === 'object' && !Array.isArray(existing.streams))
          ? { ...(existing.streams as Record<string, any>) }
          : {};
        prevStreams.settings_kv = {
          ...(prevStreams.settings_kv && typeof prevStreams.settings_kv === 'object' ? prevStreams.settings_kv : {}),
          [settingKey]: list
        };
        await adminClient
          .from('school_settings')
          .update({ streams: prevStreams, updated_at: Date.now() })
          .eq('school_id', existing.school_id);
      }
    } catch {}
  }

  // Sales Suite CRM Leads CRUD (Supabase public.crm_leads + public.settings fallback)
  app.get("/api/crm/leads", authenticateToken, requireRoles("super_admin", "creator"), async (_req, res) => {
    try {
      const adminClient = getSupabaseAdmin();
      const { data, error } = await adminClient
        .from('crm_leads')
        .select('*')
        .order('created_at', { ascending: false });

      if (!error && Array.isArray(data)) {
        const formatted = data.map((row: any) => ({
          id: String(row.id),
          schoolName: row.school_name || row.schoolName || '',
          contactPerson: row.contact_person || row.contactPerson || '',
          email: row.email || '',
          phone: row.phone || '',
          location: row.location || 'Accra, Ghana',
          estimatedStudents: Number(row.estimated_students ?? row.estimatedStudents ?? 250),
          stage: row.stage || 'New',
          expectedTier: row.expected_tier || row.expectedTier || 'Standard',
          dealValue: Number(row.deal_value ?? row.dealValue ?? 950),
          notes: row.notes || '',
          followUpDate: row.follow_up_date || row.followUpDate || '',
          createdAt: Number(row.created_at ?? row.createdAt ?? Date.now())
        }));
        return res.json({ success: true, leads: formatted });
      }

      const fallbackLeads = await readSupabaseSettingList('platform_crm_leads');
      return res.json({ success: true, leads: fallbackLeads });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  app.post("/api/crm/leads", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const raw = req.body || {};
      const now = Date.now();
      const leadId = raw.id && /^[0-9a-f-]{36}$/i.test(String(raw.id)) ? String(raw.id) : crypto.randomUUID();
      const cleanLead = {
        id: leadId,
        schoolName: String(raw.schoolName || raw.school_name || 'Prospective School').trim(),
        contactPerson: String(raw.contactPerson || raw.contact_person || 'Administrator').trim(),
        email: String(raw.email || '').trim(),
        phone: String(raw.phone || '').trim(),
        location: String(raw.location || 'Accra, Ghana').trim(),
        estimatedStudents: Number(raw.estimatedStudents ?? raw.estimated_students ?? 250),
        stage: String(raw.stage || 'New'),
        expectedTier: String(raw.expectedTier || raw.expected_tier || 'Standard'),
        dealValue: Number(raw.dealValue ?? raw.deal_value ?? 950),
        notes: String(raw.notes || ''),
        followUpDate: String(raw.followUpDate || raw.follow_up_date || ''),
        createdAt: Number(raw.createdAt || now)
      };

      const adminClient = getSupabaseAdmin();
      const { data, error } = await adminClient
        .from('crm_leads')
        .upsert([{
          id: cleanLead.id,
          school_name: cleanLead.schoolName,
          contact_person: cleanLead.contactPerson,
          email: cleanLead.email || null,
          phone: cleanLead.phone,
          location: cleanLead.location,
          estimated_students: cleanLead.estimatedStudents,
          stage: cleanLead.stage,
          expected_tier: cleanLead.expectedTier,
          deal_value: cleanLead.dealValue,
          notes: cleanLead.notes,
          follow_up_date: cleanLead.followUpDate || null,
          created_at: cleanLead.createdAt,
          updated_at: now
        }], { onConflict: 'id' })
        .select()
        .maybeSingle();

      if (error) {
        const list = await readSupabaseSettingList('platform_crm_leads');
        const filtered = list.filter((item: any) => String(item.id) !== String(cleanLead.id));
        filtered.unshift(cleanLead);
        await writeSupabaseSettingList('platform_crm_leads', filtered);
      }

      return res.status(201).json({ success: true, lead: data ? { ...cleanLead, id: data.id } : cleanLead });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  app.put("/api/crm/leads/:id", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { id } = req.params;
      const raw = req.body || {};
      const now = Date.now();
      const adminClient = getSupabaseAdmin();

      const updateFields: Record<string, any> = { updated_at: now };
      if (raw.schoolName !== undefined) updateFields.school_name = String(raw.schoolName).trim();
      if (raw.contactPerson !== undefined) updateFields.contact_person = String(raw.contactPerson).trim();
      if (raw.email !== undefined) updateFields.email = String(raw.email).trim() || null;
      if (raw.phone !== undefined) updateFields.phone = String(raw.phone).trim();
      if (raw.location !== undefined) updateFields.location = String(raw.location).trim();
      if (raw.estimatedStudents !== undefined) updateFields.estimated_students = Number(raw.estimatedStudents);
      if (raw.stage !== undefined) updateFields.stage = String(raw.stage);
      if (raw.expectedTier !== undefined) updateFields.expected_tier = String(raw.expectedTier);
      if (raw.dealValue !== undefined) updateFields.deal_value = Number(raw.dealValue);
      if (raw.notes !== undefined) updateFields.notes = String(raw.notes);
      if (raw.followUpDate !== undefined) updateFields.follow_up_date = String(raw.followUpDate) || null;

      const { error } = await adminClient.from('crm_leads').update(updateFields).eq('id', id);
      if (error) {
        const list = await readSupabaseSettingList('platform_crm_leads');
        const updatedList = list.map((item: any) =>
          String(item.id) === String(id) ? { ...item, ...raw, id } : item
        );
        await writeSupabaseSettingList('platform_crm_leads', updatedList);
      }

      return res.json({ success: true, id });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  app.delete("/api/crm/leads/:id", authenticateToken, requireRoles("super_admin", "creator"), async (req, res) => {
    try {
      const { id } = req.params;
      const adminClient = getSupabaseAdmin();
      const { error } = await adminClient.from('crm_leads').delete().eq('id', id);
      if (error) {
        const list = await readSupabaseSettingList('platform_crm_leads');
        await writeSupabaseSettingList(
          'platform_crm_leads',
          list.filter((item: any) => String(item.id) !== String(id))
        );
      }
      return res.json({ success: true, id });
    } catch (err: any) {
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

