  app.post("/api/students/bulk-delete", authenticateToken, async (req: any, res) => {
    try {
      invalidateDbCache();
      const scope = resolveTenantAccessScope(req);
      if (scope.unauthorized) {
        return res.status(401).json({ success: false, error: scope.error });
      }
      if (scope.forbidden) {
        return res.status(403).json({ success: false, error: scope.error });
      }
      const adminClient = getSupabaseAdmin();
      const { ids, studentIds } = req.body || {};
      const targetSchoolId = scope.schoolId;
      if (!targetSchoolId && !scope.isSuper) {
        return res.status(403).json({ success: false, error: "Tenant isolation policy violation: valid school_id required." });
      }

      const listIds = Array.isArray(ids) ? ids : [];
      const listStudentIds = Array.isArray(studentIds) ? studentIds : [];

      if (listIds.length === 0 && listStudentIds.length === 0) {
        return res.status(400).json({ success: false, error: "No student IDs provided for deletion" });
      }

      let deletedCount = 0;

      // 1. Delete by Primary Keys in Supabase
      if (listIds.length > 0) {
        try {
          let query = adminClient.from('students').delete().in('id', listIds);
          if (targetSchoolId) {
            query = query.eq("school_id", targetSchoolId);
          }
          const { error, count } = await query;
          if (!error && count) deletedCount += count;
        } catch (e) {
          console.warn("Notice in bulk delete by ID:", e);
        }
      }

      // 2. Delete by studentId identifiers in Supabase
      if (listStudentIds.length > 0) {
        try {
          let q1 = adminClient.from('students').delete().in('studentId', listStudentIds);
          if (targetSchoolId) q1 = q1.eq('school_id', targetSchoolId);
          await q1;
        } catch (e) {}
        try {
          let q2 = adminClient.from('students').delete().in('student_id', listStudentIds);
          if (targetSchoolId) q2 = q2.eq('school_id', targetSchoolId);
          await q2;
        } catch (e) {}
      }

      const idSet = new Set(listIds.map(String));
      const sidSet = new Set(listStudentIds.map(String));
      removeFromFallback('students', (item: any) =>
        idSet.has(String(item.id)) ||
        sidSet.has(String(item.studentId || '')) ||
        sidSet.has(String(item.student_id || ''))
      );

      // 3. Invalidate DB cache
      invalidateDbCache();
      return res.json({
        success: true,
        message: `Successfully deleted selected students from Supabase`,
        count: Math.max(deletedCount, listIds.length, listStudentIds.length)
      });
    } catch (err: any) {
      invalidateDbCache();
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

