  // =========================================================================
  // ATTENDANCE SUPABASE ENDPOINTS (public.attendance + classes & students sync)
  // =========================================================================

  const normalizeAttendanceStatus = (rawStatus: any): 'Present' | 'Absent' | 'Late' | 'Excused' => {
    const s = String(rawStatus || 'Present').trim().toLowerCase();
    if (s === 'absent') return 'Absent';
    if (s === 'late') return 'Late';
    if (s === 'excused') return 'Excused';
    return 'Present';
  };

  const normalizeAttendanceDate = (rawDate: any): string => {
    const str = String(rawDate || '').trim();
    const match = str.match(/^(\d{4}-\d{2}-\d{2})/);
    if (match) return match[1];
    const parsed = new Date(str);
    if (!isNaN(parsed.getTime())) {
      return parsed.toISOString().slice(0, 10);
    }
    return new Date().toISOString().slice(0, 10);
  };

  const normalizeAttendanceRecord = (raw: any, defaultSchoolId?: string | null) => {
    if (!raw || typeof raw !== 'object') return null;
    const studentId = String(raw.student_id ?? raw.studentId ?? '').trim();
    if (!studentId) return null;
    const date = normalizeAttendanceDate(raw.date);
    const status = normalizeAttendanceStatus(raw.status);
    const className = raw.class !== undefined && raw.class !== null && String(raw.class).trim() !== ''
      ? String(raw.class).trim()
      : (raw.className || raw.class_name ? String(raw.className || raw.class_name).trim() : null);
    const reasonRaw = raw.reason !== undefined && raw.reason !== null
      ? String(raw.reason).trim()
      : (raw.note !== undefined && raw.note !== null ? String(raw.note).trim() : '');
    const recordedBy = raw.recorded_by || raw.recordedBy
      ? String(raw.recorded_by || raw.recordedBy).trim()
      : null;
    const schoolId = String(raw.school_id || raw.schoolId || defaultSchoolId || '').trim();
    const createdAt = Number(raw.created_at ?? raw.createdAt ?? Date.now()) || Date.now();

    return {
      id: raw.id !== undefined && raw.id !== null ? raw.id : undefined,
      schoolId,
      school_id: schoolId,
      studentId,
      student_id: studentId,
      class: className,
      date,
      status,
      reason: reasonRaw || null,
      note: reasonRaw || '',
      recordedBy,
      recorded_by: recordedBy,
      createdAt,
      created_at: createdAt
    };
  };

  async function resolveAttendanceSchoolId(req: any): Promise<string> {
    return requireAuthenticatedSchoolScope(req);
  }

  async function ensureAttendanceReferenceRecordsInSupabase(
    schoolId: string,
    classesInput: any[],
    studentsInput: any[]
  ): Promise<void> {
    if (!schoolId) return;
    const adminClient = getSupabaseAdmin();

    // 1. Ensure classes exist in public.classes
    if (Array.isArray(classesInput) && classesInput.length > 0) {
      const classRows = classesInput
        .map((c: any) => {
          const name = String(typeof c === 'string' ? c : (c?.name || c?.class || '')).trim();
          if (!name) return null;
          const level = String(c?.level || (name.toUpperCase().startsWith('JHS') ? 'JHS' : 'Primary')).trim();
          const capacity = Number(c?.capacity) > 0 ? Number(c.capacity) : 50;
          return {
            school_id: schoolId,
            name,
            level,
            capacity,
            created_at: Number(c?.created_at || c?.createdAt || Date.now()) || Date.now()
          };
        })
        .filter(Boolean);

      if (classRows.length > 0) {
        try {
          await adminClient
            .from('classes')
            .upsert(classRows as any[], { onConflict: 'school_id,name' });
        } catch {}
      }
    }

    // 2. Ensure students exist in public.students
    if (Array.isArray(studentsInput) && studentsInput.length > 0) {
      const seenStudentIds = new Set<string>();
      const studentRows: any[] = [];

      for (const s of studentsInput) {
        if (!s || typeof s !== 'object') continue;
        const studentId = String(s.studentId || s.student_id || '').trim();
        if (!studentId || seenStudentIds.has(studentId)) continue;
        seenStudentIds.add(studentId);

        const firstName = String(s.firstName || s.first_name || 'Student').trim() || 'Student';
        const lastName = String(s.lastName || s.last_name || studentId).trim() || studentId;
        const className = String(s.class || s.className || 'P1').trim() || 'P1';
        const rawGender = String(s.gender || 'Male').trim();
        const gender = rawGender === 'Female' || rawGender === 'Other' ? rawGender : 'Male';
        const rawDob = String(s.dateOfBirth || s.date_of_birth || '').trim();
        const dobMatch = rawDob.match(/^(\d{4}-\d{2}-\d{2})/);

        studentRows.push({
          school_id: schoolId,
          student_id: studentId,
          first_name: firstName,
          last_name: lastName,
          class: className,
          date_of_birth: dobMatch ? dobMatch[1] : null,
          gender,
          guardian_name: s.guardianName || s.guardian_name || null,
          guardian_phone: s.guardianPhone || s.guardian_phone || null,
          fees_paid: Math.max(0, Number(s.feesPaid ?? s.fees_paid ?? 0) || 0),
          total_fees: Math.max(0, Number(s.totalFees ?? s.total_fees ?? 0) || 0),
          house: s.house || null,
          department: s.department || null,
          photo: s.photo || null,
          status: 'active',
          created_at: Number(s.createdAt ?? s.created_at ?? Date.now()) || Date.now(),
          updated_at: Date.now()
        });
      }

      if (studentRows.length > 0) {
        try {
          await adminClient
            .from('students')
            .upsert(studentRows, { onConflict: 'school_id,student_id' });
        } catch {}
      }
    }
  }

  async function upsertAttendanceRecordsInSupabase(
    schoolId: string,
    rawRecords: any[],
    defaultRecordedBy?: string | null
  ): Promise<any[]> {
    if (!schoolId || !Array.isArray(rawRecords) || rawRecords.length === 0) return [];
    const adminClient = getSupabaseAdmin();

    // Normalize and deduplicate by (studentId, date)
    const dedupedMap = new Map<string, ReturnType<typeof normalizeAttendanceRecord>>();
    for (const item of rawRecords) {
      const norm = normalizeAttendanceRecord(
        {
          ...item,
          school_id: schoolId,
          recorded_by: item?.recorded_by || item?.recordedBy || defaultRecordedBy || null
        },
        schoolId
      );
      if (norm && norm.studentId && norm.date) {
        dedupedMap.set(`${norm.studentId}|${norm.date}`, norm);
      }
    }

    const normalizedList = Array.from(dedupedMap.values()).filter(Boolean) as NonNullable<ReturnType<typeof normalizeAttendanceRecord>>[];
    if (normalizedList.length === 0) return [];

    // Ensure parent student records exist in public.students to satisfy "attendance_student_fk" and resolve missing class names
    const allStudentIds = Array.from(new Set(normalizedList.map(r => r.studentId)));
    const studentClassMap = new Map<string, string>();
    const existingStudentIdSet = new Set<string>();

    if (allStudentIds.length > 0) {
      try {
        const { data: stuRows } = await adminClient
          .from('students')
          .select('student_id, class')
          .eq('school_id', schoolId)
          .in('student_id', allStudentIds);
        for (const st of (stuRows || [])) {
          if (st.student_id) {
            existingStudentIdSet.add(String(st.student_id));
            if (st.class) {
              studentClassMap.set(String(st.student_id), String(st.class));
            }
          }
        }
      } catch {}

      const missingStudentIds = allStudentIds.filter(sid => !existingStudentIdSet.has(sid));
      if (missingStudentIds.length > 0) {
        const stubStudents = missingStudentIds.map(sid => {
          const matchingAtt = normalizedList.find(r => r.studentId === sid);
          return {
            studentId: sid,
            firstName: 'Student',
            lastName: sid,
            class: matchingAtt?.class || 'P1',
            gender: 'Male'
          };
        });
        await ensureAttendanceReferenceRecordsInSupabase(schoolId, [], stubStudents);
      }
    }

    const dbPayload = normalizedList.map(r => ({
      school_id: schoolId,
      student_id: r.studentId,
      class: r.class || studentClassMap.get(r.studentId) || null,
      date: r.date,
      status: r.status,
      reason: r.reason || null,
      recorded_by: r.recordedBy || defaultRecordedBy || null,
      created_at: r.createdAt || Date.now()
    }));

    // 1. Primary atomic upsert on (school_id, student_id, date)
    const { data: upsertedRows, error: upsertErr } = await adminClient
      .from('attendance')
      .upsert(dbPayload, { onConflict: 'school_id,student_id,date' })
      .select();

    if (!upsertErr && Array.isArray(upsertedRows)) {
      return upsertedRows
        .map(row => normalizeAttendanceRecord(row, schoolId))
        .filter(Boolean);
    }

    // 2. Fallback: individual select + update/insert if onConflict constraint differs
    const savedResults: any[] = [];
    for (const row of dbPayload) {
      try {
        const { data: existing } = await adminClient
          .from('attendance')
          .select('id')
          .eq('school_id', schoolId)
          .eq('student_id', row.student_id)
          .eq('date', row.date)
          .limit(1)
          .maybeSingle();

        if (existing?.id != null) {
          const { data: updated, error: updErr } = await adminClient
            .from('attendance')
            .update({
              status: row.status,
              class: row.class,
              reason: row.reason,
              recorded_by: row.recorded_by
            })
            .eq('id', existing.id)
            .eq('school_id', schoolId)
            .select()
            .maybeSingle();
          if (updErr) throw new Error(updErr.message);
          if (updated) savedResults.push(normalizeAttendanceRecord(updated, schoolId));
        } else {
          const { data: inserted, error: insErr } = await adminClient
            .from('attendance')
            .insert([row])
            .select()
            .maybeSingle();
          if (insErr) throw new Error(insErr.message);
          if (inserted) savedResults.push(normalizeAttendanceRecord(inserted, schoolId));
        }
      } catch (innerErr: any) {
        throw new Error(innerErr?.message || upsertErr?.message || 'Failed to save attendance record to Supabase');
      }
    }

    return savedResults.filter(Boolean);
  }

  async function fetchSchoolAttendanceFromSupabase(
    schoolId: string,
    filters?: { date?: string; className?: string; studentId?: string }
  ): Promise<{
    attendance: any[];
    dateAttendance: any[];
    classes: any[];
    students: any[];
  }> {
    const adminClient = getSupabaseAdmin();
    if (!schoolId) {
      return { attendance: [], dateAttendance: [], classes: [], students: [] };
    }

    const [attRes, clsRes, stuRes] = await Promise.all([
      adminClient
        .from('attendance')
        .select('*')
        .eq('school_id', schoolId)
        .order('date', { ascending: false })
        .order('id', { ascending: true }),
      adminClient
        .from('classes')
        .select('*')
        .eq('school_id', schoolId)
        .order('name', { ascending: true }),
      adminClient
        .from('students')
        .select('*')
        .eq('school_id', schoolId)
        .order('first_name', { ascending: true })
    ]);

    const students = Array.isArray(stuRes.data)
      ? stuRes.data.map((s: any) => normalizeServerStudentRecord(s))
      : [];
    const studentClassLookup = new Map<string, string>();
    students.forEach((s: any) => {
      if (s?.studentId && s?.class) {
        studentClassLookup.set(String(s.studentId), String(s.class));
      }
    });

    const classes = Array.isArray(clsRes.data)
      ? clsRes.data.map((c: any) => normalizeServerClassRecord(c))
      : [];

    const attendance = Array.isArray(attRes.data)
      ? attRes.data
          .map((row: any) => {
            const norm = normalizeAttendanceRecord(row, schoolId);
            if (!norm) return null;
            if (!norm.class && studentClassLookup.has(norm.studentId)) {
              norm.class = studentClassLookup.get(norm.studentId) || null;
            }
            return norm;
          })
          .filter(Boolean)
      : [];

    const targetDate = filters?.date ? normalizeAttendanceDate(filters.date) : '';
    const targetClass = filters?.className && filters.className !== 'All' ? String(filters.className).trim().toLowerCase() : '';
    const targetStudentId = filters?.studentId ? String(filters.studentId).trim() : '';

    const dateAttendance = attendance.filter((a: any) => {
      if (targetDate && a.date !== targetDate) return false;
      if (targetStudentId && a.studentId !== targetStudentId) return false;
      if (targetClass) {
        const recordClass = String(a.class || studentClassLookup.get(a.studentId) || '').trim().toLowerCase();
        if (recordClass && recordClass !== targetClass) return false;
      }
      return true;
    });

    return {
      attendance,
      dateAttendance,
      classes,
      students
    };
  }

  // GET /api/attendance - Fetch attendance records, classes, and students for the active school from Supabase
  app.get("/api/attendance", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      const schoolId = await resolveAttendanceSchoolId(req);
      const date = req.query.date ? String(req.query.date).trim() : undefined;
      const className = req.query.class ? String(req.query.class).trim() : undefined;
      const studentId = (req.query.student_id || req.query.studentId)
        ? String(req.query.student_id || req.query.studentId).trim()
        : undefined;

      const { attendance, dateAttendance, classes, students } = await fetchSchoolAttendanceFromSupabase(schoolId, {
        date,
        className,
        studentId
      });

      return res.json({
        success: true,
        schoolId,
        attendance,
        dateAttendance,
        classes,
        students
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // POST /api/attendance - Save single or bulk attendance entries directly to Supabase (public.attendance)
  app.post("/api/attendance", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      invalidateDbCache();
      const userRole = String(req.user?.role || '').toLowerCase();
      if (userRole === 'parent' || userRole === 'student') {
        return res.status(403).json({
          success: false,
          error: "Parents and students are not permitted to modify attendance records."
        });
      }

      const schoolId = await resolveAttendanceSchoolId(req);
      if (!schoolId) {
        return res.status(400).json({ success: false, error: "Could not resolve active school_id for attendance." });
      }

      const body = req.body || {};
      const recordedBy = String(
        body.recordedBy ||
        body.recorded_by ||
        (req.user as any)?.full_name ||
        req.user?.fullName ||
        req.user?.username ||
        'Staff'
      ).trim();

      // If student/class metadata is included, ensure they exist in Supabase
      const classesToEnsure = Array.isArray(body.classes)
        ? body.classes
        : (body.class ? [{ name: body.class }] : []);
      const studentsToEnsure = Array.isArray(body.students)
        ? body.students
        : (body.student ? [body.student] : []);
      if (classesToEnsure.length > 0 || studentsToEnsure.length > 0) {
        await ensureAttendanceReferenceRecordsInSupabase(schoolId, classesToEnsure, studentsToEnsure);
      }

      const incomingRecords = Array.isArray(body.records)
        ? body.records
        : [body];

      const validRecords = incomingRecords.filter(
        (r: any) => r && (r.studentId || r.student_id)
      );

      if (validRecords.length === 0) {
        return res.status(400).json({
          success: false,
          error: "At least one attendance record with studentId is required."
        });
      }

      const saved = await upsertAttendanceRecordsInSupabase(schoolId, validRecords, recordedBy);
      const filterDate = body.date || validRecords[0]?.date;
      const { attendance, dateAttendance, classes, students } = await fetchSchoolAttendanceFromSupabase(schoolId, {
        date: filterDate
      });

      return res.status(201).json({
        success: true,
        schoolId,
        saved,
        record: saved[0] || null,
        attendance,
        dateAttendance,
        classes,
        students
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // POST /api/attendance/sync - Auto-migrate local attendance, students, and classes to Supabase on load
  app.post("/api/attendance/sync", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      invalidateDbCache();
      const schoolId = await resolveAttendanceSchoolId(req);
      if (!schoolId) {
        return res.status(400).json({ success: false, error: "Could not resolve school_id for attendance sync." });
      }

      const body = req.body || {};
      const incomingClasses = Array.isArray(body.classes) ? body.classes : [];
      const incomingStudents = Array.isArray(body.students) ? body.students : [];
      const incomingAttendance = Array.isArray(body.attendance)
        ? body.attendance
        : (Array.isArray(body.records) ? body.records : []);
      const recordedBy = String(
        body.recordedBy ||
        body.recorded_by ||
        (req.user as any)?.full_name ||
        req.user?.fullName ||
        req.user?.username ||
        'System Sync'
      ).trim();

      if (incomingClasses.length > 0 || incomingStudents.length > 0) {
        await ensureAttendanceReferenceRecordsInSupabase(schoolId, incomingClasses, incomingStudents);
      }

      const userRole = String(req.user?.role || '').toLowerCase();
      let saved: any[] = [];
      if (incomingAttendance.length > 0 && userRole !== 'parent' && userRole !== 'student') {
        saved = await upsertAttendanceRecordsInSupabase(schoolId, incomingAttendance, recordedBy);
      }

      const filterDate = body.date ? String(body.date).trim() : undefined;
      const { attendance, dateAttendance, classes, students } = await fetchSchoolAttendanceFromSupabase(schoolId, {
        date: filterDate
      });

      return res.json({
        success: true,
        schoolId,
        migratedCount: saved.length,
        attendance,
        dateAttendance,
        classes,
        students
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // =========================================================================
  // ACADEMIC RESULTS & CONTINUOUS ASSESSMENT (EXERCISES, HOMEWORK, TESTS) SUPABASE ENDPOINTS
  // =========================================================================

  const DEFAULT_SERVER_CA_COLUMNS = [
    { id: 'ex1', title: 'Ex 1', category: 'Exercise', maxScore: 10 },
    { id: 'ex2', title: 'Ex 2', category: 'Exercise', maxScore: 10 },
    { id: 'hw1', title: 'HW 1', category: 'Homework', maxScore: 10 },
    { id: 'test1', title: 'Test 1', category: 'Test', maxScore: 20 }
  ];

  const makeCaSubjectKey = (classNameRaw: any, subjectRaw: any, termRaw: any): string => {
    const cls = String(classNameRaw || 'P1').trim();
    const subj = String(subjectRaw || 'Mathematics').trim();
    const trm = String(termRaw || 'Term 1').trim();
    return `${cls}::${subj}::${trm}`;
  };

  const calculateServerGrade = (total: number): { grade: string; remarks: string } => {
    if (total >= 80) return { grade: 'A1', remarks: 'Excellent' };
    if (total >= 70) return { grade: 'B2', remarks: 'Very Good' };
    if (total >= 65) return { grade: 'B3', remarks: 'Good' };
    if (total >= 60) return { grade: 'C4', remarks: 'Credit' };
    if (total >= 55) return { grade: 'C5', remarks: 'Credit' };
    if (total >= 50) return { grade: 'C6', remarks: 'Credit' };
    if (total >= 45) return { grade: 'D7', remarks: 'Pass' };
    if (total >= 40) return { grade: 'E8', remarks: 'Weak Pass' };
    return { grade: 'F9', remarks: 'Fail' };
  };

  async function resolveResultsSchoolId(req: any): Promise<string> {
    return requireAuthenticatedSchoolScope(req);
  }

  async function readContinuousAssessmentFromSchoolSettings(schoolId: string): Promise<Record<string, {
    className: string;
    subject: string;
    term: string;
    columns: any[];
    studentScores: Record<string, {
      scores: Record<string, number>;
      rawCaScore: number;
      rawCaMax: number;
      scaledClassScore: number;
    }>;
    updatedAt: number;
  }>> {
    if (!schoolId) return {};
    const adminClient = getSupabaseAdmin();
    try {
      const { data, error } = await adminClient
        .from('school_settings')
        .select('*')
        .eq('school_id', schoolId)
        .limit(1)
        .maybeSingle();

      if (!error && data && data.streams && typeof data.streams === 'object' && !Array.isArray(data.streams)) {
        const ca = (data.streams as any).continuous_assessment;
        if (ca && typeof ca === 'object') {
          return ca;
        }
      }
    } catch {}
    return {};
  }

  async function writeContinuousAssessmentToSchoolSettings(
    schoolId: string,
    entriesToMerge: Record<string, {
      className: string;
      subject: string;
      term: string;
      columns: any[];
      studentScores: Record<string, {
        scores: Record<string, number>;
        rawCaScore: number;
        rawCaMax: number;
        scaledClassScore: number;
      }>;
      updatedAt: number;
    }>
  ): Promise<void> {
    if (!schoolId || !entriesToMerge || Object.keys(entriesToMerge).length === 0) return;
    const adminClient = getSupabaseAdmin();

    try {
      const { data: existing } = await adminClient
        .from('school_settings')
        .select('*')
        .eq('school_id', schoolId)
        .limit(1)
        .maybeSingle();

      const existingStreams = existing?.streams;
      let streamItems: any[] = [];
      let prevNotes: Record<string, string> = {};
      let prevSuggestions: any[] = [];
      let prevCa: Record<string, any> = {};

      if (Array.isArray(existingStreams)) {
        streamItems = existingStreams;
      } else if (existingStreams && typeof existingStreams === 'object') {
        streamItems = Array.isArray((existingStreams as any).items) ? (existingStreams as any).items : [];
        prevNotes = (existingStreams as any).timetable_notes || {};
        prevSuggestions = Array.isArray((existingStreams as any).timetable_suggestions) ? (existingStreams as any).timetable_suggestions : [];
        prevCa = (existingStreams as any).continuous_assessment && typeof (existingStreams as any).continuous_assessment === 'object'
          ? (existingStreams as any).continuous_assessment
          : {};
      }

      const mergedCa: Record<string, any> = { ...prevCa };
      for (const [key, incoming] of Object.entries(entriesToMerge)) {
        const prevEntry = mergedCa[key] || {};
        const prevStudentScores = prevEntry.studentScores && typeof prevEntry.studentScores === 'object'
          ? prevEntry.studentScores
          : {};
        mergedCa[key] = {
          className: incoming.className || prevEntry.className || 'P1',
          subject: incoming.subject || prevEntry.subject || 'Mathematics',
          term: incoming.term || prevEntry.term || 'Term 1',
          columns: Array.isArray(incoming.columns) && incoming.columns.length > 0
            ? incoming.columns
            : (Array.isArray(prevEntry.columns) && prevEntry.columns.length > 0 ? prevEntry.columns : DEFAULT_SERVER_CA_COLUMNS),
          studentScores: {
            ...prevStudentScores,
            ...(incoming.studentScores || {})
          },
          updatedAt: incoming.updatedAt || Date.now()
        };
      }

      const nextStreamsObj = {
        ...(existingStreams && typeof existingStreams === 'object' && !Array.isArray(existingStreams) ? existingStreams : {}),
        items: streamItems,
        timetable_notes: prevNotes,
        timetable_suggestions: prevSuggestions,
        continuous_assessment: mergedCa
      };

      const payload = {
        school_id: schoolId,
        grade_boundaries: existing?.grade_boundaries || [],
        terms: existing?.terms || [],
        streams: nextStreamsObj,
        updated_at: Date.now()
      };

      await adminClient
        .from('school_settings')
        .upsert([payload], { onConflict: 'school_id' });
    } catch (err) {
      console.warn('Notice saving continuous assessment to school_settings in Supabase:', err);
    }
  }

  const normalizeResultRecord = (
    raw: any,
    defaultSchoolId?: string | null,
    caLedger?: Record<string, any>
  ) => {
    if (!raw || typeof raw !== 'object') return null;
    const studentId = String(raw.student_id || raw.studentId || '').trim();
    const subject = String(raw.subject || '').trim();
    if (!studentId || !subject) return null;

    const term = String(raw.term || 'Term 1').trim();
    const academicYear = String(raw.academic_year || raw.academicYear || '2026/2027').trim();
    const className = String(raw.class || raw.className || 'P1').trim();
    const schoolId = String(raw.school_id || raw.schoolId || defaultSchoolId || '').trim();

    const caKey = makeCaSubjectKey(className, subject, term);
    const caEntry = caLedger?.[caKey];
    const caStu = caEntry?.studentScores?.[studentId];

    let exerciseColumns = raw.exercise_columns ?? raw.exerciseColumns;
    if (typeof exerciseColumns === 'string') {
      try { exerciseColumns = JSON.parse(exerciseColumns); } catch { exerciseColumns = undefined; }
    }
    if (!Array.isArray(exerciseColumns) || exerciseColumns.length === 0) {
      if (Array.isArray(caEntry?.columns) && caEntry.columns.length > 0) {
        exerciseColumns = caEntry.columns;
      } else {
        exerciseColumns = undefined;
      }
    }

    let exerciseScores = raw.exercise_scores ?? raw.exerciseScores;
    if (typeof exerciseScores === 'string') {
      try { exerciseScores = JSON.parse(exerciseScores); } catch { exerciseScores = undefined; }
    }
    if (!exerciseScores || typeof exerciseScores !== 'object' || Object.keys(exerciseScores).length === 0) {
      if (caStu?.scores && typeof caStu.scores === 'object' && Object.keys(caStu.scores).length > 0) {
        exerciseScores = caStu.scores;
      } else {
        exerciseScores = undefined;
      }
    }

    const activeCols = Array.isArray(exerciseColumns) && exerciseColumns.length > 0
      ? exerciseColumns
      : DEFAULT_SERVER_CA_COLUMNS;

    let computedRawObtained = 0;
    let computedRawMax = activeCols.reduce((acc: number, c: any) => acc + (Number(c?.maxScore) || 0), 0);
    let hasExerciseEntry = false;

    if (exerciseScores && typeof exerciseScores === 'object') {
      for (const col of activeCols) {
        const val = (exerciseScores as any)[col.id];
        if (val !== undefined && val !== null && !isNaN(Number(val))) {
          hasExerciseEntry = true;
          const clamped = Math.min(Number(col.maxScore) || 100, Math.max(0, Number(val)));
          computedRawObtained += clamped;
        }
      }
    }

    const rawCaScore = raw.raw_ca_score !== undefined || raw.rawCaScore !== undefined
      ? Number(raw.raw_ca_score ?? raw.rawCaScore)
      : (caStu?.rawCaScore !== undefined ? Number(caStu.rawCaScore) : (hasExerciseEntry ? computedRawObtained : undefined));

    const rawCaMax = raw.raw_ca_max !== undefined || raw.rawCaMax !== undefined
      ? Number(raw.raw_ca_max ?? raw.rawCaMax)
      : (caStu?.rawCaMax !== undefined ? Number(caStu.rawCaMax) : (hasExerciseEntry ? computedRawMax : undefined));

    const autoScaledClassScore = (hasExerciseEntry && computedRawMax > 0)
      ? Math.min(30, Math.max(0, Math.round((computedRawObtained / computedRawMax) * 30)))
      : undefined;

    const classScore = Math.min(
      100,
      Math.max(
        0,
        Number(raw.class_score ?? raw.classScore ?? autoScaledClassScore ?? caStu?.scaledClassScore ?? 0) || 0
      )
    );
    const examScore = Math.min(
      100,
      Math.max(0, Number(raw.exam_score ?? raw.examScore ?? 0) || 0)
    );
    const totalScore = Math.min(
      100,
      Math.max(0, Number(raw.total_score ?? raw.totalScore ?? (classScore + examScore)) || 0)
    );
    const fallbackGrade = calculateServerGrade(totalScore);
    const grade = String(raw.grade || fallbackGrade.grade).trim();
    const remarks = String(raw.remarks || fallbackGrade.remarks).trim();
    const createdAt = Number(raw.created_at ?? raw.createdAt ?? Date.now()) || Date.now();

    return {
      id: typeof raw.id === 'number' ? raw.id : undefined,
      schoolId,
      school_id: schoolId,
      studentId,
      student_id: studentId,
      subject,
      term,
      academicYear,
      academic_year: academicYear,
      class: className,
      classScore,
      class_score: classScore,
      examScore,
      exam_score: examScore,
      totalScore,
      total_score: totalScore,
      grade,
      remarks,
      exerciseScores,
      exercise_scores: exerciseScores,
      exerciseColumns,
      exercise_columns: exerciseColumns,
      rawCaScore,
      raw_ca_score: rawCaScore,
      rawCaMax,
      raw_ca_max: rawCaMax,
      createdAt,
      created_at: createdAt
    };
  };

  async function upsertResultsAndCaInSupabase(
    schoolId: string,
    rawRecords: any[],
    explicitCaMeta?: {
      className?: string;
      subject?: string;
      term?: string;
      columns?: any[];
      exerciseScores?: Record<string, Record<string, number>>;
    }
  ): Promise<any[]> {
    if (!schoolId) return [];
    const adminClient = getSupabaseAdmin();

    // 1. Build CA ledger updates per (className, subject, term)
    const caUpdates: Record<string, {
      className: string;
      subject: string;
      term: string;
      columns: any[];
      studentScores: Record<string, {
        scores: Record<string, number>;
        rawCaScore: number;
        rawCaMax: number;
        scaledClassScore: number;
      }>;
      updatedAt: number;
    }> = {};

    const ensureCaBucket = (cls: string, subj: string, trm: string, cols?: any[]) => {
      const key = makeCaSubjectKey(cls, subj, trm);
      if (!caUpdates[key]) {
        caUpdates[key] = {
          className: cls,
          subject: subj,
          term: trm,
          columns: Array.isArray(cols) && cols.length > 0 ? cols : DEFAULT_SERVER_CA_COLUMNS,
          studentScores: {},
          updatedAt: Date.now()
        };
      } else if (Array.isArray(cols) && cols.length > 0) {
        caUpdates[key].columns = cols;
      }
      return caUpdates[key];
    };

    if (explicitCaMeta?.className && explicitCaMeta?.subject && explicitCaMeta?.term) {
      const bucket = ensureCaBucket(
        explicitCaMeta.className,
        explicitCaMeta.subject,
        explicitCaMeta.term,
        explicitCaMeta.columns
      );
      const rawMax = bucket.columns.reduce((acc: number, c: any) => acc + (Number(c?.maxScore) || 0), 0);
      if (explicitCaMeta.exerciseScores && typeof explicitCaMeta.exerciseScores === 'object') {
        for (const [stuId, scoreMap] of Object.entries(explicitCaMeta.exerciseScores)) {
          if (!stuId || !scoreMap || typeof scoreMap !== 'object') continue;
          const cleanScores: Record<string, number> = {};
          let rawObtained = 0;
          let hasAny = false;
          for (const col of bucket.columns) {
            const v = (scoreMap as any)[col.id];
            if (v !== undefined && v !== null && !isNaN(Number(v))) {
              const clamped = Math.min(Number(col.maxScore) || 100, Math.max(0, Number(v)));
              cleanScores[col.id] = clamped;
              rawObtained += clamped;
              hasAny = true;
            }
          }
          const scaledClassScore = (hasAny && rawMax > 0)
            ? Math.min(30, Math.max(0, Math.round((rawObtained / rawMax) * 30)))
            : 0;
          bucket.studentScores[stuId] = {
            scores: cleanScores,
            rawCaScore: rawObtained,
            rawCaMax: rawMax,
            scaledClassScore
          };
        }
      }
    }

    // 2. Normalize and deduplicate incoming result records
    const dedupedMap = new Map<string, NonNullable<ReturnType<typeof normalizeResultRecord>>>();
    for (const item of (Array.isArray(rawRecords) ? rawRecords : [])) {
      const norm = normalizeResultRecord({ ...item, school_id: schoolId }, schoolId);
      if (!norm) continue;
      const dedupeKey = `${norm.studentId}|${norm.subject.toLowerCase()}|${norm.term.toLowerCase()}|${norm.academicYear}`;
      dedupedMap.set(dedupeKey, norm);

      if (norm.exerciseColumns || norm.exerciseScores) {
        const bucket = ensureCaBucket(norm.class, norm.subject, norm.term, norm.exerciseColumns);
        const rawMax = bucket.columns.reduce((acc: number, c: any) => acc + (Number(c?.maxScore) || 0), 0);
        if (norm.exerciseScores && typeof norm.exerciseScores === 'object') {
          const cleanScores: Record<string, number> = {};
          let rawObtained = 0;
          for (const [k, v] of Object.entries(norm.exerciseScores)) {
            if (v !== undefined && v !== null && !isNaN(Number(v))) {
              cleanScores[k] = Number(v);
              rawObtained += Number(v);
            }
          }
          bucket.studentScores[norm.studentId] = {
            scores: cleanScores,
            rawCaScore: norm.rawCaScore ?? rawObtained,
            rawCaMax: norm.rawCaMax ?? rawMax,
            scaledClassScore: norm.classScore
          };
        }
      }
    }

    // Persist CA breakdown to public.school_settings in Supabase
    if (Object.keys(caUpdates).length > 0) {
      await writeContinuousAssessmentToSchoolSettings(schoolId, caUpdates);
    }

    const normalizedList = Array.from(dedupedMap.values());
    if (normalizedList.length === 0) return [];

    // Prepare extended payload (with exercise_scores & exercise_columns) and core payload (standard schema_master columns)
    const extendedDbPayload = normalizedList.map(r => ({
      school_id: schoolId,
      student_id: r.studentId,
      subject: r.subject,
      term: r.term,
      academic_year: r.academicYear,
      class: r.class,
      class_score: r.classScore,
      exam_score: r.examScore,
      total_score: r.totalScore,
      grade: r.grade,
      remarks: r.remarks,
      exercise_scores: r.exerciseScores || {},
      exercise_columns: r.exerciseColumns || [],
      raw_ca_score: r.rawCaScore ?? null,
      raw_ca_max: r.rawCaMax ?? null,
      created_at: r.createdAt || Date.now()
    }));

    const coreDbPayload = normalizedList.map(r => ({
      school_id: schoolId,
      student_id: r.studentId,
      subject: r.subject,
      term: r.term,
      academic_year: r.academicYear,
      class: r.class,
      class_score: r.classScore,
      exam_score: r.examScore,
      total_score: r.totalScore,
      grade: r.grade,
      remarks: r.remarks,
      created_at: r.createdAt || Date.now()
    }));

    // Try extended upsert first (if exercise_scores column exists on public.results)
    try {
      const { data: extRows, error: extErr } = await adminClient
        .from('results')
        .upsert(extendedDbPayload, { onConflict: 'school_id,student_id,subject,term,academic_year' })
        .select();

      if (!extErr && Array.isArray(extRows)) {
        const caLedger = await readContinuousAssessmentFromSchoolSettings(schoolId);
        return extRows.map(row => normalizeResultRecord(row, schoolId, caLedger)).filter(Boolean);
      }
    } catch {}

    // Fallback to core columns upsert on (school_id,student_id,subject,term,academic_year)
    const { data: coreRows, error: coreErr } = await adminClient
      .from('results')
      .upsert(coreDbPayload, { onConflict: 'school_id,student_id,subject,term,academic_year' })
      .select();

    if (!coreErr && Array.isArray(coreRows)) {
      const caLedger = await readContinuousAssessmentFromSchoolSettings(schoolId);
      return coreRows.map(row => normalizeResultRecord(row, schoolId, caLedger)).filter(Boolean);
    }

    // Individual row select + update/insert fallback if composite constraint differs
    const savedRows: any[] = [];
    for (const row of coreDbPayload) {
      try {
        const { data: existing } = await adminClient
          .from('results')
          .select('id')
          .eq('school_id', schoolId)
          .eq('student_id', row.student_id)
          .eq('subject', row.subject)
          .eq('term', row.term)
          .limit(1)
          .maybeSingle();

        if (existing?.id != null) {
          const { data: updated, error: updErr } = await adminClient
            .from('results')
            .update({
              class: row.class,
              academic_year: row.academic_year,
              class_score: row.class_score,
              exam_score: row.exam_score,
              total_score: row.total_score,
              grade: row.grade,
              remarks: row.remarks
            })
            .eq('id', existing.id)
            .eq('school_id', schoolId)
            .select()
            .maybeSingle();
          if (!updErr && updated) savedRows.push(updated);
        } else {
          const { data: inserted, error: insErr } = await adminClient
            .from('results')
            .insert([row])
            .select()
            .maybeSingle();
          if (!insErr && inserted) savedRows.push(inserted);
        }
      } catch {}
    }

    const caLedger = await readContinuousAssessmentFromSchoolSettings(schoolId);
    return savedRows.map(row => normalizeResultRecord(row, schoolId, caLedger)).filter(Boolean);
  }

  async function fetchSchoolResultsFromSupabase(
    schoolId: string,
    filters?: { className?: string; term?: string; subject?: string; studentId?: string }
  ): Promise<{
    results: any[];
    caColumns: any[];
    caScores: Record<string, Record<string, number>>;
    allCaMap: Record<string, any>;
  }> {
    const adminClient = getSupabaseAdmin();
    if (!schoolId) {
      return { results: [], caColumns: DEFAULT_SERVER_CA_COLUMNS, caScores: {}, allCaMap: {} };
    }

    const [resQuery, caLedger] = await Promise.all([
      adminClient
        .from('results')
        .select('*')
        .eq('school_id', schoolId)
        .order('id', { ascending: true }),
      readContinuousAssessmentFromSchoolSettings(schoolId)
    ]);

    const allResults = Array.isArray(resQuery.data)
      ? resQuery.data.map(r => normalizeResultRecord(r, schoolId, caLedger)).filter(Boolean)
      : [];

    const targetClass = filters?.className && filters.className !== 'All'
      ? String(filters.className).trim().toLowerCase()
      : '';
    const targetTerm = filters?.term
      ? String(filters.term).trim().toLowerCase()
      : '';
    const targetSubject = filters?.subject
      ? String(filters.subject).trim().toLowerCase()
      : '';
    const targetStudentId = filters?.studentId
      ? String(filters.studentId).trim().toLowerCase()
      : '';

    const filteredResults = allResults.filter((r: any) => {
      if (targetClass && String(r.class || '').trim().toLowerCase() !== targetClass) return false;
      if (targetTerm && String(r.term || '').trim().toLowerCase() !== targetTerm) return false;
      if (targetSubject && String(r.subject || '').trim().toLowerCase() !== targetSubject) return false;
      if (targetStudentId && String(r.studentId || '').trim().toLowerCase() !== targetStudentId) return false;
      return true;
    });

    let caColumns = DEFAULT_SERVER_CA_COLUMNS;
    const caScores: Record<string, Record<string, number>> = {};

    if (filters?.className && filters?.subject && filters?.term) {
      const exactKey = makeCaSubjectKey(filters.className, filters.subject, filters.term);
      const matchedKey = Object.keys(caLedger).find(k => k.toLowerCase() === exactKey.toLowerCase());
      const entry = matchedKey ? caLedger[matchedKey] : null;

      if (entry) {
        if (Array.isArray(entry.columns) && entry.columns.length > 0) {
          caColumns = entry.columns;
        }
        if (entry.studentScores && typeof entry.studentScores === 'object') {
          for (const [stuId, stuBreak] of Object.entries(entry.studentScores)) {
            if (stuBreak?.scores && typeof stuBreak.scores === 'object') {
              caScores[stuId] = stuBreak.scores;
            }
          }
        }
      } else {
        const resultWithCols = filteredResults.find((r: any) => Array.isArray(r.exerciseColumns) && r.exerciseColumns.length > 0);
        if (resultWithCols?.exerciseColumns) {
          caColumns = resultWithCols.exerciseColumns;
        }
      }

      for (const r of filteredResults) {
        if (r.exerciseScores && typeof r.exerciseScores === 'object' && Object.keys(r.exerciseScores).length > 0) {
          caScores[r.studentId] = {
            ...(caScores[r.studentId] || {}),
            ...r.exerciseScores
          };
        }
      }
    }

    return {
      results: filteredResults,
      caColumns,
      caScores,
      allCaMap: caLedger
    };
  }

  // GET /api/results - Fetch academic results and Continuous Assessment (Exercises, Homework, Tests) from Supabase
  app.get("/api/results", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      const schoolId = await resolveResultsSchoolId(req);
      const className = req.query.class ? String(req.query.class).trim() : undefined;
      const term = req.query.term ? String(req.query.term).trim() : undefined;
      const subject = req.query.subject ? String(req.query.subject).trim() : undefined;
      const studentId = (req.query.student_id || req.query.studentId)
        ? String(req.query.student_id || req.query.studentId).trim()
        : undefined;

      const { results, caColumns, caScores, allCaMap } = await fetchSchoolResultsFromSupabase(schoolId, {
        className,
        term,
        subject,
        studentId
      });

      return res.json({
        success: true,
        schoolId,
        results,
        caColumns,
        caScores,
        allCaMap
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // POST /api/results/ca - Real-time auto-save of Class Exercises, Homework, and Class Test columns & marks to Supabase
  app.post("/api/results/ca", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      invalidateDbCache();
      const userRole = String(req.user?.role || '').toLowerCase();
      if (userRole === 'parent' || userRole === 'student') {
        return res.status(403).json({
          success: false,
          error: "Parents and students are not permitted to modify continuous assessment marks."
        });
      }

      const schoolId = await resolveResultsSchoolId(req);
      if (!schoolId) {
        return res.status(400).json({ success: false, error: "Could not resolve active school_id for continuous assessment." });
      }

      const body = req.body || {};
      const className = String(body.class || body.className || 'P1').trim();
      const subject = String(body.subject || 'Mathematics').trim();
      const term = String(body.term || 'Term 1').trim();
      const academicYear = String(body.academicYear || body.academic_year || '2026/2027').trim();
      const columns = Array.isArray(body.columns) && body.columns.length > 0
        ? body.columns
        : DEFAULT_SERVER_CA_COLUMNS;
      const exerciseScores: Record<string, Record<string, number>> =
        body.exerciseScores && typeof body.exerciseScores === 'object' ? body.exerciseScores : {};
      const scoresMap: Record<string, { class: number; exam: number }> =
        body.scores && typeof body.scores === 'object' ? body.scores : {};

      // Also build result rows for any students with exercise scores or terminal scores so public.results stays in sync
      const rawMax = columns.reduce((acc: number, c: any) => acc + (Number(c?.maxScore) || 0), 0);
      const studentIds = Array.from(new Set([...Object.keys(exerciseScores), ...Object.keys(scoresMap)])).filter(Boolean);
      const recordsToUpsert: any[] = [];

      for (const stuId of studentIds) {
        const stuEx = exerciseScores[stuId] || {};
        let rawObtained = 0;
        let hasAnyEx = false;
        const cleanStuEx: Record<string, number> = {};
        for (const col of columns) {
          const v = stuEx[col.id];
          if (v !== undefined && v !== null && !isNaN(Number(v))) {
            const clamped = Math.min(Number(col.maxScore) || 100, Math.max(0, Number(v)));
            cleanStuEx[col.id] = clamped;
            rawObtained += clamped;
            hasAnyEx = true;
          }
        }
        const scaledClassScore = (hasAnyEx && rawMax > 0)
          ? Math.min(30, Math.max(0, Math.round((rawObtained / rawMax) * 30)))
          : 0;
        const directScore = scoresMap[stuId] || { class: 0, exam: 0 };
        const classScore = hasAnyEx ? scaledClassScore : (Number(directScore.class) || 0);
        const examScore = Number(directScore.exam) || 0;
        const totalScore = classScore + examScore;
        const { grade, remarks } = calculateServerGrade(totalScore);

        if (hasAnyEx || classScore > 0 || examScore > 0) {
          recordsToUpsert.push({
            school_id: schoolId,
            student_id: stuId,
            subject,
            term,
            academic_year: academicYear,
            class: className,
            class_score: classScore,
            exam_score: examScore,
            total_score: totalScore,
            grade,
            remarks,
            exercise_scores: cleanStuEx,
            exercise_columns: columns,
            raw_ca_score: hasAnyEx ? rawObtained : undefined,
            raw_ca_max: hasAnyEx ? rawMax : undefined
          });
        }
      }

      const saved = await upsertResultsAndCaInSupabase(schoolId, recordsToUpsert, {
        className,
        subject,
        term,
        columns,
        exerciseScores
      });

      return res.json({
        success: true,
        schoolId,
        className,
        subject,
        term,
        columns,
        savedCount: saved.length,
        results: saved,
        syncedAt: Date.now()
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // POST /api/results - Authoritative bulk save of Class Exercises, 30% Class Scores, 70% Exam Scores, and Report Card totals to Supabase
  app.post("/api/results", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      invalidateDbCache();
      const userRole = String(req.user?.role || '').toLowerCase();
      if (userRole === 'parent' || userRole === 'student') {
        return res.status(403).json({
          success: false,
          error: "Parents and students are not permitted to modify academic results."
        });
      }

      const schoolId = await resolveResultsSchoolId(req);
      if (!schoolId) {
        return res.status(400).json({ success: false, error: "Could not resolve active school_id for results." });
      }

      const body = req.body || {};
      const incomingRecords = Array.isArray(body.results)
        ? body.results
        : (Array.isArray(body.records) ? body.records : (Array.isArray(body) ? body : [body]));

      const validRecords = incomingRecords.filter(
        (r: any) => r && (r.studentId || r.student_id) && r.subject
      );

      const caMeta = body.caMeta && typeof body.caMeta === 'object' ? body.caMeta : undefined;
      const saved = await upsertResultsAndCaInSupabase(schoolId, validRecords, caMeta);

      const sample = validRecords[0] || {};
      const { results, caColumns, caScores } = await fetchSchoolResultsFromSupabase(schoolId, {
        className: body.class || sample.class,
        term: body.term || sample.term,
        subject: body.subject || sample.subject
      });

      return res.status(201).json({
        success: true,
        schoolId,
        savedCount: saved.length,
        saved,
        results,
        caColumns,
        caScores,
        syncedAt: Date.now()
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // POST /api/results/sync - Auto-migrate local results & CA breakdowns to Supabase on load
  app.post("/api/results/sync", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      invalidateDbCache();
      const schoolId = await resolveResultsSchoolId(req);
      if (!schoolId) {
        return res.status(400).json({ success: false, error: "Could not resolve school_id for results sync." });
      }

      const body = req.body || {};
      const incomingResults = Array.isArray(body.results)
        ? body.results
        : (Array.isArray(body.records) ? body.records : []);
      const userRole = String(req.user?.role || '').toLowerCase();

      let saved: any[] = [];
      if (incomingResults.length > 0 && userRole !== 'parent' && userRole !== 'student') {
        saved = await upsertResultsAndCaInSupabase(schoolId, incomingResults, body.caMeta);
      }

      const { results, caColumns, caScores, allCaMap } = await fetchSchoolResultsFromSupabase(schoolId, {
        className: body.class ? String(body.class).trim() : undefined,
        term: body.term ? String(body.term).trim() : undefined,
        subject: body.subject ? String(body.subject).trim() : undefined
      });

      return res.json({
        success: true,
        schoolId,
        migratedCount: saved.length,
        results,
        caColumns,
        caScores,
        allCaMap,
        syncedAt: Date.now()
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // ============================================================================
  // TEACHER LESSON NOTES & HOD / HEADMASTER REVIEW PORTAL (SUPABASE + STORAGE)
  // ============================================================================
  const LESSON_NOTES_STORAGE_BUCKET = 'lesson-notes';

  const LESSON_NOTES_DDL_SQL = `-- ==============================================================================
-- SCHOOLSPHERE: public.lesson_notes Table & Supabase Storage Bucket Setup
-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.lesson_notes (
  id BIGSERIAL PRIMARY KEY,
  school_id UUID NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
  note_id VARCHAR(100) NOT NULL,
  teacher_id VARCHAR(100) NULL,
  teacher_name VARCHAR(255) NOT NULL,
  term VARCHAR(50) NOT NULL DEFAULT 'Term 1',
  academic_year VARCHAR(50) NOT NULL DEFAULT '2026/2027',
  week_number INT NOT NULL DEFAULT 1 CHECK (week_number >= 1 AND week_number <= 20),
  class VARCHAR(100) NOT NULL,
  subject VARCHAR(255) NOT NULL,
  lesson_date VARCHAR(50) NULL,
  duration VARCHAR(50) NOT NULL DEFAULT '60 mins',
  class_size INT NULL,
  strand TEXT NOT NULL,
  sub_strand TEXT NULL,
  content_standard TEXT NULL,
  objectives TEXT NULL,
  tlms TEXT NULL,
  core_competencies TEXT NULL,
  starter_activity TEXT NULL,
  main_activity TEXT NULL,
  plenary_activity TEXT NULL,
  evaluation TEXT NULL,
  teacher_remarks TEXT NULL,
  pdf_file_name VARCHAR(255) NULL,
  pdf_file_size BIGINT NULL,
  pdf_file_url TEXT NULL,
  pdf_storage_path TEXT NULL,
  pdf_data TEXT NULL,
  pdf_uploaded_at BIGINT NULL,
  status VARCHAR(50) NOT NULL DEFAULT 'Draft'
    CHECK (status IN ('Draft', 'Pending Review', 'Approved', 'Needs Revision', 'Rejected')),
  submitted_at BIGINT NULL,
  reviewed_by VARCHAR(255) NULL,
  reviewer_role VARCHAR(100) NULL,
  reviewer_feedback TEXT NULL,
  reviewed_at BIGINT NULL,
  created_at BIGINT NOT NULL DEFAULT (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT,
  updated_at BIGINT NOT NULL DEFAULT (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT,
  CONSTRAINT uq_school_lesson_note UNIQUE (school_id, note_id)
);

ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_file_url TEXT NULL;
ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_storage_path TEXT NULL;
ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_file_name VARCHAR(255) NULL;
ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_file_size BIGINT NULL;
ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_data TEXT NULL;
ALTER TABLE public.lesson_notes ADD COLUMN IF NOT EXISTS pdf_uploaded_at BIGINT NULL;

CREATE INDEX IF NOT EXISTS idx_lesson_notes_school_lookup
  ON public.lesson_notes (school_id, term, week_number, class, subject);
CREATE INDEX IF NOT EXISTS idx_lesson_notes_status
  ON public.lesson_notes (school_id, status);
CREATE INDEX IF NOT EXISTS idx_lesson_notes_teacher
  ON public.lesson_notes (school_id, teacher_name);

ALTER TABLE public.lesson_notes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Tenant isolation for lesson_notes" ON public.lesson_notes;
CREATE POLICY "Tenant isolation for lesson_notes" ON public.lesson_notes
  FOR ALL USING (school_id = public.get_auth_school_id() OR public.is_super_admin())
  WITH CHECK (school_id = public.get_auth_school_id() OR public.is_super_admin());

DROP TRIGGER IF EXISTS trg_lesson_notes_updated_at ON public.lesson_notes;
CREATE TRIGGER trg_lesson_notes_updated_at
  BEFORE UPDATE ON public.lesson_notes
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('lesson-notes', 'lesson-notes', true, 15728640, ARRAY['application/pdf'])
ON CONFLICT (id) DO UPDATE SET
  public = true,
  file_size_limit = 15728640,
  allowed_mime_types = ARRAY['application/pdf'];

NOTIFY pgrst, 'reload schema';`;

  let storageBucketVerified = false;
  async function ensureLessonNotesStorageBucket(): Promise<{ ready: boolean; bucketName: string; error?: string }> {
    const adminClient = getSupabaseAdmin();
    if (storageBucketVerified) {
      return { ready: true, bucketName: LESSON_NOTES_STORAGE_BUCKET };
    }
    try {
      const { data: buckets, error: listErr } = await adminClient.storage.listBuckets();
      if (!listErr && Array.isArray(buckets)) {
        const exists = buckets.some((b: any) => b.name === LESSON_NOTES_STORAGE_BUCKET || b.id === LESSON_NOTES_STORAGE_BUCKET);
        if (exists) {
          storageBucketVerified = true;
          return { ready: true, bucketName: LESSON_NOTES_STORAGE_BUCKET };
        }
      }
      const { error: createErr } = await adminClient.storage.createBucket(LESSON_NOTES_STORAGE_BUCKET, {
        public: true,
        fileSizeLimit: 15 * 1024 * 1024,
        allowedMimeTypes: ['application/pdf']
      });
      if (!createErr || String(createErr.message || '').toLowerCase().includes('already exists')) {
        storageBucketVerified = true;
        return { ready: true, bucketName: LESSON_NOTES_STORAGE_BUCKET };
      }
      return { ready: false, bucketName: LESSON_NOTES_STORAGE_BUCKET, error: createErr.message };
    } catch (err: any) {
      return { ready: false, bucketName: LESSON_NOTES_STORAGE_BUCKET, error: err?.message || 'Storage check failed' };
    }
  }

  async function uploadLessonNotePdfToStorage(params: {
    schoolId: string;
    term?: string;
    weekNumber?: number;
    noteId?: string;
    fileName?: string;
    pdfData?: string;
  }): Promise<{
    pdfFileUrl?: string;
    pdfStoragePath?: string;
    pdfFileName?: string;
    pdfFileSize?: number;
  } | null> {
    const rawData = String(params.pdfData || '').trim();
    if (!rawData) return null;

    // If pdfData is already an http(s) Supabase Storage URL, return it directly
    if (/^https?:\/\//i.test(rawData)) {
      return {
        pdfFileUrl: rawData,
        pdfFileName: params.fileName || 'LessonNote.pdf'
      };
    }

    await ensureLessonNotesStorageBucket();
    const adminClient = getSupabaseAdmin();

    let base64Body = rawData;
    const base64Idx = rawData.indexOf(';base64,');
    if (base64Idx !== -1) {
      base64Body = rawData.slice(base64Idx + 8);
    } else if (rawData.startsWith('data:')) {
      const commaIdx = rawData.indexOf(',');
      if (commaIdx !== -1) base64Body = rawData.slice(commaIdx + 1);
    }

    let fileBuffer: Buffer;
    try {
      fileBuffer = Buffer.from(base64Body, 'base64');
    } catch {
      return null;
    }
    if (!fileBuffer || fileBuffer.length === 0) return null;

    const cleanSchool = String(params.schoolId || 'school').replace(/[^a-zA-Z0-9_-]/g, '');
    const cleanTerm = String(params.term || 'Term-1').replace(/[^a-zA-Z0-9_-]/g, '-');
    const cleanWeek = `week-${Math.min(20, Math.max(1, Number(params.weekNumber) || 1))}`;
    const safeOriginalName = String(params.fileName || 'Lesson-Note.pdf')
      .replace(/[^a-zA-Z0-9._-]/g, '_')
      .replace(/_{2,}/g, '_');
    const finalName = safeOriginalName.toLowerCase().endsWith('.pdf') ? safeOriginalName : `${safeOriginalName}.pdf`;
    const uniquePrefix = String(params.noteId || Date.now()).replace(/[^a-zA-Z0-9_-]/g, '');
    const objectPath = `${cleanSchool}/${cleanTerm}/${cleanWeek}/${uniquePrefix}-${finalName}`;

    try {
      const { error: upErr } = await adminClient.storage
        .from(LESSON_NOTES_STORAGE_BUCKET)
        .upload(objectPath, fileBuffer, {
          contentType: 'application/pdf',
          upsert: true,
          cacheControl: '3600'
        });

      if (upErr) {
        console.warn('[LessonNotes Storage] Upload warning:', upErr.message);
        return null;
      }

      const { data: pubData } = adminClient.storage
        .from(LESSON_NOTES_STORAGE_BUCKET)
        .getPublicUrl(objectPath);

      return {
        pdfFileUrl: pubData?.publicUrl || undefined,
        pdfStoragePath: objectPath,
        pdfFileName: params.fileName || finalName,
        pdfFileSize: fileBuffer.length
      };
    } catch (err: any) {
      console.warn('[LessonNotes Storage] Upload error:', err?.message);
      return null;
    }
  }

  async function checkPublicLessonNotesTableStatus(): Promise<{
    tableExists: boolean;
    rowCount: number;
    error?: string;
  }> {
    const adminClient = getSupabaseAdmin();
    try {
      const { count, error } = await adminClient
        .from('lesson_notes')
        .select('id', { count: 'exact', head: true });

      if (!error) {
        return { tableExists: true, rowCount: Number(count || 0) };
      }
      return {
        tableExists: false,
        rowCount: 0,
        error: error.message
      };
    } catch (err: any) {
      return {
        tableExists: false,
        rowCount: 0,
        error: err?.message || 'Unable to query public.lesson_notes'
      };
    }
  }

  const normalizeLessonNoteRecord = (raw: any, defaultSchoolId?: string | null) => {
    if (!raw || typeof raw !== 'object') return null;

    const schoolId = String(raw.school_id || raw.schoolId || defaultSchoolId || '').trim();
    const className = String(raw.class || raw.className || 'JHS 1').trim();
    const subject = String(raw.subject || 'Mathematics').trim();
    const term = String(raw.term || 'Term 1').trim();
    const academicYear = String(raw.academic_year || raw.academicYear || '2026/2027').trim();
    const weekNumber = Math.min(14, Math.max(1, Number(raw.week_number ?? raw.weekNumber ?? 1) || 1));
    const teacherName = String(raw.teacher_name || raw.teacherName || 'Subject Teacher').trim();
    const teacherId = String(raw.teacher_id || raw.teacherId || teacherName).trim();

    const rawNoteId = String(raw.note_id || raw.noteId || '').trim();
    const noteId = rawNoteId || `LN-${academicYear.replace(/[^0-9]/g, '').slice(0, 4)}-T${term.replace(/[^0-9]/g, '') || '1'}-W${String(weekNumber).padStart(2, '0')}-${className.replace(/[^a-zA-Z0-9]/g, '')}-${subject.replace(/[^a-zA-Z0-9]/g, '').slice(0, 6).toUpperCase()}-${String(raw.id || Date.now()).slice(-5)}`;

    const lessonDate = String(raw.lesson_date || raw.lessonDate || new Date().toISOString().split('T')[0]).trim();
    const duration = String(raw.duration || '60 mins').trim();
    const classSize = raw.class_size !== undefined || raw.classSize !== undefined
      ? Number(raw.class_size ?? raw.classSize) || 0
      : undefined;

    const strand = String(raw.strand || '').trim();
    const subStrand = String(raw.sub_strand ?? raw.subStrand ?? '').trim();
    const contentStandard = String(raw.content_standard ?? raw.contentStandard ?? '').trim();
    const objectives = String(raw.objectives ?? '').trim();
    const tlms = String(raw.tlms ?? '').trim();
    const coreCompetencies = String(raw.core_competencies ?? raw.coreCompetencies ?? '').trim();
    const starterActivity = String(raw.starter_activity ?? raw.starterActivity ?? '').trim();
    const mainActivity = String(raw.main_activity ?? raw.mainActivity ?? '').trim();
    const plenaryActivity = String(raw.plenary_activity ?? raw.plenaryActivity ?? '').trim();
    const evaluation = String(raw.evaluation ?? '').trim();
    const teacherRemarks = String(raw.teacher_remarks ?? raw.teacherRemarks ?? '').trim();

    const pdfFileName = raw.pdf_file_name || raw.pdfFileName
      ? String(raw.pdf_file_name || raw.pdfFileName).trim()
      : undefined;
    const pdfFileSize = raw.pdf_file_size !== undefined || raw.pdfFileSize !== undefined
      ? Number(raw.pdf_file_size ?? raw.pdfFileSize) || undefined
      : undefined;
    const pdfFileUrl = raw.pdf_file_url || raw.pdfFileUrl
      ? String(raw.pdf_file_url || raw.pdfFileUrl).trim()
      : undefined;
    const pdfStoragePath = raw.pdf_storage_path || raw.pdfStoragePath
      ? String(raw.pdf_storage_path || raw.pdfStoragePath).trim()
      : undefined;
    const rawPdfData = raw.pdf_data || raw.pdfData
      ? String(raw.pdf_data || raw.pdfData)
      : undefined;
    const pdfData = pdfFileUrl || rawPdfData;
    const pdfUploadedAt = raw.pdf_uploaded_at !== undefined || raw.pdfUploadedAt !== undefined
      ? Number(raw.pdf_uploaded_at ?? raw.pdfUploadedAt) || undefined
      : undefined;

    const validStatuses = ['Draft', 'Pending Review', 'Approved', 'Needs Revision', 'Rejected'];
    const rawStatus = String(raw.status || 'Draft').trim();
    const status = (validStatuses.includes(rawStatus) ? rawStatus : 'Draft') as
      | 'Draft'
      | 'Pending Review'
      | 'Approved'
      | 'Needs Revision'
      | 'Rejected';

    const submittedAt = raw.submitted_at !== undefined || raw.submittedAt !== undefined
      ? Number(raw.submitted_at ?? raw.submittedAt) || undefined
      : undefined;
    const reviewedBy = raw.reviewed_by || raw.reviewedBy
      ? String(raw.reviewed_by || raw.reviewedBy).trim()
      : undefined;
    const reviewerRole = raw.reviewer_role || raw.reviewerRole
      ? String(raw.reviewer_role || raw.reviewerRole).trim()
      : undefined;
    const reviewerFeedback = raw.reviewer_feedback !== undefined || raw.reviewerFeedback !== undefined
      ? String(raw.reviewer_feedback ?? raw.reviewerFeedback ?? '').trim()
      : undefined;
    const reviewedAt = raw.reviewed_at !== undefined || raw.reviewedAt !== undefined
      ? Number(raw.reviewed_at ?? raw.reviewedAt) || undefined
      : undefined;

    const now = Date.now();
    const createdAt = Number(raw.created_at ?? raw.createdAt ?? now) || now;
    const updatedAt = Number(raw.updated_at ?? raw.updatedAt ?? now) || now;

    return {
      id: typeof raw.id === 'number' ? raw.id : undefined,
      noteId,
      note_id: noteId,
      schoolId,
      school_id: schoolId,
      teacherId,
      teacher_id: teacherId,
      teacherName,
      teacher_name: teacherName,
      term,
      academicYear,
      academic_year: academicYear,
      weekNumber,
      week_number: weekNumber,
      class: className,
      subject,
      lessonDate,
      lesson_date: lessonDate,
      duration,
      classSize,
      class_size: classSize ?? null,
      strand,
      subStrand,
      sub_strand: subStrand,
      contentStandard,
      content_standard: contentStandard,
      objectives,
      tlms,
      coreCompetencies,
      core_competencies: coreCompetencies,
      starterActivity,
      starter_activity: starterActivity,
      mainActivity,
      main_activity: mainActivity,
      plenaryActivity,
      plenary_activity: plenaryActivity,
      evaluation,
      teacherRemarks,
      teacher_remarks: teacherRemarks,
      pdfFileName,
      pdf_file_name: pdfFileName || null,
      pdfFileSize,
      pdf_file_size: pdfFileSize ?? null,
      pdfFileUrl: pdfFileUrl || (rawPdfData && /^https?:\/\//i.test(rawPdfData) ? rawPdfData : undefined),
      pdf_file_url: pdfFileUrl || (rawPdfData && /^https?:\/\//i.test(rawPdfData) ? rawPdfData : null),
      pdfStoragePath,
      pdf_storage_path: pdfStoragePath || null,
      pdfData,
      pdf_data: pdfData || null,
      pdfUploadedAt,
      pdf_uploaded_at: pdfUploadedAt ?? null,
      status,
      submittedAt,
      submitted_at: submittedAt ?? null,
      reviewedBy,
      reviewed_by: reviewedBy || null,
      reviewerRole,
      reviewer_role: reviewerRole || null,
      reviewerFeedback,
      reviewer_feedback: reviewerFeedback || null,
      reviewedAt,
      reviewed_at: reviewedAt ?? null,
      createdAt,
      created_at: createdAt,
      updatedAt,
      updated_at: updatedAt
    };
  };

  async function readLessonNotesFromSchoolSettings(schoolId: string): Promise<any[]> {
    if (!schoolId) return [];
    const adminClient = getSupabaseAdmin();
    try {
      const { data, error } = await adminClient
        .from('school_settings')
        .select('streams')
        .eq('school_id', schoolId)
        .limit(1)
        .maybeSingle();

      if (!error && data?.streams && typeof data.streams === 'object' && !Array.isArray(data.streams)) {
        const list = (data.streams as any).lesson_notes;
        if (Array.isArray(list)) {
          return list
            .map((item: any) => normalizeLessonNoteRecord(item, schoolId))
            .filter(Boolean);
        }
      }
    } catch {}
    return [];
  }

  async function writeLessonNotesToSchoolSettings(
    schoolId: string,
    notesToMerge: any[],
    noteIdsToRemove?: string[]
  ): Promise<any[]> {
    if (!schoolId) return [];
    const adminClient = getSupabaseAdmin();

    try {
      const { data: existing } = await adminClient
        .from('school_settings')
        .select('*')
        .eq('school_id', schoolId)
        .limit(1)
        .maybeSingle();

      const existingStreams = existing?.streams;
      let streamItems: any[] = [];
      let prevLessonNotes: any[] = [];

      if (Array.isArray(existingStreams)) {
        streamItems = existingStreams;
      } else if (existingStreams && typeof existingStreams === 'object') {
        streamItems = Array.isArray((existingStreams as any).items) ? (existingStreams as any).items : [];
        prevLessonNotes = Array.isArray((existingStreams as any).lesson_notes) ? (existingStreams as any).lesson_notes : [];
      }

      const removeSet = new Set((noteIdsToRemove || []).map(v => String(v).trim()));
      const noteMap = new Map<string, any>();

      for (const prev of prevLessonNotes) {
        const norm = normalizeLessonNoteRecord(prev, schoolId);
        if (!norm) continue;
        if (removeSet.has(norm.noteId) || (norm.id !== undefined && removeSet.has(String(norm.id)))) continue;
        noteMap.set(norm.noteId, norm);
      }

      for (const incoming of (Array.isArray(notesToMerge) ? notesToMerge : [])) {
        const norm = normalizeLessonNoteRecord(incoming, schoolId);
        if (!norm) continue;
        if (removeSet.has(norm.noteId) || (norm.id !== undefined && removeSet.has(String(norm.id)))) continue;
        const prev = noteMap.get(norm.noteId);
        // When PDF is stored in Supabase Storage, keep settings payload lightweight by storing the Storage URL
        const resolvedUrl = norm.pdfFileUrl || prev?.pdfFileUrl;
        noteMap.set(norm.noteId, {
          ...(prev || {}),
          ...norm,
          pdfFileUrl: resolvedUrl,
          pdf_file_url: resolvedUrl || null,
          pdfStoragePath: norm.pdfStoragePath || prev?.pdfStoragePath,
          pdf_storage_path: norm.pdfStoragePath || prev?.pdfStoragePath || null,
          pdfData: resolvedUrl || norm.pdfData || prev?.pdfData,
          pdf_data: resolvedUrl || norm.pdfData || prev?.pdfData || null,
          id: norm.id ?? prev?.id
        });
      }

      const mergedList = Array.from(noteMap.values()).sort(
        (a, b) => Number(b.updatedAt || b.createdAt || 0) - Number(a.updatedAt || a.createdAt || 0)
      );

      const nextStreamsObj = {
        ...(existingStreams && typeof existingStreams === 'object' && !Array.isArray(existingStreams) ? existingStreams : {}),
        items: streamItems,
        lesson_notes: mergedList
      };

      const payload = {
        school_id: schoolId,
        grade_boundaries: existing?.grade_boundaries || [],
        terms: existing?.terms || [],
        streams: nextStreamsObj,
        updated_at: Date.now()
      };

      await adminClient
        .from('school_settings')
        .upsert([payload], { onConflict: 'school_id' });

      return mergedList;
    } catch (err) {
      console.warn('Notice saving lesson notes to school_settings in Supabase:', err);
      return [];
    }
  }

  async function upsertLessonNotesInSupabase(schoolId: string, rawNotes: any[]): Promise<any[]> {
    if (!schoolId) return [];
    const adminClient = getSupabaseAdmin();
    const normalizedInput = (Array.isArray(rawNotes) ? rawNotes : [rawNotes])
      .map(n => normalizeLessonNoteRecord({ ...n, school_id: schoolId }, schoolId))
      .filter(Boolean) as NonNullable<ReturnType<typeof normalizeLessonNoteRecord>>[];

    if (normalizedInput.length === 0) return [];

    // 0. Automatically offload any base64 PDF attachments into the 'lesson-notes' Supabase Storage bucket
    for (const n of normalizedInput) {
      if (n.pdfData && n.pdfData.startsWith('data:') && !n.pdfFileUrl) {
        const uploaded = await uploadLessonNotePdfToStorage({
          schoolId,
          term: n.term,
          weekNumber: n.weekNumber,
          noteId: n.noteId,
          fileName: n.pdfFileName,
          pdfData: n.pdfData
        });
        if (uploaded?.pdfFileUrl) {
          n.pdfFileUrl = uploaded.pdfFileUrl;
          n.pdf_file_url = uploaded.pdfFileUrl;
          n.pdfStoragePath = uploaded.pdfStoragePath;
          n.pdf_storage_path = uploaded.pdfStoragePath || null;
          n.pdfFileName = uploaded.pdfFileName || n.pdfFileName;
          n.pdf_file_name = n.pdfFileName || null;
          n.pdfFileSize = uploaded.pdfFileSize ?? n.pdfFileSize;
          n.pdf_file_size = n.pdfFileSize ?? null;
          n.pdfData = uploaded.pdfFileUrl;
          n.pdf_data = uploaded.pdfFileUrl;
        }
      }
    }

    // 1. Always persist to public.school_settings.streams.lesson_notes in Supabase for guaranteed cross-device persistence
    const settingsSaved = await writeLessonNotesToSchoolSettings(schoolId, normalizedInput);

    // 2. Also persist to public.lesson_notes table in Supabase if present
    const fullDbPayload = normalizedInput.map(n => ({
      school_id: schoolId,
      note_id: n.noteId,
      teacher_id: n.teacherId || null,
      teacher_name: n.teacherName,
      term: n.term,
      academic_year: n.academicYear,
      week_number: n.weekNumber,
      class: n.class,
      subject: n.subject,
      lesson_date: n.lessonDate || null,
      duration: n.duration || '60 mins',
      class_size: n.classSize ?? null,
      strand: n.strand,
      sub_strand: n.subStrand || null,
      content_standard: n.contentStandard || null,
      objectives: n.objectives || null,
      tlms: n.tlms || null,
      core_competencies: n.coreCompetencies || null,
      starter_activity: n.starterActivity || null,
      main_activity: n.mainActivity || null,
      plenary_activity: n.plenaryActivity || null,
      evaluation: n.evaluation || null,
      teacher_remarks: n.teacherRemarks || null,
      pdf_file_name: n.pdfFileName || null,
      pdf_file_size: n.pdfFileSize ?? null,
      pdf_file_url: n.pdfFileUrl || null,
      pdf_storage_path: n.pdfStoragePath || null,
      pdf_data: n.pdfFileUrl || n.pdfData || null,
      pdf_uploaded_at: n.pdfUploadedAt ?? null,
      status: n.status,
      submitted_at: n.submittedAt ?? null,
      reviewed_by: n.reviewedBy || null,
      reviewer_role: n.reviewerRole || null,
      reviewer_feedback: n.reviewerFeedback || null,
      reviewed_at: n.reviewedAt ?? null,
      created_at: n.createdAt,
      updated_at: n.updatedAt
    }));

    try {
      let { data: tableRows, error: tableErr } = await adminClient
        .from('lesson_notes')
        .upsert(fullDbPayload, { onConflict: 'school_id,note_id' })
        .select();

      // Fallback if table exists without pdf_file_url / pdf_storage_path columns yet
      if (tableErr && String(tableErr.message || '').includes('pdf_')) {
        const legacyPayload = fullDbPayload.map(({ pdf_file_url, pdf_storage_path, ...rest }) => rest);
        const retryRes = await adminClient
          .from('lesson_notes')
          .upsert(legacyPayload, { onConflict: 'school_id,note_id' })
          .select();
        tableRows = retryRes.data;
        tableErr = retryRes.error;
      }

      if (!tableErr && Array.isArray(tableRows) && tableRows.length > 0) {
        const normalizedTableRows = tableRows
          .map(r => normalizeLessonNoteRecord(r, schoolId))
          .filter(Boolean);
        await writeLessonNotesToSchoolSettings(schoolId, normalizedTableRows);
        for (const r of normalizedTableRows) {
          saveToFallback('lessonNotes', r);
        }
        return normalizedTableRows;
      }
    } catch {}

    for (const r of normalizedInput) {
      saveToFallback('lessonNotes', r);
    }

    const savedSet = new Set(normalizedInput.map(n => n.noteId));
    return settingsSaved.filter(n => savedSet.has(n.noteId));
  }

  async function backfillAllSchoolsLessonNotesToTable(): Promise<number> {
    const adminClient = getSupabaseAdmin();
    let migratedCount = 0;
    try {
      const { data: settingsRows } = await adminClient
        .from('school_settings')
        .select('school_id, streams');

      if (Array.isArray(settingsRows)) {
        for (const row of settingsRows) {
          const sId = row?.school_id ? String(row.school_id) : '';
          const list = row?.streams && typeof row.streams === 'object' && !Array.isArray(row.streams)
            ? (row.streams as any).lesson_notes
            : null;
          if (sId && Array.isArray(list) && list.length > 0) {
            const res = await upsertLessonNotesInSupabase(sId, list);
            migratedCount += res.length;
          }
        }
      }
    } catch {}
    return migratedCount;
  }

  async function fetchSchoolLessonNotesFromSupabase(
    schoolId: string,
    filters?: {
      term?: string;
      weekNumber?: number;
      className?: string;
      subject?: string;
      teacherId?: string;
      status?: string;
    }
  ): Promise<any[]> {
    if (!schoolId) return [];
    const adminClient = getSupabaseAdmin();

    const [tableQuery, settingsNotes] = await Promise.all([
      (async () => {
        try {
          const { data, error } = await adminClient
            .from('lesson_notes')
            .select('*')
            .eq('school_id', schoolId)
            .order('updated_at', { ascending: false });
          if (!error && Array.isArray(data)) {
            return data.map(r => normalizeLessonNoteRecord(r, schoolId)).filter(Boolean);
          }
        } catch {}
        return [];
      })(),
      readLessonNotesFromSchoolSettings(schoolId)
    ]);

    const noteMap = new Map<string, any>();
    for (const sn of settingsNotes) {
      if (sn?.noteId) noteMap.set(sn.noteId, sn);
    }
    for (const tn of tableQuery) {
      if (!tn?.noteId) continue;
      const prev = noteMap.get(tn.noteId);
      if (!prev || Number(tn.updatedAt || 0) >= Number(prev.updatedAt || 0)) {
        const mergedPdfUrl = tn.pdfFileUrl || prev?.pdfFileUrl;
        noteMap.set(tn.noteId, {
          ...(prev || {}),
          ...tn,
          pdfFileUrl: mergedPdfUrl,
          pdf_file_url: mergedPdfUrl || null,
          pdfStoragePath: tn.pdfStoragePath || prev?.pdfStoragePath,
          pdf_storage_path: tn.pdfStoragePath || prev?.pdfStoragePath || null,
          pdfData: mergedPdfUrl || tn.pdfData || prev?.pdfData,
          pdfFileName: tn.pdfFileName || prev?.pdfFileName,
          pdfFileSize: tn.pdfFileSize ?? prev?.pdfFileSize
        });
      }
    }

    let combined = Array.from(noteMap.values()).sort(
      (a, b) => Number(b.updatedAt || b.createdAt || 0) - Number(a.updatedAt || a.createdAt || 0)
    );

    if (filters?.term && filters.term !== 'All') {
      const targetTerm = filters.term.trim().toLowerCase();
      combined = combined.filter(n => String(n.term || '').trim().toLowerCase() === targetTerm);
    }
    if (filters?.weekNumber !== undefined && filters.weekNumber !== null && Number(filters.weekNumber) > 0) {
      combined = combined.filter(n => Number(n.weekNumber) === Number(filters.weekNumber));
    }
    if (filters?.className && filters.className !== 'All') {
      const targetClass = filters.className.trim().toLowerCase();
      combined = combined.filter(n => String(n.class || '').trim().toLowerCase() === targetClass);
    }
    if (filters?.subject && filters.subject !== 'All') {
      const targetSubject = filters.subject.trim().toLowerCase();
      combined = combined.filter(n => String(n.subject || '').trim().toLowerCase() === targetSubject);
    }
    if (filters?.teacherId && filters.teacherId !== 'All') {
      const targetTeacher = filters.teacherId.trim().toLowerCase();
      combined = combined.filter(
        n =>
          String(n.teacherId || '').trim().toLowerCase() === targetTeacher ||
          String(n.teacherName || '').trim().toLowerCase() === targetTeacher
      );
    }
    if (filters?.status && filters.status !== 'All') {
      const targetStatus = filters.status.trim().toLowerCase();
      combined = combined.filter(n => String(n.status || '').trim().toLowerCase() === targetStatus);
    }

    // If public.lesson_notes exists and has fewer rows than settingsNotes, automatically backfill missing notes into public.lesson_notes
    if (settingsNotes.length > 0 && tableQuery.length < settingsNotes.length) {
      const tableIds = new Set(tableQuery.map(t => t?.noteId).filter(Boolean));
      const missingInTable = settingsNotes.filter(s => s?.noteId && !tableIds.has(s.noteId));
      if (missingInTable.length > 0) {
        void upsertLessonNotesInSupabase(schoolId, missingInTable).catch(() => {});
      }
    }

    return combined;
  }

  // POST /api/lesson-notes/upload-pdf - Upload teacher lesson note PDF directly to Supabase Storage bucket
  app.post("/api/lesson-notes/upload-pdf", authenticateToken, async (req: AuthenticatedRequest, res) => {
    try {
      const userRole = String(req.user?.role || '').toLowerCase();
      if (userRole === 'parent' || userRole === 'student') {
        return res.status(403).json({
          success: false,
          error: "Students and parents are not permitted to upload lesson note PDFs."
        });
      }

      const schoolId = (await resolveResultsSchoolId(req)) || 'default-school';
      const body = req.body || {};
      const fileName = String(body.fileName || body.pdfFileName || 'Lesson-Note.pdf').trim();
      const pdfData = String(body.pdfBase64 || body.pdfData || body.dataUrl || '').trim();
      const term = String(body.term || 'Term 1').trim();
      const weekNumber = Number(body.weekNumber || body.week_number || 1) || 1;
      const noteId = String(body.noteId || body.note_id || `LN-${Date.now()}`).trim();

      if (!pdfData) {
        return res.status(400).json({ success: false, error: "Missing PDF file payload." });
      }

      const uploaded = await uploadLessonNotePdfToStorage({
        schoolId,
        term,
        weekNumber,
        noteId,
        fileName,
        pdfData
      });

      if (!uploaded?.pdfFileUrl) {
        return res.status(500).json({
          success: false,
          error: "Failed to upload PDF to Supabase Storage bucket."
        });
      }

      return res.status(201).json({
        success: true,
        bucket: LESSON_NOTES_STORAGE_BUCKET,
        pdfFileName: uploaded.pdfFileName,
        pdfFileSize: uploaded.pdfFileSize,
        pdfFileUrl: uploaded.pdfFileUrl,
        pdfStoragePath: uploaded.pdfStoragePath,
        pdfUploadedAt: Date.now()
      });
    } catch (err: any) {
      if (isTenantAccessError(err)) {
        return res.status(err.statusCode).json({ success: false, error: err.message });
      }
      return res.status(500).json({ success: false, error: sanitizeErrorMessage(err) });
    }
  });

  // GET /api/lesson-notes - Fetch lesson notes and PDF attachments from Supabase
